package gnotask

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
)

const (
	StatusOpen             = "Open"
	StatusClaimed          = "Claimed"
	StatusSubmitted        = "Submitted"
	StatusChangesRequested = "ChangesRequested"
	StatusPaid             = "Paid"
	StatusRefunded         = "Refunded"
	StatusCancelled        = "Cancelled"

	NativeRewardDenom       = "ugnot"
	MinReviewWindowSeconds  = int64(60 * 60)
	MaxReviewWindowSeconds  = int64(30 * 24 * 60 * 60)
)

// Task is the authoritative escrow record. Descriptions, GitHub evidence,
// search metadata, and private operational data remain off-chain.
type Task struct {
	ID                  string
	Sponsor             address
	Contributor         address
	SpecHash            string
	RewardAmount        int64
	RewardDenom         string
	DeliveryDueAt       time.Time
	ReviewWindowSeconds int64
	ReviewDeadline      time.Time
	Status              string
	RevisionRequests    int
	EvidenceHash        string
	ReviewHash          string
	Escrowed            bool
	ReleaseReason       string
}

var (
	tasks   = make(map[string]*Task)
	taskIDs []string
)

// A direct MsgCall is required anywhere an address authorizes a state change.
// IsUserCall deliberately rejects intermediate code and user-run ephemeral
// realms, which is required when unsafe.OriginSend is treated as a receipt.
func requireDirectUser(cur realm) address {
	previous := cur.Previous()
	if !previous.IsUserCall() {
		panic("direct user call required")
	}
	return previous.Address()
}

func requireTask(taskID string) *Task {
	task := tasks[taskID]
	if task == nil {
		panic("task not found")
	}
	return task
}

func requireSponsor(task *Task, caller address) {
	if task.Sponsor != caller {
		panic("only sponsor")
	}
}

func requireContributor(task *Task, caller address) {
	if task.Contributor != caller {
		panic("only selected contributor")
	}
}

func requireTaskID(taskID string) {
	if len(taskID) == 0 || len(taskID) > 64 {
		panic("invalid task id")
	}
	for index := 0; index < len(taskID); index++ {
		char := taskID[index]
		valid := char >= 'a' && char <= 'z' || char >= '0' && char <= '9' || char == '-' || char == '_'
		if !valid {
			panic("invalid task id")
		}
	}
}

func requireHash(value, field string) {
	if len(value) != 64 {
		panic(field + " must be a lowercase sha256 hash")
	}
	for index := 0; index < len(value); index++ {
		char := value[index]
		if !(char >= '0' && char <= '9' || char >= 'a' && char <= 'f') {
			panic(field + " must be a lowercase sha256 hash")
		}
	}
}

func requireExactEscrow(rewardAmount int64, rewardDenom string) {
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != rewardDenom || sent[0].Amount != rewardAmount {
		panic("exact reward must be attached")
	}
}

func settleEscrow(cur realm, task *Task, recipient address, reason, terminalStatus string) {
	if !task.Escrowed {
		panic("reward is not escrowed")
	}
	task.Escrowed = false
	task.ReleaseReason = reason
	task.Status = terminalStatus
	coins := chain.Coins{{Denom: task.RewardDenom, Amount: task.RewardAmount}}
	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(cur.Address(), recipient, coins)
}

// CreateTask locks the exact GNOT reward attached to this direct transaction.
// No Task becomes Open from a URL, promise, or off-chain balance screenshot.
func CreateTask(
	cur realm,
	taskID string,
	specHash string,
	rewardAmount int64,
	rewardDenom string,
	deliveryDueUnix int64,
	reviewWindowSeconds int64,
) {
	sponsor := requireDirectUser(cur)
	requireTaskID(taskID)
	if tasks[taskID] != nil {
		panic("task already exists")
	}
	requireHash(specHash, "spec hash")
	if rewardAmount <= 0 {
		panic("reward must be positive")
	}
	if rewardDenom != NativeRewardDenom {
		panic("only ugnot rewards are supported")
	}
	if deliveryDueUnix <= time.Now().Unix() {
		panic("delivery deadline must be in the future")
	}
	if reviewWindowSeconds < MinReviewWindowSeconds || reviewWindowSeconds > MaxReviewWindowSeconds {
		panic("invalid review window")
	}
	requireExactEscrow(rewardAmount, rewardDenom)

	tasks[taskID] = &Task{
		ID:                  taskID,
		Sponsor:             sponsor,
		SpecHash:            specHash,
		RewardAmount:        rewardAmount,
		RewardDenom:         rewardDenom,
		DeliveryDueAt:       time.Unix(deliveryDueUnix, 0),
		ReviewWindowSeconds: reviewWindowSeconds,
		Status:              StatusOpen,
		Escrowed:            true,
	}
	taskIDs = append(taskIDs, taskID)
	chain.Emit("TaskCreated",
		"task_id", taskID,
		"sponsor", sponsor.String(),
		"spec_hash", specHash,
	)
	chain.Emit("FundingLocked",
		"task_id", taskID,
		"amount", strconv.FormatInt(rewardAmount, 10),
		"denom", rewardDenom,
		"delivery_due_unix", strconv.FormatInt(deliveryDueUnix, 10),
	)
}

// CancelOpenTask returns the full escrow while nobody has been selected.
func CancelOpenTask(cur realm, taskID string) {
	caller := requireDirectUser(cur)
	task := requireTask(taskID)
	requireSponsor(task, caller)
	if task.Status != StatusOpen {
		panic("only an open task can be cancelled")
	}
	settleEscrow(cur, task, task.Sponsor, "sponsor_cancelled", StatusCancelled)
	chain.Emit("TaskCancelled", "task_id", taskID)
	chain.Emit("RewardRefunded", "task_id", taskID, "reason", task.ReleaseReason)
}

// SelectContributor records the one contributor chosen through the off-chain
// application flow. The reward remains in the Realm.
func SelectContributor(cur realm, taskID string, contributor address) {
	caller := requireDirectUser(cur)
	task := requireTask(taskID)
	requireSponsor(task, caller)
	if task.Status != StatusOpen {
		panic("task is not open")
	}
	if !contributor.IsValid() || contributor == caller {
		panic("invalid contributor")
	}
	task.Contributor = contributor
	task.Status = StatusClaimed
	chain.Emit("ContributorSelected",
		"task_id", taskID,
		"contributor", contributor.String(),
	)
}

// SubmitEvidence anchors a canonical hash and starts the on-chain review timer.
func SubmitEvidence(cur realm, taskID, evidenceHash string) {
	caller := requireDirectUser(cur)
	task := requireTask(taskID)
	requireContributor(task, caller)
	if task.Status != StatusClaimed && task.Status != StatusChangesRequested {
		panic("task does not accept evidence")
	}
	now := time.Now()
	if task.Status == StatusClaimed && !now.Before(task.DeliveryDueAt) {
		panic("delivery deadline reached")
	}
	if task.Status == StatusChangesRequested && (task.ReviewDeadline.IsZero() || !now.Before(task.ReviewDeadline)) {
		panic("revision deadline reached")
	}
	requireHash(evidenceHash, "evidence hash")
	task.EvidenceHash = evidenceHash
	task.ReviewDeadline = now.Add(time.Duration(task.ReviewWindowSeconds) * time.Second)
	task.Status = StatusSubmitted
	chain.Emit("WorkSubmitted",
		"task_id", taskID,
		"contributor", caller.String(),
		"evidence_hash", evidenceHash,
		"review_deadline_unix", strconv.FormatInt(task.ReviewDeadline.Unix(), 10),
	)
}

// Review either requests the one allowed revision or atomically accepts and
// releases the escrow to the selected Contributor.
func Review(cur realm, taskID string, accept bool, reviewHash string) {
	caller := requireDirectUser(cur)
	task := requireTask(taskID)
	requireSponsor(task, caller)
	if task.Status != StatusSubmitted {
		panic("task is not submitted")
	}
	requireHash(reviewHash, "review hash")
	now := time.Now()
	if !accept && (task.ReviewDeadline.IsZero() || !now.Before(task.ReviewDeadline)) {
		panic("review deadline reached")
	}
	task.ReviewHash = reviewHash
	if accept {
		settleEscrow(cur, task, task.Contributor, "sponsor_accepted", StatusPaid)
		chain.Emit("TaskAccepted", "task_id", taskID, "review_hash", reviewHash)
		chain.Emit("RewardReleased",
			"task_id", taskID,
			"contributor", task.Contributor.String(),
			"reason", task.ReleaseReason,
		)
		return
	}
	if task.RevisionRequests >= 1 {
		panic("revision limit reached")
	}
	task.RevisionRequests++
	// The same bounded window now becomes the Contributor's revision window.
	task.ReviewDeadline = now.Add(time.Duration(task.ReviewWindowSeconds) * time.Second)
	task.Status = StatusChangesRequested
	chain.Emit("ChangesRequested", "task_id", taskID, "review_hash", reviewHash)
}

// ClaimAfterReviewDeadline protects a Contributor from an absent Sponsor.
func ClaimAfterReviewDeadline(cur realm, taskID string) {
	caller := requireDirectUser(cur)
	task := requireTask(taskID)
	requireContributor(task, caller)
	if task.Status != StatusSubmitted {
		panic("task is not awaiting review")
	}
	if task.ReviewDeadline.IsZero() || time.Now().Before(task.ReviewDeadline) {
		panic("review deadline not reached")
	}
	settleEscrow(cur, task, task.Contributor, "review_timeout", StatusPaid)
	chain.Emit("RewardReleased",
		"task_id", taskID,
		"contributor", task.Contributor.String(),
		"reason", task.ReleaseReason,
	)
}

// RefundExpiredTask returns the escrow when the selected Contributor misses
// either the initial delivery deadline or the bounded revision deadline.
// Submitted work is protected by the review timer and cannot use this path.
func RefundExpiredTask(cur realm, taskID string) {
	caller := requireDirectUser(cur)
	task := requireTask(taskID)
	requireSponsor(task, caller)
	if task.Status != StatusClaimed && task.Status != StatusChangesRequested {
		panic("task is not refundable after delivery timeout")
	}
	deadline := task.DeliveryDueAt
	if task.Status == StatusChangesRequested {
		deadline = task.ReviewDeadline
	}
	if deadline.IsZero() || time.Now().Before(deadline) {
		panic("delivery deadline not reached")
	}
	settleEscrow(cur, task, task.Sponsor, "delivery_timeout", StatusRefunded)
	chain.Emit("RewardRefunded", "task_id", taskID, "reason", task.ReleaseReason)
}

func TaskCount() int {
	return len(taskIDs)
}

func GetTask(taskID string) (
	string,
	address,
	address,
	string,
	string,
	int64,
	string,
	int64,
	int64,
	int64,
	int,
	string,
	string,
	bool,
	string,
) {
	task := requireTask(taskID)
	reviewDeadlineUnix := int64(0)
	if !task.ReviewDeadline.IsZero() {
		reviewDeadlineUnix = task.ReviewDeadline.Unix()
	}
	return task.ID,
		task.Sponsor,
		task.Contributor,
		task.Status,
		task.SpecHash,
		task.RewardAmount,
		task.RewardDenom,
		task.DeliveryDueAt.Unix(),
		task.ReviewWindowSeconds,
		reviewDeadlineUnix,
		task.RevisionRequests,
		task.EvidenceHash,
		task.ReviewHash,
		task.Escrowed,
		task.ReleaseReason
}

// GetTaskState is a compact, query-friendly representation for off-chain
// indexers. Every field is constrained so the pipe delimiter is unambiguous.
func GetTaskState(taskID string) string {
	task := requireTask(taskID)
	contributor := ""
	if task.Contributor.IsValid() {
		contributor = task.Contributor.String()
	}
	reviewDeadlineUnix := int64(0)
	if !task.ReviewDeadline.IsZero() {
		reviewDeadlineUnix = task.ReviewDeadline.Unix()
	}
	return strings.Join([]string{
		task.ID,
		task.Sponsor.String(),
		contributor,
		task.Status,
		task.SpecHash,
		strconv.FormatInt(task.RewardAmount, 10),
		task.RewardDenom,
		strconv.FormatInt(task.DeliveryDueAt.Unix(), 10),
		strconv.FormatInt(task.ReviewWindowSeconds, 10),
		strconv.FormatInt(reviewDeadlineUnix, 10),
		strconv.Itoa(task.RevisionRequests),
		task.EvidenceHash,
		task.ReviewHash,
		strconv.FormatBool(task.Escrowed),
		task.ReleaseReason,
	}, "|")
}

func Render(path string) string {
	taskID := strings.TrimPrefix(path, "/")
	if taskID == "" {
		return "# GnoTask\n\nGNOT-escrowed open-source work.\n\nOn-chain Tasks: **" + strconv.Itoa(len(taskIDs)) + "**"
	}
	task := requireTask(taskID)
	contributor := "Not selected"
	if task.Contributor.IsValid() {
		contributor = task.Contributor.String()
	}
	escrow := "Released"
	if task.Escrowed {
		escrow = "Locked in Realm"
	}
	return "# Task `" + task.ID + "`\n\n" +
		"- Status: **" + task.Status + "**\n" +
		"- Escrow: **" + escrow + "**\n" +
		"- Sponsor: `" + task.Sponsor.String() + "`\n" +
		"- Contributor: `" + contributor + "`\n" +
		"- Reward: **" + strconv.FormatInt(task.RewardAmount, 10) + " " + task.RewardDenom + "**\n" +
		"- Delivery deadline: `" + task.DeliveryDueAt.Format(time.RFC3339) + "`\n" +
		"- Spec hash: `" + task.SpecHash + "`"
}

package grc721

import (
	"chain"
	"math/overflow"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

type BasicNFT struct {
	name              string
	symbol            string
	origRealm         string   // owning realm's package path
	owners            avl.Tree // tokenId -> OwnerAddress
	balances          avl.Tree // OwnerAddress -> TokenCount
	tokenApprovals    avl.Tree // TokenId -> ApprovedAddress
	tokenURIs         avl.Tree // TokenId -> URIs
	operatorApprovals avl.Tree // "OwnerAddress:OperatorAddress" -> bool
}

func NewBasicNFT(_ int, rlm realm, name, symbol string) *BasicNFT {
	if !rlm.IsCurrent() {
		panic(ErrSpoofedRealm)
	}
	pkgPath := rlm.PkgPath()
	if pkgPath == "" {
		panic(ErrNotRealm)
	}
	if !validName(name) {
		panic(ErrInvalidName)
	}
	if !validSymbol(symbol) {
		panic(ErrInvalidSymbol)
	}

	return &BasicNFT{
		name:      name,
		symbol:    symbol,
		origRealm: pkgPath,

		owners:            avl.Tree{},
		balances:          avl.Tree{},
		tokenApprovals:    avl.Tree{},
		tokenURIs:         avl.Tree{},
		operatorApprovals: avl.Tree{},
	}
}

func (s *BasicNFT) Name() string      { return s.name }
func (s *BasicNFT) Symbol() string    { return s.symbol }
func (s *BasicNFT) TokenCount() int64 { return int64(s.owners.Size()) }

func (s *BasicNFT) ID() string {
	return s.origRealm + "." + s.symbol
}

// BalanceOf returns balance of input address
func (s *BasicNFT) BalanceOf(addr address) (int64, error) {
	if err := isValidAddress(addr); err != nil {
		return 0, err
	}

	balance := s.balances.Get(addr.String())
	if balance == nil {
		return 0, nil
	}

	return balance.(int64), nil
}

// OwnerOf returns owner of input token id
func (s *BasicNFT) OwnerOf(tid TokenID) (address, error) {
	owner := s.owners.Get(string(tid))
	if owner == nil {
		return "", ErrInvalidTokenId
	}

	return owner.(address), nil
}

// TokenURI returns the URI of input token id
func (s *BasicNFT) TokenURI(tid TokenID) (string, error) {
	uri := s.tokenURIs.Get(tid.String())
	if uri == nil {
		return "", ErrInvalidTokenId
	}

	return uri.(string), nil
}

// SetTokenURI sets the URI of a token. caller must equal the token's
// owner. The owning realm's public wrapper is responsible for deriving
// caller from rlm.Previous().Address() under an rlm.IsCurrent() guard
// before invoking this method; this method trusts the supplied caller.
func (s *BasicNFT) SetTokenURI(caller address, tid TokenID, tURI TokenURI) (bool, error) {
	// check for invalid TokenID
	if !s.exists(tid) {
		return false, ErrInvalidTokenId
	}

	// check for the right owner
	owner, err := s.OwnerOf(tid)
	if err != nil {
		return false, err
	}
	if caller != owner {
		return false, ErrCallerIsNotOwner
	}
	s.tokenURIs.Set(tid.String(), tURI.String())

	chain.Emit(
		TokenURIUpdateEvent,
		"token", s.ID(),
		"tokenId", tid.String(),
	)

	return true, nil
}

// IsApprovedForAll returns true if operator is approved for all by the owner.
// Otherwise, returns false
func (s *BasicNFT) IsApprovedForAll(owner, operator address) bool {
	key := owner.String() + ":" + operator.String()
	approved := s.operatorApprovals.Get(key)
	if approved == nil {
		return false
	}

	return approved.(bool)
}

// Approve approves the input address for a particular token. caller
// must be the owner OR an operator approved for all on owner's behalf.
// The owning realm's wrapper validates IsCurrent and derives caller
// from rlm.Previous().Address() before calling.
func (s *BasicNFT) Approve(caller, to address, tid TokenID) error {
	if err := isValidAddress(to); err != nil {
		return err
	}

	owner, err := s.OwnerOf(tid)
	if err != nil {
		return err
	}
	if owner == to {
		return ErrApprovalToCurrentOwner
	}

	if caller != owner && !s.IsApprovedForAll(owner, caller) {
		return ErrCallerIsNotOwnerOrApproved
	}

	tidStr := tid.String()
	s.tokenApprovals.Set(tidStr, to)

	chain.Emit(
		ApprovalEvent,
		"token", s.ID(),
		"owner", owner.String(),
		"to", to.String(),
		"tokenId", tidStr,
	)

	return nil
}

// GetApproved return the approved address for token
func (s *BasicNFT) GetApproved(tid TokenID) (address, error) {
	addr := s.tokenApprovals.Get(tid.String())
	if addr == nil {
		return zeroAddress, ErrTokenIdNotHasApproved
	}

	return addr.(address), nil
}

// SetApprovalForAll grants/revokes operator permission across all of
// the caller's tokens. caller is the owner whose approvals are mutated;
// the owning realm's wrapper derives it from rlm.Previous().Address()
// under an IsCurrent() guard.
func (s *BasicNFT) SetApprovalForAll(caller, operator address, approved bool) error {
	if err := isValidAddress(operator); err != nil {
		return ErrInvalidAddress
	}
	return s.setApprovalForAll(caller, operator, approved)
}

// SafeTransferFrom transfers a token from `from` to `to`, checking that
// contract recipients are aware of the GRC721 protocol to prevent
// tokens from being forever locked. caller must be the owner or an
// approved operator. The owning realm's wrapper derives caller from
// rlm.Previous().Address() under an IsCurrent() guard.
func (s *BasicNFT) SafeTransferFrom(caller, from, to address, tid TokenID) error {
	if !s.isApprovedOrOwner(caller, tid) {
		return ErrCallerIsNotOwnerOrApproved
	}

	err := s.transfer(from, to, tid)
	if err != nil {
		return err
	}

	if !s.checkOnGRC721Received(from, to, tid) {
		return ErrTransferToNonGRC721Receiver
	}

	return nil
}

// TransferFrom transfers a token from `from` to `to`. Same caller
// contract as SafeTransferFrom.
func (s *BasicNFT) TransferFrom(caller, from, to address, tid TokenID) error {
	if !s.isApprovedOrOwner(caller, tid) {
		return ErrCallerIsNotOwnerOrApproved
	}

	err := s.transfer(from, to, tid)
	if err != nil {
		return err
	}

	return nil
}

// Mints `tokenId` and transfers it to `to`.
func (s *BasicNFT) Mint(to address, tid TokenID) error {
	return s.mint(to, tid)
}

// Mints `tokenId` and transfers it to `to`. Also checks that
// contract recipients are using GRC721 protocol
func (s *BasicNFT) SafeMint(to address, tid TokenID) error {
	err := s.mint(to, tid)
	if err != nil {
		return err
	}

	if !s.checkOnGRC721Received(zeroAddress, to, tid) {
		return ErrTransferToNonGRC721Receiver
	}

	return nil
}

func (s *BasicNFT) Burn(tid TokenID) error {
	owner, err := s.OwnerOf(tid)
	if err != nil {
		return err
	}

	s.beforeTokenTransfer(owner, zeroAddress, tid, 1)

	tidStr := tid.String()
	s.tokenApprovals.Remove(tidStr)
	balance, err := s.BalanceOf(owner)
	if err != nil {
		return err
	}
	balance = overflow.Sub64p(balance, 1)

	ownerStr := owner.String()
	s.balances.Set(ownerStr, balance)
	s.owners.Remove(tidStr)

	chain.Emit(
		BurnEvent,
		"token", s.ID(),
		"from", ownerStr,
		"tokenId", tidStr,
	)

	s.afterTokenTransfer(owner, zeroAddress, tid, 1)

	return nil
}

/* Helper methods */

// Helper for SetApprovalForAll()
func (s *BasicNFT) setApprovalForAll(owner, operator address, approved bool) error {
	if owner == operator {
		return ErrApprovalToCurrentOwner
	}

	key := owner.String() + ":" + operator.String()
	s.operatorApprovals.Set(key, approved)

	chain.Emit(
		ApprovalForAllEvent,
		"token", s.ID(),
		"owner", owner.String(),
		"to", operator.String(),
		"approved", strconv.FormatBool(approved),
	)

	return nil
}

// Helper for TransferFrom() and SafeTransferFrom()
func (s *BasicNFT) transfer(from, to address, tid TokenID) error {
	if err := isValidAddress(from); err != nil {
		return ErrInvalidAddress
	}
	if err := isValidAddress(to); err != nil {
		return ErrInvalidAddress
	}

	if from == to {
		return ErrCannotTransferToSelf
	}

	owner, err := s.OwnerOf(tid)
	if err != nil {
		return err
	}
	if owner != from {
		return ErrTransferFromIncorrectOwner
	}

	s.beforeTokenTransfer(from, to, tid, 1)

	// Check that tokenId was not transferred by `beforeTokenTransfer`
	owner, err = s.OwnerOf(tid)
	if err != nil {
		return err
	}
	if owner != from {
		return ErrTransferFromIncorrectOwner
	}

	tidStr := tid.String()
	s.tokenApprovals.Remove(tidStr)
	fromBalance, err := s.BalanceOf(from)
	if err != nil {
		return err
	}
	toBalance, err := s.BalanceOf(to)
	if err != nil {
		return err
	}
	fromBalance = overflow.Sub64p(fromBalance, 1)
	toBalance = overflow.Add64p(toBalance, 1)

	fromStr := from.String()
	toStr := to.String()

	s.balances.Set(fromStr, fromBalance)
	s.balances.Set(toStr, toBalance)
	s.owners.Set(tidStr, to)

	chain.Emit(
		TransferEvent,
		"token", s.ID(),
		"from", fromStr,
		"to", toStr,
		"tokenId", tidStr,
	)

	s.afterTokenTransfer(from, to, tid, 1)

	return nil
}

// Helper for Mint() and SafeMint()
func (s *BasicNFT) mint(to address, tid TokenID) error {
	if err := isValidAddress(to); err != nil {
		return err
	}

	if s.exists(tid) {
		return ErrTokenIdAlreadyExists
	}

	s.beforeTokenTransfer(zeroAddress, to, tid, 1)

	// Check that tokenId was not minted by `beforeTokenTransfer`
	if s.exists(tid) {
		return ErrTokenIdAlreadyExists
	}

	toBalance, err := s.BalanceOf(to)
	if err != nil {
		return err
	}
	toBalance = overflow.Add64p(toBalance, 1)
	toStr := to.String()
	tidStr := tid.String()
	s.balances.Set(toStr, toBalance)
	s.owners.Set(tidStr, to)

	chain.Emit(
		MintEvent,
		"token", s.ID(),
		"to", toStr,
		"tokenId", tidStr,
	)

	s.afterTokenTransfer(zeroAddress, to, tid, 1)

	return nil
}

func (s *BasicNFT) isApprovedOrOwner(addr address, tid TokenID) bool {
	owner := s.owners.Get(tid.String())
	if owner == nil {
		return false
	}

	ownerAddr := owner.(address)
	if addr == ownerAddr || s.IsApprovedForAll(ownerAddr, addr) {
		return true
	}

	approved, err := s.GetApproved(tid)
	if err != nil {
		return false
	}

	return approved == addr
}

