		buf = strconv.AppendUint(buf[:0], rem.Uint64(), 10)
		copy(out[pos-len(buf):], buf)
		if y.IsZero() {
			break
		}
		pos -= 19
	}

	var res string
	if s < 0 {
		res = "-"
	}
	res += string(out[pos-len(buf):])
	return res
}

func (z *Int) SetString(s string) (*Int, error) {
	if len(s) == 0 {
		return nil, errors.New("int256: empty string")
	}

	isNeg := false
	switch s[0] {
	case '+':
		s = s[1:]
	case '-':
		isNeg = true
		s = s[1:]
	}

	if len(s) == 0 {
		return nil, errors.New("int256: empty string")
	}

	// Parallel comparison technique for validation
	// Process in 8-byte chunks for optimal performance
	sLen := len(s)
	i := 0

	// Process 8 bytes at a time
	for i+7 < sLen {
		// Access up to s[i+7] is safe, then we can reduce the number of bounds checks
		_ = s[i+7]

		// Convert 8 bytes into a single uint64
		// This method processes bytes directly, so no endianness issues
		chunk := uint64(s[i]) | uint64(s[i+1])<<8
		chunk |= uint64(s[i+2])<<16 | uint64(s[i+3])<<24
		chunk |= uint64(s[i+4])<<32 | uint64(s[i+5])<<40
		chunk |= uint64(s[i+6])<<48 | uint64(s[i+7])<<56

		// Check for '+' (0x2B) using SWAR technique
		// Subtracting 0x2B from each byte makes '+' bytes become 0
		// Subtracting 0x01 makes bytes in ASCII range (0-127) have 0 in their highest bit
		// Therefore, AND with 0x80 to check for zero bytes
		plusTest := ((chunk ^ 0x2B2B2B2B2B2B2B2B) - 0x0101010101010101) & 0x8080808080808080

		// Check for '-' (0x2D) using SWAR technique
		minusTest := ((chunk ^ 0x2D2D2D2D2D2D2D2D) - 0x0101010101010101) & 0x8080808080808080

		// If either test is non-zero, a sign character exists
		if (plusTest | minusTest) != 0 {
			return nil, errors.New("int256: invalid sign in middle of number")
		}

		i += 8
	}

	// Process remaining bytes
	for ; i < sLen; i++ {
		if s[i] == '+' || s[i] == '-' {
			return nil, errors.New("int256: invalid sign in middle of number")
		}
	}

	// Strip leading zeros
	if len(s) > 0 && s[0] == '0' {
		idx := 0
		for idx < len(s) && s[idx] == '0' {
			idx++
		}
		s = s[idx:]
		// If all characters were zeros, set to "0"
		if len(s) == 0 {
			s = "0"
		}
	}

	// Check for overflow
	if len(s) > len(maxAbsI256Dec) ||
		(len(s) == len(maxAbsI256Dec) && s > maxAbsI256Dec) ||
		(s == maxAbsI256Dec && !isNeg) {
		return nil, errors.New("int256: overflow")
	}

	if err := z.fromDecimal(s); err != nil {
		return nil, err
	}

	if isNeg {
		z.Neg(z)
	}

	return z, nil
}

func (z *Int) fromDecimal(bs string) error {
	z.Clear()
	var (
		num       uint64
		err       error
		remaining = len(bs)
	)

	if remaining == 0 {
		return errors.New("EOF")
	}

	for i, mult := range _multipliers {
		if remaining <= 0 {
			return nil
		}
		if remaining > 19 {
			num, err = strconv.ParseUint(bs[remaining-19:remaining], 10, 64)
		} else {
			num, err = strconv.ParseUint(bs, 10, 64)
		}
		if err != nil {
			return err
		}
		if i == 0 {
			z.SetUint64(num)
		} else {
			base := new(Int).SetUint64(num)
			z.Add(z, base.Mul(base, mult))
		}
		if remaining > 19 {
			bs = bs[0 : remaining-19]
		}
		remaining -= 19
	}
	return nil
}

// FromUint256 converts a uint256 to int256.
// Panics if the uint256 value is greater than MaxInt256 (2^255 - 1).
func FromUint256(x *u256.Uint) *Int {
	// Check overflow: if MSB of x[3] is set, value > MaxInt256
	if x[3] > 0x7fffffffffffffff {
		panic("int256: overflow - uint256 value exceeds MaxInt256")
	}
	z := &Int{}
	z[0] = x[0]
	z[1] = x[1]
	z[2] = x[2]
	z[3] = x[3]
	return z
}

// Package int256 implements 256-bit signed integer arithmetic for GnoSwap.
//
// This package provides an Int type that represents a 256-bit signed integer
// using two's complement representation. It supports the full range from
// -(2^255) to 2^255-1, with arithmetic operations that detect overflow.
//
// The implementation follows Ethereum's int256 semantics, ensuring compatibility
// for cross-chain DeFi protocols. Operations are optimized for common AMM
// calculations including tick math and price computations.
//
// Critical operations like Add, Sub, and Mul return overflow flags, enabling
// safe handling of edge cases in financial calculations.
package int256

package int256

import (
	"encoding/binary"
	"math"
	"math/bits"

	u256 "gno.land/p/gnoswap/uint256"
)

type Int [4]uint64

func Zero() *Int {
	return &Int{}
}

func One() *Int {
	return &Int{1, 0, 0, 0}
}

func MinInt256() *Int {
	return &Int{0, 0, 0, 0x8000000000000000}
}

func MaxInt256() *Int {
	return &Int{0xffffffffffffffff, 0xffffffffffffffff, 0xffffffffffffffff, 0x7fffffffffffffff}
}

func NewInt(val int64) *Int {
	z := &Int{}
	z.SetInt64(val)
	return z
}

func (z *Int) Set(x *Int) *Int {
	z[0], z[1], z[2], z[3] = x[0], x[1], x[2], x[3]
	return z
}

func (z *Int) SetInt64(x int64) *Int {
	if x >= 0 {
		z[3], z[2], z[1], z[0] = 0, 0, 0, uint64(x)
		return z
	}

	z[3], z[2], z[1], z[0] = 0xffffffffffffffff, 0xffffffffffffffff, 0xffffffffffffffff, uint64(x)
	return z
}

func (z *Int) IsInt64() bool {
	return ((z[1]|z[2]|z[3]) == 0 && z[0] <= 0x7fffffffffffffff) || // zero or positive int64
		((z[1]&z[2]&z[3]) == 0xffffffffffffffff && z[0] >= 0x8000000000000000) // negative int64
}

func (z *Int) Int64() int64 {
	if !z.IsInt64() {
		panic("int256: int64 overflow")
	}
	s := z.Sign()
	if s == 0 {
		return 0
	}
	if s > 0 {
		// overflow when z[0] > math.MaxInt64
		return int64(z[0])
	}
	// -(2^64 - z[0])
	return -int64(math.MaxUint64 - z[0] + 1)
}

func (z *Int) SetUint64(x uint64) *Int {
	z[3], z[2], z[1], z[0] = 0, 0, 0, x
	return z
}

func (z *Int) IsUint64() bool {
	return (z[1] | z[2] | z[3]) == 0
}

func (z *Int) Uint64() uint64 {
	if !z.IsUint64() {
		panic("int256: uint64 overflow")
	}
	return z[0]
}

func (z *Int) Abs() *u256.Uint {
	if z.IsNeg() {
		neg := new(Int).NegOverflow(z)
		return &u256.Uint{neg[0], neg[1], neg[2], neg[3]}
	}
	return &u256.Uint{z[0], z[1], z[2], z[3]}
}

func (z *Int) Sign() int {
	if z.IsZero() {
		return 0
	}
	if z[3]&0x8000000000000000 == 0 {
		return 1
	}
	return -1
}

func (z *Int) IsZero() bool {
	return (z[0] | z[1] | z[2] | z[3]) == 0
}

func (z *Int) IsOne() bool {
	return (z[0] == 1) && (z[1]|z[2]|z[3]) == 0
}

func (z *Int) IsNeg() bool {
	return z[3]&0x8000000000000000 != 0
}

func (z *Int) IsPositive() bool {
	return (z[3]&0x8000000000000000) == 0 && (z[3]|z[2]|z[1]|z[0]) != 0
}

func (z *Int) IsMinI256() bool {
	return (z[3] == 0x8000000000000000) && ((z[2] | z[1] | z[0]) == 0)
}

func (z *Int) NegOverflow(x *Int) *Int {
	if x[3] == 0x8000000000000000 && x[2] == 0 && x[1] == 0 && x[0] == 0 {
		panic("int256: overflow")
	}

	return z.Neg(x)
}

func (z *Int) Neg(x *Int) *Int {
	var carry uint64
	z[0], z[1], z[2], z[3] = ^x[0], ^x[1], ^x[2], ^x[3]
	z[0], carry = bits.Add64(z[0], 1, 0)
	z[1], carry = bits.Add64(z[1], 0, carry)
	z[2], carry = bits.Add64(z[2], 0, carry)
	z[3] += carry
	return z
}

func (z *Int) Eq(x *Int) bool {
	return (z[0] == x[0]) && (z[1] == x[1]) && (z[2] == x[2]) && (z[3] == x[3])
}

func (z *Int) Neq(x *Int) bool {
	return !z.Eq(x)
}

func (z *Int) Add(x, y *Int) *Int {
	var carry uint64
	z[0], carry = bits.Add64(x[0], y[0], 0)
	z[1], carry = bits.Add64(x[1], y[1], carry)
	z[2], carry = bits.Add64(x[2], y[2], carry)
	z[3] = x[3] + y[3] + carry
	return z
}

func (z *Int) AddOverflow(x, y *Int) (*Int, bool) {
	var carry uint64
	z[0], carry = bits.Add64(x[0], y[0], 0)
	z[1], carry = bits.Add64(x[1], y[1], carry)
	z[2], carry = bits.Add64(x[2], y[2], carry)
	z[3] = x[3] + y[3] + carry
	var overflow bool
	signX, signY, signZ := x.Sign(), y.Sign(), z.Sign()
	if (signX == signY) && (signX != signZ) {
		overflow = true
	}
	return z, overflow
}

func (z *Int) Sub(x, y *Int) *Int {
	var carry uint64
	z[0], carry = bits.Sub64(x[0], y[0], 0)
	z[1], carry = bits.Sub64(x[1], y[1], carry)
	z[2], carry = bits.Sub64(x[2], y[2], carry)
	z[3] = x[3] - y[3] - carry
	return z
}

func (z *Int) SubOverflow(x, y *Int) (*Int, bool) {
	var carry uint64
	z[0], carry = bits.Sub64(x[0], y[0], 0)
	z[1], carry = bits.Sub64(x[1], y[1], carry)
	z[2], carry = bits.Sub64(x[2], y[2], carry)
	z[3] = x[3] - y[3] - carry
	var overflow bool
	signX, signY, signZ := x.Sign(), y.Sign(), z.Sign()
	if (signX == 0 && y.IsMinI256()) || ((signX != 0) && (signX != signY) && (signX != signZ)) {
		overflow = true
	}
	return z, overflow
}

func (z *Int) Mul(x, y *Int) *Int {
	var (
		res              Int
		carry            uint64
		res1, res2, res3 uint64
	)

	carry, res[0] = bits.Mul64(x[0], y[0])
	carry, res1 = umulHop(carry, x[1], y[0])
	carry, res2 = umulHop(carry, x[2], y[0])
	res3 = x[3]*y[0] + carry

	carry, res[1] = umulHop(res1, x[0], y[1])
	carry, res2 = umulStep(res2, x[1], y[1], carry)
	res3 = res3 + x[2]*y[1] + carry

	carry, res[2] = umulHop(res2, x[0], y[2])
	res3 = res3 + x[1]*y[2] + carry

	res[3] = res3 + x[0]*y[3]

	return z.Set(&res)
}

func (z *Int) MulOverflow(x, y *Int) (*Int, bool) {
	if (x.IsMinI256() && y.IsOne()) || (x.IsOne() && y.IsMinI256()) {
		return z.Set(MinInt256()), false
	}

	var flipSign bool
	xSign, ySign := x.Sign(), y.Sign()
	if xSign*ySign == -1 {
		flipSign = true
	}

	xCopy := x.Clone()
	yCopy := y.Clone()

	if xSign < 0 {
		xCopy.Neg(xCopy)
	}
	if ySign < 0 {
		yCopy.Neg(yCopy)
	}

	p := umul(xCopy, yCopy)
	z[0], z[1], z[2], z[3] = p[0], p[1], p[2], p[3]

	var overflow bool
	if (p[4] | p[5] | p[6] | p[7]) != 0 {
		overflow = true
	} else if z.IsNeg() {
		// The 256th bit is set, which means the absolute value is >= 2^255
		// This is only valid if the result should be exactly -2^255
		if !flipSign || !z.IsMinI256() {
			overflow = true
		}
	}

	if flipSign {
		z.Neg(z)
	}

	return z, overflow
}

func umul(x, y *Int) [8]uint64 {
	var (
		res                           [8]uint64
		carry, carry4, carry5, carry6 uint64
		res1, res2, res3, res4, res5  uint64
	)

	carry, res[0] = bits.Mul64(x[0], y[0])
	carry, res1 = umulHop(carry, x[1], y[0])
	carry, res2 = umulHop(carry, x[2], y[0])
	carry4, res3 = umulHop(carry, x[3], y[0])

	carry, res[1] = umulHop(res1, x[0], y[1])
	carry, res2 = umulStep(res2, x[1], y[1], carry)
	carry, res3 = umulStep(res3, x[2], y[1], carry)
	carry5, res4 = umulStep(carry4, x[3], y[1], carry)

	carry, res[2] = umulHop(res2, x[0], y[2])
	carry, res3 = umulStep(res3, x[1], y[2], carry)
	carry, res4 = umulStep(res4, x[2], y[2], carry)
	carry6, res5 = umulStep(carry5, x[3], y[2], carry)

	carry, res[3] = umulHop(res3, x[0], y[3])
	carry, res[4] = umulStep(res4, x[1], y[3], carry)
	carry, res[5] = umulStep(res5, x[2], y[3], carry)
	res[7], res[6] = umulStep(carry6, x[3], y[3], carry)

	return res
}

func umulStep(z, x, y, carry uint64) (hi, lo uint64) {
	hi, lo = bits.Mul64(x, y)
	lo, carry = bits.Add64(lo, carry, 0)
	hi += carry
	lo, carry = bits.Add64(lo, z, 0)
	hi += carry
	return hi, lo
}

func umulHop(z, x, y uint64) (hi, lo uint64) {
	hi, lo = bits.Mul64(x, y)
	lo, carry := bits.Add64(lo, z, 0)
	hi += carry
	return hi, lo
}

func (z *Int) Clear() *Int {
	z[0], z[1], z[2], z[3] = 0, 0, 0, 0
	return z
}

func (z *Int) SetOne() *Int {
	z[3], z[2], z[1], z[0] = 0, 0, 0, 1
	return z
}

func (z *Int) SetAllBitsOne() *Int {
	z[0], z[1], z[2], z[3] = 0xffffffffffffffff, 0xffffffffffffffff, 0xffffffffffffffff, 0xffffffffffffffff
	return z
}

func (z *Int) Div(x, y *Int) *Int {
	if x.Sign() > 0 {
		if y.Sign() > 0 {
			return z.uquo(x, y)
		}
		z.uquo(x, new(Int).Neg(y))
		return z.Neg(z)
	}
	if y.Sign() < 0 {
		return z.uquo(new(Int).Neg(x), new(Int).Neg(y))
	}
	z.uquo(new(Int).Neg(x), y)
	return z.Neg(z)
}

func (z *Int) uquo(x, y *Int) *Int {
	if y.IsZero() {
		panic("zero division")
	}
	if x.IsZero() {
		return z.Clear()
	}
	if x.Eq(y) {
		return z.SetOne()
	}
	if x.IsInt64() && y.IsInt64() {
		return z.SetInt64(x.Int64() / y.Int64())
	}
	quot := Int{}
	udivrem(quot[:], x[:], y)
	return z.Set(&quot)
}

func (z *Int) Rem(x, y *Int) *Int {
	if x.Sign() > 0 {
		if y.Sign() > 0 {
			return z.urem(x, y)
		}
		return z.urem(x, new(Int).Neg(y))
	}
	if y.Sign() < 0 {
		z.urem(new(Int).Neg(x), new(Int).Neg(y))
		return z.Neg(z)
	}
	z.urem(new(Int).Neg(x), y)
	return z.Neg(z)
}

func (z *Int) urem(x, y *Int) *Int {
	if y.IsZero() {
		panic("zero division")
	}
	if x.IsZero() {
		return z.Clear()
	}
	if x.Eq(y) {
		return z.Clear()
	}
	if x.IsInt64() && y.IsInt64() {
		xInt64 := x.Int64()
		yInt64 := y.Int64()
		return z.SetInt64(xInt64 % yInt64)
	}
	quot := Int{}
	rem := udivrem(quot[:], x[:], y)
	return z.Set(&rem)
}

func (z *Int) Lt(x *Int) bool {
	return z.Cmp(x) < 0
}

func (z *Int) Lte(x *Int) bool {
	return z.Cmp(x) <= 0
}

func (z *Int) Gt(x *Int) bool {
	return z.Cmp(x) > 0
}

func (z *Int) Gte(x *Int) bool {
	return z.Cmp(x) >= 0
}

func (z *Int) Cmp(x *Int) int {
	zneg := int8(z[3] >> 63)
	xneg := int8(x[3] >> 63)
	if zneg != xneg {
		return int(xneg - zneg)
	}
	d0, carry := bits.Sub64(z[0], x[0], 0)
	d1, carry := bits.Sub64(z[1], x[1], carry)
	d2, carry := bits.Sub64(z[2], x[2], carry)
	d3, carry := bits.Sub64(z[3], x[3], carry)
	if carry == 1 {
		return -1
	}
	if d0|d1|d2|d3 == 0 {
		return 0
	}
	return 1
}

func (z *Int) Clone() *Int {
	return &Int{z[0], z[1], z[2], z[3]}
}

func (z *Int) Or(x, y *Int) *Int {
	z[0] = x[0] | y[0]
	z[1] = x[1] | y[1]
	z[2] = x[2] | y[2]
	z[3] = x[3] | y[3]
	return z
}

func (z *Int) And(x, y *Int) *Int {
	z[0] = x[0] & y[0]
	z[1] = x[1] & y[1]
	z[2] = x[2] & y[2]
	z[3] = x[3] & y[3]
	return z
}

func (z *Int) Xor(x, y *Int) *Int {
	z[0] = x[0] ^ y[0]
	z[1] = x[1] ^ y[1]
	z[2] = x[2] ^ y[2]
	z[3] = x[3] ^ y[3]
	return z
}

func (z *Int) Not(x *Int) *Int {
	z[0] = ^x[0]
	z[1] = ^x[1]
	z[2] = ^x[2]
	z[3] = ^x[3]
	return z
}

func (z *Int) Lsh(x *Int, n uint) *Int {
	if n == 0 {
		return z.Set(x)
	}
	if n >= 256 {
		return z.Clear()
	}
	// Handle exact multiples of 64 separately to avoid 64-bit shift issues
	if n&0x3f == 0 {
		switch n {
		case 64:
			z[3], z[2], z[1], z[0] = x[2], x[1], x[0], 0
		case 128:
			z[3], z[2], z[1], z[0] = x[1], x[0], 0, 0
		case 192:
			z[3], z[2], z[1], z[0] = x[0], 0, 0, 0
		}
		return z
	}
	switch {
	case n > 192:
		n -= 192
		z[3], z[2], z[1], z[0] = x[0]<<n, 0, 0, 0
	case n > 128:
		n -= 128
		z[3] = (x[1] << n) | (x[0] >> (64 - n))
		z[2] = x[0] << n
		z[1], z[0] = 0, 0
	case n > 64:
		n -= 64
		z[3] = (x[2] << n) | (x[1] >> (64 - n))
		z[2] = (x[1] << n) | (x[0] >> (64 - n))
		z[1] = x[0] << n
		z[0] = 0
	default:
		z[3] = (x[3] << n) | (x[2] >> (64 - n))
		z[2] = (x[2] << n) | (x[1] >> (64 - n))
		z[1] = (x[1] << n) | (x[0] >> (64 - n))
		z[0] = x[0] << n
	}
	return z
}

func (z *Int) Rsh(x *Int, n uint) *Int {
	if n == 0 {
		return z.Set(x)
	}
	if x.IsNeg() {
		return z.negRsh(x, n)
	}
	return z.rsh(x, n)
}

func (z *Int) rsh(x *Int, n uint) *Int {
	if n >= 256 {
		return z.Clear()
	}
	// Handle exact multiples of 64 separately to avoid 64-bit shift issues
	if n&0x3f == 0 {
		switch n {
		case 0:
			return z.Set(x)
		case 64:
			z[3], z[2], z[1], z[0] = 0, x[3], x[2], x[1]
		case 128:
			z[3], z[2], z[1], z[0] = 0, 0, x[3], x[2]
		case 192:
			z[3], z[2], z[1], z[0] = 0, 0, 0, x[3]
		}
		return z
	}
	switch {
	case n > 192:
		n -= 192
		z[3], z[2], z[1], z[0] = 0, 0, 0, x[3]>>n
	case n > 128:
		n -= 128
		z[3], z[2] = 0, 0
		z[1] = x[3] >> n
		z[0] = (x[3] << (64 - n)) | (x[2] >> n)
	case n > 64:
		n -= 64
		z[3] = 0
		z[2] = x[3] >> n
		z[1] = (x[3] << (64 - n)) | (x[2] >> n)
		z[0] = (x[2] << (64 - n)) | (x[1] >> n)
	default:
		z[3] = x[3] >> n
		z[2] = (x[3] << (64 - n)) | (x[2] >> n)
		z[1] = (x[2] << (64 - n)) | (x[1] >> n)
		z[0] = (x[1] << (64 - n)) | (x[0] >> n)
	}
	return z
}

func (z *Int) negRsh(x *Int, n uint) *Int {
	if n >= 256 {
		return z.SetAllBitsOne()
	}
	var v uint64 = 0xffffffffffffffff
	// Handle exact multiples of 64 separately to avoid 64-bit shift issues
	if n&0x3f == 0 {
		switch n {
		case 0:
			return z.Set(x)
		case 64:
			z[3], z[2], z[1], z[0] = v, x[3], x[2], x[1]
		case 128:
			z[3], z[2], z[1], z[0] = v, v, x[3], x[2]
		case 192:
			z[3], z[2], z[1], z[0] = v, v, v, x[3]
		}
		return z
	}
	switch {
	case n > 192:
		n -= 192
		z[3], z[2], z[1], z[0] = v, v, v, (v<<(64-n))|(x[3]>>n)
	case n > 128:
		n -= 128
		z[3], z[2] = v, v
		z[1] = (v << (64 - n)) | (x[3] >> n)
		z[0] = (x[3] << (64 - n)) | (x[2] >> n)
	case n > 64:
		n -= 64
		z[3] = v
		z[2] = (v << (64 - n)) | (x[3] >> n)
		z[1] = (x[3] << (64 - n)) | (x[2] >> n)
		z[0] = (x[2] << (64 - n)) | (x[1] >> n)
	default:
		z[3] = (v << (64 - n)) | (x[3] >> n)
		z[2] = (x[3] << (64 - n)) | (x[2] >> n)
		z[1] = (x[2] << (64 - n)) | (x[1] >> n)
		z[0] = (x[1] << (64 - n)) | (x[0] >> n)
	}
	return z
}

func (z *Int) BitLen() int {
	switch {
	case z[3] != 0:
		return 192 + bits.Len64(z[3])
	case z[2] != 0:
		return 128 + bits.Len64(z[2])
	case z[1] != 0:
		return 64 + bits.Len64(z[1])
	default:
		return bits.Len64(z[0])
	}
}

func (z *Int) SetBytes32(in []byte) *Int {
	_ = in[31] // bounds check hint to compiler; see golang.org/issue/14808
	z[3] = binary.BigEndian.Uint64(in[0:8])
	z[2] = binary.BigEndian.Uint64(in[8:16])
	z[1] = binary.BigEndian.Uint64(in[16:24])
	z[0] = binary.BigEndian.Uint64(in[24:32])
	return z
}

package consts

import (
	i256 "gno.land/p/gnoswap/int256"
	u256 "gno.land/p/gnoswap/uint256"
)

// u256.Uint and i256.Int are little-endian [4]uint64:
// {arr[0]=least significant, arr[1], arr[2], arr[3]=most significant}.

// MaxUint256 returns 2^256 - 1.
func MaxUint256() *u256.Uint {
	return &u256.Uint{18446744073709551615, 18446744073709551615, 18446744073709551615, 18446744073709551615}
}

// MaxUint128 returns 2^128 - 1, the maximum uint128 value.
func MaxUint128() *u256.Uint {
	return &u256.Uint{18446744073709551615, 18446744073709551615, 0, 0}
}

// MaxInt256 returns 2^255 - 1, the maximum int256 value, as an unsigned u256.
func MaxInt256() *u256.Uint {
	return &u256.Uint{18446744073709551615, 18446744073709551615, 18446744073709551615, 9223372036854775807}
}

// Q96 returns 2^96, the Q64.96 fixed-point scaling factor.
func Q96() *u256.Uint {
	return &u256.Uint{0, 4294967296, 0, 0}
}

// Q128 returns 2^128, the Q128.128 fixed-point scaling factor.
func Q128() *u256.Uint {
	return &u256.Uint{0, 0, 1, 0}
}

// Q192 returns 2^192.
func Q192() *u256.Uint {
	return &u256.Uint{0, 0, 0, 1}
}

// Max160 returns 2^160 - 1, the maximum value representable in 160 bits.
func Max160() *u256.Uint {
	return &u256.Uint{18446744073709551615, 18446744073709551615, 4294967295, 0}
}

// MinSqrtRatio returns the minimum valid sqrt price ratio (4295128739),
// equal to TickMathGetSqrtRatioAtTick(minTick).
func MinSqrtRatio() *u256.Uint {
	return &u256.Uint{4295128739, 0, 0, 0}
}

// MaxSqrtRatio returns the maximum valid sqrt price ratio
// (1461446703485210103287273052203988822378723970342),
// equal to TickMathGetSqrtRatioAtTick(maxTick).
func MaxSqrtRatio() *u256.Uint {
	return &u256.Uint{6743328256752651558, 17280870778742802505, 4294805859, 0}
}

// MaxInt128I256 returns 2^127 - 1, the maximum int128 value, as a signed i256.
func MaxInt128I256() *i256.Int {
	return &i256.Int{18446744073709551615, 9223372036854775807, 0, 0}
}

// MaxInt64I256 returns 2^63 - 1, the maximum int64 value, as a signed i256.
func MaxInt64I256() *i256.Int {
	return &i256.Int{9223372036854775807, 0, 0, 0}
}

// MinInt64I256 returns -2^63, the minimum int64 value, as a signed i256.
func MinInt64I256() *i256.Int {
	return &i256.Int{9223372036854775808, 18446744073709551615, 18446744073709551615, 18446744073709551615}
}

package gnsmath

import (
	u256 "gno.land/p/gnoswap/uint256"
)

// bitShift represents a bit pattern and corresponding shift amount for bit manipulation.
type bitShift struct {
	bitPattern *u256.Uint
	shift      uint
}

// newMsbShifts returns the descending power-of-two thresholds used by
// BitMathMostSignificantBit. It is a constructor (not a package-level var) so
// each call yields freshly allocated bit patterns that callers never share.
// Values are built from little-endian [4]uint64 literals to avoid runtime
// shift computations.
func newMsbShifts() []bitShift {
	return []bitShift{
		{&u256.Uint{0, 0, 1, 0}, 128},         // 2^128
		{&u256.Uint{0, 1, 0, 0}, 64},          // 2^64
		{&u256.Uint{4294967296, 0, 0, 0}, 32}, // 2^32
		{&u256.Uint{65536, 0, 0, 0}, 16},      // 2^16
		{&u256.Uint{256, 0, 0, 0}, 8},         // 2^8
		{&u256.Uint{16, 0, 0, 0}, 4},          // 2^4
		{&u256.Uint{4, 0, 0, 0}, 2},           // 2^2
		{&u256.Uint{2, 0, 0, 0}, 1},           // 2^1
	}
}

// newLsbShifts returns the descending (2^n - 1) masks used by
// BitMathLeastSignificantBit. See newMsbShifts for rationale.
func newLsbShifts() []bitShift {
	return []bitShift{
		{&u256.Uint{18446744073709551615, 18446744073709551615, 0, 0}, 128}, // 2^128 - 1
		{&u256.Uint{18446744073709551615, 0, 0, 0}, 64},                     // 2^64 - 1
		{&u256.Uint{4294967295, 0, 0, 0}, 32},                               // 2^32 - 1
		{&u256.Uint{65535, 0, 0, 0}, 16},                                    // 2^16 - 1
		{&u256.Uint{255, 0, 0, 0}, 8},                                       // 2^8 - 1
		{&u256.Uint{0xf, 0, 0, 0}, 4},                                       // 2^4 - 1 = 15
		{&u256.Uint{0x3, 0, 0, 0}, 2},                                       // 2^2 - 1 = 3
		{&u256.Uint{0x1, 0, 0, 0}, 1},                                       // 2^1 - 1 = 1
	}
}

// BitMathMostSignificantBit returns the 0-based position of the most significant bit in x.
// This function is essential for AMM calculations involving price ranges and tick boundaries.
//
// Parameters:
//   - x: the value for which to compute the most significant bit
//
// Returns the index of the most significant bit (0-255).
//
// Panics if x is zero.
func BitMathMostSignificantBit(x *u256.Uint) uint8 {
	if x.IsZero() {
		panic(errMSBZeroInput)
	}

	temp := x.Clone()
	r := uint8(0)

	for _, s := range newMsbShifts() {
		if temp.Gte(s.bitPattern) {
			temp = temp.Rsh(temp, s.shift)
			r += uint8(s.shift)
		}
	}

	return r
}

// BitMathLeastSignificantBit returns the 0-based position of the least significant bit in x.
// This function is used in AMM calculations for efficient bit manipulation and range queries.
//
// Parameters:
//   - x: the value for which to compute the least significant bit
//
// Returns the index of the least significant bit (0-255).
//
// Panics if x is zero.
func BitMathLeastSignificantBit(x *u256.Uint) uint8 {
	if x.IsZero() {
		panic(errLSBZeroInput)
	}

	temp := x.Clone()
	hasSetBits := u256.Zero()
	r := uint8(255)

	for _, s := range newLsbShifts() {
		hasSetBits = hasSetBits.And(temp, s.bitPattern)
		if !hasSetBits.IsZero() {
			r -= uint8(s.shift)
		} else {
			temp = temp.Rsh(temp, s.shift)
		}
	}

	return r
}

package gnsmath

const (
	// minTick is the minimum valid tick index in the concentrated liquidity model.
	// Represents the lowest possible price: 1.0001^(-887272) ≈ 0
	minTick = -887272

	// maxTick is the maximum valid tick index in the concentrated liquidity model.
	// Represents the highest possible price: 1.0001^887272 ≈ infinity
	maxTick = 887272

	Q96_RESOLUTION  uint = 96
	Q160_RESOLUTION uint = 160

	MAX_UINT128 = "340282366920938463463374607431768211455" // 2^128 - 1
	Q96         = "79228162514264337593543950336"           // 2^96
)

// Package gnsmath provides core mathematical operations for GnoSwap's concentrated liquidity AMM.
//
// ## Overview
//
// This package provides the fundamental calculations for concentrated liquidity,
// including tick conversion, liquidity math calculations, sqrt price math, swap
// calculations, and bit manipulation utilities. All operations use Q64.96,
// Q128.128, and Q160 fixed-point arithmetic where appropriate.
//
// The implementation follows Uniswap V3's mathematical model.
//
// ## Features
//
//   - Bit Math: MSB/LSB calculations for tick bitmap operations
//   - Tick Math: tick and Q64.96 sqrt-price conversions
//   - Liquidity Math: liquidity and token amount math for price ranges
//   - Sqrt Price Math: token amount conversions using Q64.96 format
//   - Swap Math: single-step swap calculations with fee handling
//   - Overflow Protection: explicit int256/uint256 overflow checks
//   - Rounding Control: configurable rounding for AMM safety
//
// ## Core Concepts
//
// ### Q64.96 Fixed-Point Format
//
// Square root prices use Q64.96 representation:
//   - sqrtPriceX96 = sqrt(token1/token0) * 2^96
//   - Enables precise integer arithmetic without floating-point
//
// ### Rounding Directions
//
//   - Round UP: amounts owed TO pool (deposits, exact input)
//   - Round DOWN: amounts owed FROM pool (withdrawals, exact output)
//
// ## API
//
// ### Bit Math
//
//   - BitMathMostSignificantBit(x *u256.Uint) uint8
//   - BitMathLeastSignificantBit(x *u256.Uint) uint8
//
// ### Tick Math
//
//   - TickMathGetSqrtRatioAtTick(tick int32) *u256.Uint
//   - TickMathGetTickAtSqrtRatio(sqrtPriceX96 *u256.Uint) int32
//
// ### Liquidity Math
//
//   - GetLiquidityForAmounts(sqrtRatioX96, sqrtRatioAX96, sqrtRatioBX96, amount0, amount1 *u256.Uint) *u256.Uint
//   - GetAmountsForLiquidity(sqrtRatioX96, sqrtRatioAX96, sqrtRatioBX96, liquidity *u256.Uint) (*u256.Uint, *u256.Uint)
//   - LiquidityMathAddDelta(x *u256.Uint, y *i256.Int) *u256.Uint
//
// ### Sqrt Price Math
//
//   - GetAmount0Delta(sqrtRatioAX96, sqrtRatioBX96 *u256.Uint, liquidity *i256.Int) *i256.Int
//   - GetAmount1Delta(sqrtRatioAX96, sqrtRatioBX96 *u256.Uint, liquidity *i256.Int) *i256.Int
//
// ### Swap Math
//
//   - SwapMathComputeSwapStep(sqrtRatioCurrentX96, sqrtRatioTargetX96, liquidity *u256.Uint, amountRemaining *i256.Int, feePips uint64) (*u256.Uint, *u256.Uint, *u256.Uint, *u256.Uint)
package gnsmath

package gnsmath

import (
	ufmt "gno.land/p/nt/ufmt/v0"

	"gno.land/p/gnoswap/consts"
	i256 "gno.land/p/gnoswap/int256"
	u256 "gno.land/p/gnoswap/uint256"
)

// computeLiquidityForAmount0 calculates the liquidity for a given amount of token0.
//
// This function computes the maximum possible liquidity that can be provided for `token0`
// based on the provided price boundaries (sqrtRatioAX96 and sqrtRatioBX96) in Q64.96 format.
//
// Parameters:
//   - sqrtRatioAX96: *u256.Uint - The square root price at the lower tick boundary (Q64.96).
//   - sqrtRatioBX96: *u256.Uint - The square root price at the upper tick boundary (Q64.96).
//   - amount0: *u256.Uint - The amount of token0 to be converted to liquidity.
//
// Returns:
//   - *u256.Uint: The calculated liquidity, represented as an unsigned 128-bit integer (uint128).
//
// Panics:
//   - If the resulting liquidity exceeds the uint128 range, `SafeConvertToUint128` will trigger a panic.
func computeLiquidityForAmount0(sqrtRatioAX96, sqrtRatioBX96, amount0 *u256.Uint) *u256.Uint {
	sqrtRatioAX96, sqrtRatioBX96 = toAscendingOrder(sqrtRatioAX96, sqrtRatioBX96)
	intermediate := u256.MulDiv(sqrtRatioAX96, sqrtRatioBX96, consts.Q96())

	diff := u256.Zero().Sub(sqrtRatioBX96, sqrtRatioAX96)
	if diff.IsZero() {
		panic(newErrorWithDetail(
			errLiquidityIdenticalTicks,
			ufmt.Sprintf("sqrtRatioAX96 (%s) and sqrtRatioBX96 (%s) are identical", sqrtRatioAX96.ToString(), sqrtRatioBX96.ToString()),
		))
	}
	res := u256.MulDiv(amount0, intermediate, diff)
	return SafeConvertToUint128(res)
}

// computeLiquidityForAmount1 calculates liquidity based on the provided token1 amount and price range.
//
// This function computes the liquidity for a given amount of token1 by using the difference
// between the upper and lower square root price ratios. The calculation uses Q96 fixed-point
// arithmetic to maintain precision.
//
// Parameters:
//   - sqrtRatioAX96: *u256.Uint - The square root ratio of price at the lower tick, represented in Q96 format.
//   - sqrtRatioBX96: *u256.Uint - The square root ratio of price at the upper tick, represented in Q96 format.
//   - amount1: *u256.Uint - The amount of token1 to calculate liquidity for.
//
// Returns:
//   - *u256.Uint: The calculated liquidity based on the provided amount of token1 and price range.
//
// Notes:
//   - The result is not directly limited to uint128, as liquidity values can exceed uint128 bounds.
//   - If `sqrtRatioAX96 == sqrtRatioBX96`, the function will panic due to division by zero.
//   - Q96 is a constant representing `2^96`, ensuring that precision is maintained during division.
//
// Panics:
//   - If the resulting liquidity exceeds the uint128 range, `SafeConvertToUint128` will trigger a panic.
func computeLiquidityForAmount1(sqrtRatioAX96, sqrtRatioBX96, amount1 *u256.Uint) *u256.Uint {
	sqrtRatioAX96, sqrtRatioBX96 = toAscendingOrder(sqrtRatioAX96, sqrtRatioBX96)

	diff := u256.Zero().Sub(sqrtRatioBX96, sqrtRatioAX96)
	if diff.IsZero() {
		panic(newErrorWithDetail(
			errLiquidityIdenticalTicks,
			ufmt.Sprintf("sqrtRatioAX96 (%s) and sqrtRatioBX96 (%s) are identical", sqrtRatioAX96.ToString(), sqrtRatioBX96.ToString()),
		))
	}
	res := u256.MulDiv(amount1, consts.Q96(), diff)
	return SafeConvertToUint128(res)
}

// GetLiquidityForAmounts calculates the maximum liquidity given the current price (sqrtRatioX96),
// upper and lower price bounds (sqrtRatioAX96 and sqrtRatioBX96), and token amounts (amount0, amount1).
//
// This function evaluates how much liquidity can be obtained for specified amounts of token0 and token1
// within the provided price range. It returns the lesser liquidity based on available token0 or token1
// to ensure the pool remains balanced.
//
// Parameters:
// - sqrtRatioX96: The current price as a square root ratio in Q64.96 format (*u256.Uint).
// - sqrtRatioAX96: The lower bound of the price range as a square root ratio in Q64.96 format (*u256.Uint).
// - sqrtRatioBX96: The upper bound of the price range as a square root ratio in Q64.96 format (*u256.Uint).
// - amount0: The amount of token0 available to provide liquidity (*u256.Uint).
// - amount1: The amount of token1 available to provide liquidity (*u256.Uint).
//
// Returns:
// - *u256.Uint: The maximum possible liquidity that can be minted.
//
// Notes:
//   - The `Clone` method is used to prevent modification of the original values during computation.
//   - The function ensures that liquidity calculations handle edge cases when the current price
//     is outside the specified range by returning liquidity based on the dominant token.
func GetLiquidityForAmounts(sqrtRatioX96, sqrtRatioAX96, sqrtRatioBX96, amount0, amount1 *u256.Uint) (liquidity *u256.Uint) {
	sqrtRatioAX96, sqrtRatioBX96 = toAscendingOrder(sqrtRatioAX96, sqrtRatioBX96)

	if sqrtRatioX96.Lte(sqrtRatioAX96) {
		liquidity = computeLiquidityForAmount0(sqrtRatioAX96, sqrtRatioBX96, amount0)
	} else if sqrtRatioX96.Lt(sqrtRatioBX96) {
		liquidity0 := computeLiquidityForAmount0(sqrtRatioX96, sqrtRatioBX96, amount0)
		liquidity1 := computeLiquidityForAmount1(sqrtRatioAX96, sqrtRatioX96, amount1)

		if liquidity0.Lt(liquidity1) {
			liquidity = liquidity0
		} else {
			liquidity = liquidity1
		}
	} else {
		liquidity = computeLiquidityForAmount1(sqrtRatioAX96, sqrtRatioBX96, amount1)
	}
	return liquidity
}

// computeAmount0ForLiquidity calculates the required amount of token0 for a given liquidity level
// within a specified price range (represented by sqrt ratios).
//
// This function determines the amount of token0 needed to provide a specified amount of liquidity
// within a price range defined by sqrtRatioAX96 (lower bound) and sqrtRatioBX96 (upper bound).
//
// Parameters:
// - sqrtRatioAX96: The lower bound of the price range as a square root ratio in Q64.96 format (*u256.Uint).
// - sqrtRatioBX96: The upper bound of the price range as a square root ratio in Q64.96 format (*u256.Uint).
// - liquidity: The liquidity to be provided (*u256.Uint).
//
// Returns:
// - *u256.Uint: The amount of token0 required to achieve the specified liquidity level.
//
// Notes:
// - This function assumes the price bounds are expressed in Q64.96 fixed-point format.
// - The function returns 0 if the liquidity is 0 or the price bounds are invalid.
// - Handles edge cases where sqrtRatioAX96 equals sqrtRatioBX96 by returning 0 (to prevent division by zero).
func computeAmount0ForLiquidity(sqrtRatioAX96, sqrtRatioBX96, liquidity *u256.Uint) *u256.Uint {
	sqrtRatioAX96, sqrtRatioBX96 = toAscendingOrder(sqrtRatioAX96, sqrtRatioBX96)
	if sqrtRatioAX96.IsZero() || sqrtRatioBX96.IsZero() || liquidity.IsZero() || sqrtRatioAX96.Eq(sqrtRatioBX96) {
		return u256.Zero()
	}

	val1 := u256.Zero().Lsh(liquidity, Q96_RESOLUTION)
	val2 := u256.Zero().Sub(sqrtRatioBX96, sqrtRatioAX96)

	res := u256.MulDiv(val1, val2, sqrtRatioBX96)
	res = res.Div(res, sqrtRatioAX96)

	return res
}

// computeAmount1ForLiquidity calculates the required amount of token1 for a given liquidity level
// within a specified price range (represented by sqrt ratios).
//
// This function determines the amount of token1 needed to provide liquidity between the
// lower (sqrtRatioAX96) and upper (sqrtRatioBX96) price bounds. The calculation is performed
// in Q64.96 fixed-point format, which is standard for many liquidity calculations.
//
// Parameters:
// - sqrtRatioAX96: The lower bound of the price range as a square root ratio in Q64.96 format (*u256.Uint).
// - sqrtRatioBX96: The upper bound of the price range as a square root ratio in Q64.96 format (*u256.Uint).
// - liquidity: The liquidity amount to be used in the calculation (*u256.Uint).
//
// Returns:
// - *u256.Uint: The amount of token1 required to achieve the specified liquidity level.
//
// Notes:
//   - This function handles edge cases where the liquidity is zero or when sqrtRatioAX96 equals sqrtRatioBX96
//     to prevent division by zero.
//   - The calculation assumes sqrtRatioAX96 is always less than or equal to sqrtRatioBX96 after the initial
//     ascending order sorting.
func computeAmount1ForLiquidity(sqrtRatioAX96, sqrtRatioBX96, liquidity *u256.Uint) *u256.Uint {
	sqrtRatioAX96, sqrtRatioBX96 = toAscendingOrder(sqrtRatioAX96, sqrtRatioBX96)
	if liquidity.IsZero() || sqrtRatioAX96.Eq(sqrtRatioBX96) {
		return u256.Zero()
	}

	diff := u256.Zero().Sub(sqrtRatioBX96, sqrtRatioAX96)
	res := u256.MulDiv(liquidity, diff, consts.Q96())

	return res
}

// GetAmountsForLiquidity calculates the amounts of token0 and token1 required
// to provide a specified liquidity within a price range.
//
// This function determines the quantities of token0 and token1 necessary to achieve
// a given liquidity level, depending on the current price (sqrtRatioX96) and the
// bounds of the price range (sqrtRatioAX96 and sqrtRatioBX96). The function returns
// the calculated amounts of token0 and token1 as strings.
//
// If the current price is below the lower bound of the price range, only token0 is required.
// If the current price is above the upper bound, only token1 is required. When the
// price is within the range, both token0 and token1 are calculated.
//
// Parameters:
// - sqrtRatioX96: The current price represented as a square root ratio in Q64.96 format (*u256.Uint).
// - sqrtRatioAX96: The lower bound of the price range as a square root ratio in Q64.96 format (*u256.Uint).
// - sqrtRatioBX96: The upper bound of the price range as a square root ratio in Q64.96 format (*u256.Uint).
// - liquidity: The amount of liquidity to be provided (*u256.Uint).
//
// Returns:
// - string: The calculated amount of token0 required to achieve the specified liquidity.
// - string: The calculated amount of token1 required to achieve the specified liquidity.
//
// Notes:
//   - If liquidity is zero, the function returns "0" for both token0 and token1.
//   - The function guarantees that sqrtRatioAX96 is always the lower bound and
//     sqrtRatioBX96 is the upper bound by calling toAscendingOrder().
//   - Edge cases where the current price is exactly on the bounds are handled without division by zero.
//
// Example:
// ```
// amount0, amount1 := GetAmountsForLiquidity(
//
//	u256.MustFromDecimal("79228162514264337593543950336"),  // sqrtRatioX96 (1.0 in Q64.96)
//	u256.MustFromDecimal("39614081257132168796771975168"),  // sqrtRatioAX96 (0.5 in Q64.96)
//	u256.MustFromDecimal("158456325028528675187087900672"), // sqrtRatioBX96 (2.0 in Q64.96)
//	u256.MustFromDecimal("1000000"),                        // Liquidity
//
// )
//
// println("Token0:", amount0, "Token1:", amount1)
//
// // Output:
// Token0: 500000, Token1: 250000
// ```
func GetAmountsForLiquidity(sqrtRatioX96, sqrtRatioAX96, sqrtRatioBX96, liquidity *u256.Uint) (*u256.Uint, *u256.Uint) {
	if liquidity.IsZero() {
		return u256.Zero(), u256.Zero()
	}

	sqrtRatioAX96, sqrtRatioBX96 = toAscendingOrder(sqrtRatioAX96, sqrtRatioBX96)

	amount0 := u256.Zero()
	amount1 := u256.Zero()

	if sqrtRatioX96.Lte(sqrtRatioAX96) {
		amount0 = computeAmount0ForLiquidity(sqrtRatioAX96, sqrtRatioBX96, liquidity)
	} else if sqrtRatioX96.Lt(sqrtRatioBX96) {
		amount0 = computeAmount0ForLiquidity(sqrtRatioX96, sqrtRatioBX96, liquidity)
		amount1 = computeAmount1ForLiquidity(sqrtRatioAX96, sqrtRatioX96, liquidity)
	} else {
		amount1 = computeAmount1ForLiquidity(sqrtRatioAX96, sqrtRatioBX96, liquidity)
	}

	return amount0, amount1
}

// LiquidityMathAddDelta calculates the new liquidity by applying the delta liquidity to the current liquidity.
// If delta liquidity is negative, it subtracts the absolute value of delta liquidity from the current liquidity.
// If delta liquidity is positive, it adds the absolute value of delta liquidity to the current liquidity.
//
// Parameters:
//   - x: current liquidity as unsigned 256-bit integer
//   - y: delta liquidity as signed 256-bit integer (positive to add, negative to subtract)
//
// Returns the new liquidity as a uint256 value.
//
// Panics if x or y is nil, or if the operation would result in underflow or overflow.
func LiquidityMathAddDelta(x *u256.Uint, y *i256.Int) *u256.Uint {
	if x == nil || y == nil {
		panic("liquidity_math: x or y is nil")
	}

	yAbs := y.Abs()

	// Subtract or add based on the sign of y
	if y.Lt(i256.Zero()) {
		z := u256.Zero().Sub(x, yAbs)
		if z.Gte(x) {
			panic(ufmt.Sprintf(
				"liquidity_math: underflow (x: %s, y: %s, z:%s)",
				x.ToString(), y.ToString(), z.ToString()))
		}
		if z.Gt(consts.MaxUint128()) {
			panic(ufmt.Sprintf(
				"liquidity_math: result exceeds uint128 range (z: %s)",
				z.ToString()))
		}
		return z
	}

	z := u256.Zero().Add(x, yAbs)
	if z.Lt(x) {
		panic(ufmt.Sprintf(
			"liquidity_math: overflow (x: %s, y: %s, z:%s)",
			x.ToString(), y.ToString(), z.ToString()))
	}
	if z.Gt(consts.MaxUint128()) {
		panic(ufmt.Sprintf(
			"liquidity_math: result exceeds uint128 range (z: %s)",
			z.ToString()))
	}
	return z
}

// toAscendingOrder returns the two values in ascending order.
func toAscendingOrder(a, b *u256.Uint) (*u256.Uint, *u256.Uint) {
	if a.Gt(b) {
		return b, a
	}

	return a, b
}

// SafeConvertToUint128 safely ensures a *u256.Uint value fits within the uint128 range.
//
// This function verifies that the provided unsigned 256-bit integer does not exceed the maximum value for uint128 (`2^128 - 1`).
// If the value is within the uint128 range, it is returned as is; otherwise, the function triggers a panic.
//
// Parameters:
// - value (*u256.Uint): The unsigned 256-bit integer to be checked.
//
// Returns:
// - *u256.Uint: The same value if it is within the uint128 range.
//
// Panics:
//   - If the value exceeds the maximum uint128 value (`2^128 - 1`), the function will panic with a descriptive error
//     indicating the overflow and the original value.
//
// Notes:
// - The constant `MAX_UINT128` is defined as `340282366920938463463374607431768211455` (the largest uint128 value).
// - No actual conversion occurs since the function works directly with *u256.Uint types.
//
// Example:
// validUint128 := SafeConvertToUint128(u256.MustFromDecimal("340282366920938463463374607431768211455")) // Valid
// SafeConvertToUint128(u256.MustFromDecimal("340282366920938463463374607431768211456")) // Panics due to overflow
func SafeConvertToUint128(value *u256.Uint) *u256.Uint {
	if value.Gt(consts.MaxUint128()) {
		panic(ufmt.Sprintf(
			"%v: amount(%s) overflows uint128 range",
			errLiquidityOverflow, value.ToString()))
	}
	return value
}

package gnsmath

import (
	"math"

	ufmt "gno.land/p/nt/ufmt/v0"

	i256 "gno.land/p/gnoswap/int256"
	u256 "gno.land/p/gnoswap/uint256"
)

// Range bounds used by the safe conversion helpers.
const (
	maxInt64Decimal  = "9223372036854775807"                     // 2^63 - 1
	maxInt128Decimal = "170141183460469231731687303715884105727" // 2^127 - 1
)

// maxInt128 is the largest value representable in a signed 128-bit integer.
// It is used by SafeConvertToInt128 to bound liquidity deltas.
func MaxInt128() *i256.Int {
	return i256.MustFromDecimal(maxInt128Decimal)
}

// SafeAddInt64 returns a + b, panicking on int64 overflow or underflow.
func SafeAddInt64(a, b int64) int64 {
	if a > 0 && b > math.MaxInt64-a {
		panic("int64 addition overflow")
	}
	if a < 0 && b < math.MinInt64-a {
		panic("int64 addition underflow")
	}
	return a + b
}

// SafeSubInt64 returns a - b, panicking on int64 overflow or underflow.
func SafeSubInt64(a, b int64) int64 {
	if b > 0 && a < math.MinInt64+b {
		panic("int64 subtraction underflow")
	}
	if b < 0 && a > math.MaxInt64+b {
		panic("int64 subtraction overflow")
	}
	return a - b
}

// SafeMulInt64 returns a * b, panicking on int64 overflow or underflow.
func SafeMulInt64(a, b int64) int64 {
	if a == 0 || b == 0 {
		return 0
	}

	if a > 0 && b > 0 {
		if a > math.MaxInt64/b {
			panic("int64 multiplication overflow")
		}
	} else if a < 0 && b < 0 {
		if a < math.MaxInt64/b {
			panic("int64 multiplication overflow")
		}
	} else if a > 0 && b < 0 {
		if b < math.MinInt64/a {
			panic("int64 multiplication underflow")
		}
	} else { // a < 0 && b > 0
		if a < math.MinInt64/b {
			panic("int64 multiplication underflow")
		}
	}

	return a * b
}

// SafeMulDivInt64 returns (a * b) / c, computing the intermediate product in
// 256-bit signed arithmetic so a*b need not fit in int64. The final quotient
// must fit in int64, otherwise it panics. It panics on overflow.
func SafeMulDivInt64(a, b, c int64) int64 {
	if a == 0 || b == 0 {
		return 0
	}

	result, overflow := i256.Zero().MulOverflow(i256.NewInt(a), i256.NewInt(b))
	if overflow {
		panic(errSafeMathOverflow)
	}

	result = i256.Zero().Div(result, i256.NewInt(c))
	if !result.IsInt64() {
		panic(errSafeMathOverflow)
	}

	return result.Int64()
}

// SafeAbsInt64 returns the absolute value of a, panicking when a is math.MinInt64
// since its absolute value is not representable in int64.
func SafeAbsInt64(a int64) int64 {
	if a == math.MinInt64 {
		panic(errSafeMathOverflow)
	}
	if a < 0 {
		return -a
	}
	return a
}

// SafeAddUint64 returns a + b, panicking on uint64 overflow.
func SafeAddUint64(a, b uint64) uint64 {
	if a > math.MaxUint64-b {
		panic("uint64 addition overflow")
	}
	return a + b
}

// SafeSubUint64 returns a - b, panicking on uint64 underflow.
func SafeSubUint64(a, b uint64) uint64 {
	if a < b {
		panic("uint64 subtraction underflow")
	}
	return a - b
}

// SafeUint64ToInt64 converts a uint64 to int64, panicking when the value
// exceeds the int64 range (2^63 - 1).
func SafeUint64ToInt64(value uint64) int64 {
	if value > uint64(math.MaxInt64) {
		panic(ufmt.Sprintf(
			"amount(%d) overflows int64 range (max: %s)",
			value, maxInt64Decimal,
		))
	}
	return int64(value)
}

// SafeConvertToInt64 converts a *u256.Uint to int64, panicking when the value
// is nil or exceeds the int64 range (2^63 - 1).
func SafeConvertToInt64(value *u256.Uint) int64 {
	if value == nil {
		panic("SafeConvertToInt64: value is nil")
	}
	res, overflow := value.Uint64WithOverflow()
	if overflow || res > uint64(math.MaxInt64) {
		panic(ufmt.Sprintf(
			"amount(%s) overflows int64 range (max: %s)",
			value.ToString(), maxInt64Decimal,
		))
	}
	return int64(res)
}

// SafeConvertToInt128 converts a *u256.Uint to an *i256.Int, panicking when the
// value exceeds the signed int128 range (2^127 - 1).
func SafeConvertToInt128(value *u256.Uint) *i256.Int {
	if value == nil {
		panic("SafeConvertToInt128: value is nil")
	}
	converted := i256.FromUint256(value)
	if converted.Gt(MaxInt128()) {
		panic(ufmt.Sprintf(
			"amount(%s) overflows int128 range",
			value.ToString(),
		))
	}
	return converted
}

package gnsmath

import (
	"gno.land/p/gnoswap/consts"
	i256 "gno.land/p/gnoswap/int256"
	u256 "gno.land/p/gnoswap/uint256"
)

// MIN_SQRT_RATIO returns the minimum valid sqrt price ratio (4295128739).
// It is a constructor (not a package-level var) so each caller receives a fresh
// instance rather than sharing a mutable singleton.
func MIN_SQRT_RATIO() *u256.Uint { return consts.MinSqrtRatio() }

// MAX_SQRT_RATIO returns the maximum valid sqrt price ratio
// (1461446703485210103287273052203988822378723970342). See MIN_SQRT_RATIO.
func MAX_SQRT_RATIO() *u256.Uint { return consts.MaxSqrtRatio() }

// getNextPriceAmount0Add calculates the next sqrt price when adding token0 liquidity,
// rounding up to ensure conservative pricing for the protocol.
// This internal function handles the case where token0 is being added to the pool.
func getNextPriceAmount0Add(
	currentSqrtPriceX96, liquidity, amountToAdd *u256.Uint,
) *u256.Uint {
	// liquidityShifted = liquidity << 96
	liquidityShifted := u256.Zero().Lsh(liquidity, Q96_RESOLUTION)
	// amountTimesSqrtPrice = amount * sqrtPrice
	amountTimesSqrtPrice := u256.Zero().Mul(amountToAdd, currentSqrtPriceX96)

	// Overflow check: Ensure (amountTimesSqrtPrice / amountToAdd) == currentSqrtPriceX96
	quotientCheck := u256.Zero().Div(amountTimesSqrtPrice, amountToAdd)
	if quotientCheck.Eq(currentSqrtPriceX96) {
		// denominator = liquidityShifted + amountTimesSqrtPrice
		denominator := u256.Zero().Add(liquidityShifted, amountTimesSqrtPrice)
		// only take this path when denominator >= liquidityShifted
		if denominator.Gte(liquidityShifted) {
			return u256.MulDivRoundingUp(liquidityShifted, currentSqrtPriceX96, denominator)
		}
	}

	// fallback: liquidityShifted / ((liquidityShifted / sqrtPrice) + amount)
	divValue := u256.Zero().Div(liquidityShifted, currentSqrtPriceX96)
	denominator := u256.Zero().Add(divValue, amountToAdd)
	return u256.DivRoundingUp(liquidityShifted, denominator)
}

// getNextPriceAmount0Remove calculates the next sqrt price when removing token0 liquidity,
// rounding up to ensure conservative pricing for the protocol.
// This internal function handles the case where token0 is being removed from the pool.
// Panics if validation checks fail (invalid pool sqrt price calculation).
func getNextPriceAmount0Remove(
	currentSqrtPriceX96, liquidity, amountToRemove *u256.Uint,
) *u256.Uint {
	// liquidityShifted = liquidity << 96
	liquidityShifted := u256.Zero().Lsh(liquidity, Q96_RESOLUTION)
	// amountTimesSqrtPrice = amountToRemove * currentSqrtPriceX96
	amountTimesSqrtPrice := u256.Zero().Mul(amountToRemove, currentSqrtPriceX96)

	// Validation checks
	quotientCheck := u256.Zero().Div(amountTimesSqrtPrice, amountToRemove)
	if !quotientCheck.Eq(currentSqrtPriceX96) || !liquidityShifted.Gt(amountTimesSqrtPrice) {
		panic(errInvalidPoolSqrtPrice)
	}

	denominator := u256.Zero().Sub(liquidityShifted, amountTimesSqrtPrice)
	return u256.MulDivRoundingUp(liquidityShifted, currentSqrtPriceX96, denominator)
}

// getNextSqrtPriceFromAmount0RoundingUp calculates the next sqrt price based on token0 amount,
// always rounding up to ensure conservative pricing in both exact output and exact input cases.
// The add parameter determines whether liquidity is being added (true) or removed (false).
func getNextSqrtPriceFromAmount0RoundingUp(
	sqrtPX96 *u256.Uint,
	liquidity *u256.Uint,
	amount *u256.Uint,
	add bool,
) *u256.Uint {
	// Shortcut: if no amount, return original price
	if amount.IsZero() {
		return sqrtPX96
	}

	if add {
		return getNextPriceAmount0Add(sqrtPX96, liquidity, amount)
	}
	return getNextPriceAmount0Remove(sqrtPX96, liquidity, amount)
}

// getNextPriceAmount1Add calculates the next sqrt price when adding token1,
// preserving rounding-down logic for the final result.
// This internal function handles the case where token1 is being added to the pool.
func getNextPriceAmount1Add(
	sqrtPX96, liquidity, amount *u256.Uint,
) *u256.Uint {
	var quotient *u256.Uint

	if amount.Lte(consts.Max160()) {
		// Use local variables to avoid allocation conflicts
		shifted := u256.Zero().Lsh(amount, Q96_RESOLUTION)
		quotient = u256.Zero().Div(shifted, liquidity)
	} else {
		quotient = u256.MulDiv(amount, consts.Q96(), liquidity)
	}

	result, overflow := u256.Zero().AddOverflow(sqrtPX96, quotient)
	if overflow || result.Gt(consts.Max160()) {
		panic(errSqrtPriceOverflow)
	}

	return result
}

// getNextPriceAmount1Remove calculates the next sqrt price when removing token1,
// preserving rounding-down logic for the final result.
// This internal function handles the case where token1 is being removed from the pool.
// Panics if sqrt price would exceed quotient.
func getNextPriceAmount1Remove(
	sqrtPX96, liquidity, amount *u256.Uint,
) *u256.Uint {
	var quotient *u256.Uint

	if amount.Lte(consts.Max160()) {
		shifted := u256.Zero().Lsh(amount, Q96_RESOLUTION)
		quotient = u256.DivRoundingUp(shifted, liquidity)
	} else {
		quotient = u256.MulDivRoundingUp(amount, consts.Q96(), liquidity)
	}

	if !sqrtPX96.Gt(quotient) {
		panic(errSqrtPriceExceedsQuotient)
	}

	return u256.Zero().Sub(sqrtPX96, quotient)
}

// getNextSqrtPriceFromAmount1RoundingDown calculates the next sqrt price based on token1 amount,
// always rounding down to ensure conservative pricing in both exact output and exact input cases.
// The add parameter determines whether liquidity is being added (true) or removed (false).
func getNextSqrtPriceFromAmount1RoundingDown(
	sqrtPX96,
	liquidity,
	amount *u256.Uint,
	add bool,
) *u256.Uint {
	// Shortcut: if no amount, return original price
	if amount.IsZero() {
		return sqrtPX96
	}

	if add {
		return getNextPriceAmount1Add(sqrtPX96, liquidity, amount)
	}
	return getNextPriceAmount1Remove(sqrtPX96, liquidity, amount)
}

// getNextSqrtPriceFromInput calculates the next sqrt price after adding tokens to the pool,
// rounding up for conservative pricing in both swap directions.
// The zeroForOne parameter indicates swap direction (token0 for token1 when true).
// Panics if sqrtPX96 or liquidity is zero.
func getNextSqrtPriceFromInput(
	sqrtPX96, liquidity, amountIn *u256.Uint,
	zeroForOne bool,
) *u256.Uint {
	if sqrtPX96.IsZero() {
		panic(errSqrtPriceZero)
	}

	if liquidity.IsZero() {
		panic(errLiquidityZero)
	}

	if zeroForOne {
		return getNextSqrtPriceFromAmount0RoundingUp(sqrtPX96, liquidity, amountIn, true)
	}

	return getNextSqrtPriceFromAmount1RoundingDown(sqrtPX96, liquidity, amountIn, true)
}

// getNextSqrtPriceFromOutput calculates the next sqrt price after removing tokens from the pool,
// using different rounding directions based on swap direction.
// The zeroForOne parameter indicates swap direction (token0 for token1 when true).
// Panics if sqrtPX96 or liquidity is zero.
func getNextSqrtPriceFromOutput(
	sqrtPX96, liquidity, amountOut *u256.Uint,
	zeroForOne bool,
) *u256.Uint {
	if sqrtPX96.IsZero() {
		panic(errSqrtPriceZero)
	}

	if liquidity.IsZero() {
		panic(errLiquidityZero)
	}

	if zeroForOne {
		return getNextSqrtPriceFromAmount1RoundingDown(sqrtPX96, liquidity, amountOut, false)
	}

	return getNextSqrtPriceFromAmount0RoundingUp(sqrtPX96, liquidity, amountOut, false)
}

// getAmount0DeltaHelper calculates the absolute token0 amount difference between two price ranges,
// automatically swapping inputs to ensure correct ordering. The roundUp parameter controls
// rounding direction for the final result to ensure conservative AMM calculations.
// Panics if sqrtRatioAX96 is zero.
func getAmount0DeltaHelper(
	sqrtRatioAX96, sqrtRatioBX96, liquidity *u256.Uint,
	roundUp bool,
) *u256.Uint {
	if sqrtRatioAX96.Gt(sqrtRatioBX96) {
		sqrtRatioAX96, sqrtRatioBX96 = sqrtRatioBX96, sqrtRatioAX96
	}

	// Use local variables for thread safety
	numerator := u256.Zero().Lsh(liquidity, Q96_RESOLUTION)
	difference := u256.Zero().Sub(sqrtRatioBX96, sqrtRatioAX96)

	if sqrtRatioAX96.IsZero() {
		panic(errSqrtRatioAX96Zero)
	}

	if roundUp {
		intermediate := u256.MulDivRoundingUp(numerator, difference, sqrtRatioBX96)
		return u256.DivRoundingUp(intermediate, sqrtRatioAX96)
	}

	intermediate := u256.MulDiv(numerator, difference, sqrtRatioBX96)
	return u256.Zero().Div(intermediate, sqrtRatioAX96)
}

// getAmount1DeltaHelper calculates the absolute token1 amount difference between two price ranges,
// automatically swapping inputs to ensure correct ordering. The roundUp parameter controls
// rounding direction for the final result to ensure conservative AMM calculations.
func getAmount1DeltaHelper(
	sqrtRatioAX96, sqrtRatioBX96, liquidity *u256.Uint,
	roundUp bool,
) *u256.Uint {
	if sqrtRatioAX96.Gt(sqrtRatioBX96) {
		sqrtRatioAX96, sqrtRatioBX96 = sqrtRatioBX96, sqrtRatioAX96
	}

	// amount1 = liquidity * (sqrtB - sqrtA) / 2^96
	// Use local variable for thread safety
	difference := u256.Zero().Sub(sqrtRatioBX96, sqrtRatioAX96)

	if roundUp {
		return u256.MulDivRoundingUp(liquidity, difference, consts.Q96())
	}

	return u256.MulDiv(liquidity, difference, consts.Q96())
}

// GetAmount0Delta calculates the token0 amount difference within a price range, returning
// a signed int256 value that is negative when liquidity is negative. Rounds down for
// negative liquidity and up for positive liquidity.
//
// Parameters:
//   - sqrtRatioAX96: first sqrt price in Q96 format
//   - sqrtRatioBX96: second sqrt price in Q96 format
//   - liquidity: signed liquidity value
//
// Returns the token0 amount difference as a signed int256 value.
//
// Panics if any input is nil or if the result overflows int256.
func GetAmount0Delta(
	sqrtRatioAX96, sqrtRatioBX96 *u256.Uint,
	liquidity *i256.Int,
) *i256.Int {
	if sqrtRatioAX96 == nil || sqrtRatioBX96 == nil || liquidity == nil {
		panic(errGetAmount0DeltaNilInput)
	}

	if liquidity.IsNeg() {
		u := getAmount0DeltaHelper(sqrtRatioAX96, sqrtRatioBX96, liquidity.Abs(), false)
		if u.Gt(consts.MaxInt256()) {
			// if u > (2**255 - 1), cannot cast to int256
			panic(errAmount0DeltaOverflow)
		}

		// Convert to i256 and negate properly
		return i256.Zero().Neg(i256.FromUint256(u))
	}

	u := getAmount0DeltaHelper(sqrtRatioAX96, sqrtRatioBX96, liquidity.Abs(), true)
	if u.Gt(consts.MaxInt256()) {
		// if u > (2**255 - 1), cannot cast to int256
		panic(errAmount0DeltaOverflow)
	}

	return i256.FromUint256(u)
}

// GetAmount1Delta calculates the token1 amount difference within a price range, returning
// a signed int256 value that is negative when liquidity is negative. Rounds down for
// negative liquidity and up for positive liquidity.
//
// Parameters:
//   - sqrtRatioAX96: first sqrt price in Q96 format
//   - sqrtRatioBX96: second sqrt price in Q96 format
//   - liquidity: signed liquidity value
//
// Returns the token1 amount difference as a signed int256 value.
//
// Panics if any input is nil or if the result overflows int256.
func GetAmount1Delta(
	sqrtRatioAX96, sqrtRatioBX96 *u256.Uint,
	liquidity *i256.Int,
) *i256.Int {
	if sqrtRatioAX96 == nil || sqrtRatioBX96 == nil || liquidity == nil {
		panic(errGetAmount1DeltaNilInput)
	}

	if liquidity.IsNeg() {
		u := getAmount1DeltaHelper(sqrtRatioAX96, sqrtRatioBX96, liquidity.Abs(), false)
		if u.Gt(consts.MaxInt256()) {
			// if u > (2**255 - 1), cannot cast to int256
			panic(errAmount1DeltaOverflow)
		}

		// Convert to i256 and negate properly
		return i256.Zero().Neg(i256.FromUint256(u))
	}

	u := getAmount1DeltaHelper(sqrtRatioAX96, sqrtRatioBX96, liquidity.Abs(), true)
	if u.Gt(consts.MaxInt256()) {
		// if u > (2**255 - 1), cannot cast to int256
		panic(errAmount1DeltaOverflow)
	}

	return i256.FromUint256(u)
}

package gnsmath

import (
	i256 "gno.land/p/gnoswap/int256"
	u256 "gno.land/p/gnoswap/uint256"
)

// denominator represents 100% in the fee calculation basis (1,000,000 = 100%).
// Fee calculations use this to convert feePips to actual percentages.
// For example, feePips=3000 means 3000/1000000 = 0.3% fee.
const denominator = uint64(1_000_000)

// SwapMathComputeSwapStep computes the next sqrt price, amount in, amount out, and fee amount
// for a swap step within a single tick range.
//
// Parameters:
//   - sqrtRatioCurrentX96: current sqrt price in Q96 format
//   - sqrtRatioTargetX96: target sqrt price (tick boundary)
//   - liquidity: available liquidity in the range
//   - amountRemaining: amount left to swap (positive=exact in, negative=exact out)
//   - feePips: fee in hundredths of a bip (3000 = 0.3%)
//
// Returns sqrtRatioNextX96, amountIn, amountOut, feeAmount.
//
// Panics if any input parameter is nil or if feePips >= 1000000.
func SwapMathComputeSwapStep(
	sqrtRatioCurrentX96 *u256.Uint,
	sqrtRatioTargetX96 *u256.Uint,
	liquidity *u256.Uint,
	amountRemaining *i256.Int,
	feePips uint64,
) (*u256.Uint, *u256.Uint, *u256.Uint, *u256.Uint) {
	if sqrtRatioCurrentX96 == nil || sqrtRatioTargetX96 == nil ||
		liquidity == nil || amountRemaining == nil {
		panic("SwapMathComputeSwapStep: input parameters cannot be nil")
	}

	// This function is publicly accessible and can be called by external users or contracts.
	// While the pool realm only uses predefined fee values (100, 500, 3000, 10000) which are safely within range,
	// external callers could potentially pass any feePips value. The fee calculation involves dividing by
	// (1000000 - feePips), so feePips must be strictly less than 1000000 to avoid division by zero.
	// This follows Uniswap V3's factory-level validation: require(fee < 1000000).
	if feePips >= denominator {
		panic("SwapMathComputeSwapStep: feePips must be less than 1000000")
	}

	// zeroForOne determines swap direction based on the relationship of current vs. target
	zeroForOne := sqrtRatioCurrentX96.Gte(sqrtRatioTargetX96)

	// POSITIVE == EXACT_IN => Estimated AmountOut
	// NEGATIVE == EXACT_OUT => Estimated AmountIn
	exactIn := !amountRemaining.IsNeg()

	amountRemainingAbs := amountRemaining.Abs()
	feeRateInPips := u256.NewUint(feePips)
	withoutFeeRateInPips := u256.NewUint(denominator - feePips)

	sqrtRatioNextX96 := u256.Zero()
	amountIn := u256.Zero()
	amountOut := u256.Zero()
	feeAmount := u256.Zero()

	if exactIn {
		// Handle EXACT_IN scenario as a separate function
		sqrtRatioNextX96, amountIn = handleExactIn(
			zeroForOne,
			sqrtRatioCurrentX96,
			sqrtRatioTargetX96,
			liquidity,
			amountRemainingAbs, // use absolute value here
			withoutFeeRateInPips,
		)
	} else {
		// Handle EXACT_OUT scenario as a separate function
		sqrtRatioNextX96, amountOut = handleExactOut(
			zeroForOne,
			sqrtRatioCurrentX96,
			sqrtRatioTargetX96,
			liquidity,
			amountRemainingAbs,
		)
	}

	// isMax checks if we've hit the boundary price (target)
	isMax := sqrtRatioTargetX96.Eq(sqrtRatioNextX96)

	// Calculate final amountIn, amountOut if needed
	if zeroForOne {
		// If isMax && exactIn, we already have the correct amountIn
		if !(isMax && exactIn) {
			amountIn = getAmount0DeltaHelper(
				sqrtRatioNextX96,
				sqrtRatioCurrentX96,
				liquidity,
				true,
			)
		}
		// If isMax && !exactIn, we already have the correct amountOut
		if !(isMax && !exactIn) {
			amountOut = getAmount1DeltaHelper(
				sqrtRatioNextX96,
				sqrtRatioCurrentX96,
				liquidity,
				false,
			)
		}
	} else {
		if !(isMax && exactIn) {
			amountIn = getAmount1DeltaHelper(
				sqrtRatioCurrentX96,
				sqrtRatioNextX96,
				liquidity,
				true,
			)
		}
		if !(isMax && !exactIn) {
			amountOut = getAmount0DeltaHelper(
				sqrtRatioCurrentX96,
				sqrtRatioNextX96,
				liquidity,
				false,
			)
		}
	}

	// If we're in EXACT_OUT mode but overcalculated 'amountOut'
	if !exactIn && amountOut.Gt(amountRemainingAbs) {
		amountOut = amountRemainingAbs
	}

	// Fee logic
	// If exactIn and we haven't hit the target, the difference is the fee
	// Else, compute fee from feePips
	if exactIn && !sqrtRatioNextX96.Eq(sqrtRatioTargetX96) {
		feeAmount = u256.Zero().Sub(amountRemainingAbs, amountIn)
	} else {
		feeAmount = u256.MulDivRoundingUp(
			amountIn,
			feeRateInPips,
			withoutFeeRateInPips,
		)
	}

	// Final sanity check for resulting price
	if sqrtRatioNextX96.Lt(MIN_SQRT_RATIO()) || sqrtRatioNextX96.Gt(MAX_SQRT_RATIO()) {
		panic(errInvalidPoolSqrtPrice)
	}

	return sqrtRatioNextX96, amountIn, amountOut, feeAmount
}

// handleExactIn handles the EXACT_IN scenario for swaps, returning the next sqrt price and
// a provisional amount. When the target price is reached, it returns the exact amount needed.
// When the target is not reached, it returns the amount needed to reach the target (which will
// be recalculated by the caller since we only moved partially).
// This internal function processes swaps where the input amount is specified exactly.
func handleExactIn(
	zeroForOne bool,
	sqrtRatioCurrentX96,
	sqrtRatioTargetX96,
	liquidity,
	amountRemainingAbs,
	withoutFeeRateInPips *u256.Uint,
) (*u256.Uint, *u256.Uint) {
	amountRemainingLessFee := u256.MulDiv(
		amountRemainingAbs,
		withoutFeeRateInPips,
		u256.NewUint(denominator),
	)

	// Special case:
	// When the remaining amount to be swapped becomes 1 during a tick swap,
	// the swap fee becomes less than 0.
	// At this point, check whether the swap is no longer being executed.
	if amountRemainingLessFee.IsZero() {
		return sqrtRatioCurrentX96, u256.Zero()
	}

	amountIn := u256.Zero()

	if zeroForOne {
		amountIn = getAmount0DeltaHelper(
			sqrtRatioTargetX96,
			sqrtRatioCurrentX96,
			liquidity,
			true,
		)
	} else {
		amountIn = getAmount1DeltaHelper(
			sqrtRatioCurrentX96,
			sqrtRatioTargetX96,
			liquidity,
			true,
		)
	}

	if amountRemainingLessFee.Gte(amountIn) {
		return sqrtRatioTargetX96, amountIn
	}

	// We don't reach target price; use partial move
	nextSqrt := getNextSqrtPriceFromInput(
		sqrtRatioCurrentX96,
		liquidity,
		amountRemainingLessFee,
		zeroForOne,
	)

	// Return the partially moved price and the amount to reach target (will be recalculated by caller)
	return nextSqrt, amountIn
}

// handleExactOut handles the EXACT_OUT scenario for swaps, returning the next sqrt price and
// a provisional amount. When the target price is reached, it returns the exact amount produced.
// When the target is not reached due to insufficient liquidity, it returns the amount that would
// be produced if we reached the target (which will be recalculated by the caller).
// This internal function processes swaps where the output amount is specified exactly.
func handleExactOut(
	zeroForOne bool,
	sqrtRatioCurrentX96, sqrtRatioTargetX96, liquidity, amountRemainingAbs *u256.Uint,
) (*u256.Uint, *u256.Uint) {
	amountOut := u256.Zero()

	if zeroForOne {
		amountOut = getAmount1DeltaHelper(sqrtRatioTargetX96, sqrtRatioCurrentX96, liquidity, false)
	} else {
		amountOut = getAmount0DeltaHelper(sqrtRatioCurrentX96, sqrtRatioTargetX96, liquidity, false)
	}

	// Fast path: if sufficient liquidity, use target price
	if amountRemainingAbs.Gte(amountOut) {
		return sqrtRatioTargetX96, amountOut
	}

	// Otherwise, partial move: compute next price from residual output amount
	// and return the amount to reach target (will be recalculated by caller)
	nextSqrt := getNextSqrtPriceFromOutput(
		sqrtRatioCurrentX96,
		liquidity,
		amountRemainingAbs,
		zeroForOne,
	)

	return nextSqrt, amountOut
}

package gnsmath

import (
	"errors"

	ufmt "gno.land/p/nt/ufmt/v0"

	"gno.land/p/gnoswap/consts"
	i256 "gno.land/p/gnoswap/int256"
	u256 "gno.land/p/gnoswap/uint256"
)

// Pre-calculated ratio constants for performance optimization.
//
// These were previously package-level vars (a slice plus 19 exposed pointers),
// the exact "globally exposed mutable array" anti-pattern. They are now
// constructors: each call returns freshly allocated values built from
// little-endian [4]uint64 literals, so no caller shares a mutable instance and
// no runtime decimal parsing happens. Values match Uniswap V3 exactly.

// initialRatio returns the LSB-selected initial ratio.
// absTick&0x1 != 0 selects ratio0 (0xfffcb933bd6fad37aa2d162d1a594001),
// otherwise ratio1 (2^128).
func initialRatio(odd bool) *u256.Uint {
	if odd {
		return &u256.Uint{12262481743371124737, 18445821805675392311, 0, 0} // 0xfffcb933bd6fad37aa2d162d1a594001
	}
	return &u256.Uint{0, 0, 1, 0} // 0x100000000000000000000000000000000 (2^128)
}

// ratioConstants returns the bit-mask ratio constants in order (bit 1 to bit 19).
func ratioConstants() []*u256.Uint {
	return []*u256.Uint{
		&u256.Uint{6459403834229662010, 18444899583751176498, 0, 0},  // 0xfff97272373d413259a46990580e213a (bit 1)
		&u256.Uint{17226890335427755468, 18443055278223354162, 0, 0}, // 0xfff2e50f5f656932ef12357cf3c7fdcc (bit 2)
		&u256.Uint{2032852871939366096, 18439367220385604838, 0, 0},  // 0xffe5caca7e10e4e61c3624eaa0941cd0 (bit 3)
		&u256.Uint{14545316742740207172, 18431993317065449817, 0, 0}, // 0xffcb9843d60f6159c9db58835c926644 (bit 4)
		&u256.Uint{5129152022828963008, 18417254355718160513, 0, 0},  // 0xff973b41fa98c081472e6896dfb254c0 (bit 5)
		&u256.Uint{4894419605888772193, 18387811781193591352, 0, 0},  // 0xff2ea16466c96a3843ec78b326b52861 (bit 6)
		&u256.Uint{1280255884321894483, 18329067761203520168, 0, 0},  // 0xfe5dee046a99a2a811c461f1969c3053 (bit 7)
		&u256.Uint{15924666964335305636, 18212142134806087854, 0, 0}, // 0xfcbe86c7900a88aedcffc83b479aa3a4 (bit 8)
		&u256.Uint{8010504389359918676, 17980523815641551639, 0, 0},  // 0xf987a7253ac413176f2b074cf7815e54 (bit 9)
		&u256.Uint{10668036004952895731, 17526086738831147013, 0, 0}, // 0xf3392b0822b70005940c7a398e4b70f3 (bit 10)
		&u256.Uint{4878133418470705625, 16651378430235024244, 0, 0},  // 0xe7159475a2c29b7443b29c7fa6e889d9 (bit 11)
		&u256.Uint{9537173718739605541, 15030750278693429944, 0, 0},  // 0xd097f3bdfd2022b8845ad8f792aa5825 (bit 12)
		&u256.Uint{9972618978014552549, 12247334978882834399, 0, 0},  // 0xa9f746462d870fdf8a65dc1f90e061e5 (bit 13)
		&u256.Uint{10428997489610666743, 8131365268884726200, 0, 0},  // 0x70d869a156d2a1b890bb3df62baf32f7 (bit 14)
		&u256.Uint{9305304367709015974, 3584323654723342297, 0, 0},   // 0x31be135f97d08fd981231505542fcfa6 (bit 15)
		&u256.Uint{14301143598189091785, 696457651847595233, 0, 0},   // 0x9aa508b5b7a84e1c677de54f3e99bc9 (bit 16)
		&u256.Uint{7393154844743099908, 26294789957452057, 0, 0},     // 0x5d6af8dedb81196699c329225ee604 (bit 17)
		&u256.Uint{2209338891292245656, 37481735321082, 0, 0},        // 0x2216e584f5fa1ea926041bedfe98 (bit 18)
		&u256.Uint{10518117631919034274, 76158723, 0, 0},             // 0x48a170391f7dc42444e8fa2 (bit 19)
