// castToInt64 safely casts an any value to int64
// Returns ErrFailedCast if the value is not of type int64
func castToInt64(result any) (int64, error) {
	v, ok := result.(int64)
	if !ok {
		return 0, ufmt.Errorf("%s: %s", ErrFailedCast, ufmt.Sprintf("cast %T to int64", result))
	}

	return v, nil
}

// castToUint64 safely casts an any value to uint64
// Returns ErrFailedCast if the value is not of type uint64
func castToUint64(result any) (uint64, error) {
	v, ok := result.(uint64)
	if !ok {
		return 0, ufmt.Errorf("%s: %s", ErrFailedCast, ufmt.Sprintf("cast %T to uint64", result))
	}

	return v, nil
}

// castToBool safely casts an any value to bool
// Returns ErrFailedCast if the value is not of type bool
func castToBool(result any) (bool, error) {
	v, ok := result.(bool)
	if !ok {
		return false, ufmt.Errorf("%s: %s", ErrFailedCast, ufmt.Sprintf("cast %T to bool", result))
	}

	return v, nil
}

// castToString safely casts an any value to string
// Returns ErrFailedCast if the value is not of type string
func castToString(result any) (string, error) {
	v, ok := result.(string)
	if !ok {
		return "", ufmt.Errorf("%s: %s", ErrFailedCast, ufmt.Sprintf("cast %T to string", result))
	}

	return v, nil
}

// castToBPTree safely casts an any value to *bptree.BPTree
// Returns ErrFailedCast if the value is not of type *bptree.BPTree
func castToBPTree(result any) (*bptree.BPTree, error) {
	tree, ok := result.(*bptree.BPTree)
	if !ok {
		return nil, ufmt.Errorf("%s: %s", ErrFailedCast, ufmt.Sprintf("cast %T to *bptree.BPTree", result))
	}

	return tree, nil
}

// castToAddress safely casts an any value to address
// Returns ErrFailedCast if the value is not of type address
func castToAddress(result any) (address, error) {
	v, ok := result.(address)
	if !ok {
		return address(""), ufmt.Errorf("%s: %s", ErrFailedCast, ufmt.Sprintf("cast %T to address", result))
	}

	return v, nil
}

// Package version_manager provides a runtime version management system for dynamic
// implementation switching without data migration. It implements the Strategy Pattern
// combined with Plugin Architecture to enable hot-swapping between different versioned
// implementations of the same domain.
//
// ## Overview
//
// Version Manager enables seamless upgrades by allowing multiple versioned implementations
// (v1, v2, v3) to coexist and share a unified storage layer. The domain
// (proxy) realm owns that storage; the manager records version initializers and
// swaps the active implementation reference without granting implementation
// realms direct write permission.
//
// Key components of this package include:
//
//  1. **VersionManager Interface**: Defines the contract for managing multiple versioned
//     implementations of a domain.
//  2. **versionManager Implementation**: Concrete implementation that manages version
//     registration and active implementation switching.
//  3. **Realm-Threaded Validation**: Validates live realm tokens and restricts
//     registration to packages under the configured domain path.
//  4. **Domain-Scoped Security**: Ensures only authorized packages within the domain
//     path can register implementations.
//
// ## Key Features
//
//   - **Zero-Downtime Upgrades**: Switch implementations at runtime without service
//     interruption or data migration.
//   - **Unified Storage**: All versions share a single KVStore owned by the
//     domain (proxy) realm, eliminating migration overhead.
//   - **Hot-Swapping**: Instant version switching through dynamic strategy replacement
//     with explicit realm validation.
//   - **Domain-Scoped Security**: Only packages under the authorized domain path can
//     register implementations, preventing unauthorized access.
//   - **Backward Compatibility**: Previous versions remain registered for
//     gradual migration and rollback support.
//   - **Strategy Pattern**: Enables runtime algorithm swapping without code changes.
//
// ## Architecture Pattern
//
// The package implements two complementary design patterns:
//
//   - **Strategy Pattern**: Enables runtime selection of implementation strategies
//   - **Plugin Architecture**: Supports dynamic loading and registration of versions
//
// ## Workflow
//
// Typical usage of the version_manager package includes the following steps:
//
//  1. **Initialization**: Create a version manager for the domain using NewVersionManager.
//  2. **Version Registration**: Each version (v1, v2, v3) calls RegisterInitializer during
//     its init(cur realm) function to register its implementation.
//  3. **Active Implementation**: The first registered version becomes the active implementation;
//     subsequent versions are retained for later switching.
//  4. **Version Switching**: Use ChangeImplementation to hot-swap to a different version
//     while storage ownership stays with the domain KVStore.
//
// ## Example Usage
//
// ### Step 1: Define Domain Interface
//
// ```gno
// // protocol_fee/types.gno
// package protocol_fee
//
//	type ProtocolFee interface {
//	    SetFeeRatio(ratio uint64) error
//	    GetFeeRatio() uint64
//	}
//
// ```
//
// ### Step 2: Create Version Manager
//
// ```gno
// // protocol_fee/protocol_fee.gno
// package protocol_fee
//
// import (
//
//	"gno.land/p/gnoswap/version_manager"
//	"gno.land/p/gnoswap/store"
//
// )
//
//	var manager version_manager.VersionManager
//
//	func init(cur realm) {
//	    kvStore := store.NewKVStore(cur.Address())
//
//	    manager = version_manager.NewVersionManager(
//	        cur.PkgPath(),
//	        kvStore,
//	        func(_ int, rlm realm, kv store.KVStore) any {
//	            return NewProtocolFeeStore(kv)
//	        },
//	    )
//	}
//
//	func GetManager() version_manager.VersionManager {
//	    return manager
//	}
//
// ```
//
// ### Step 3: Implement Version 1
//
// ```gno
// // protocol_fee/v1/v1.gno
// package v1
//
// import "gno.land/r/gnoswap/protocol_fee"
//
// type protocolFeeV1 struct {
//
//	store any
//
// }
//
//	func init(cur realm) {
//	    // Register this version during package initialization.
//	    protocol_fee.RegisterInitializer(cross(cur), func(_ int, rlm realm, store any) any {
//	        return &protocolFeeV1{store: store}
//	    })
//	}
//
//	func (pf *protocolFeeV1) SetFeeRatio(ratio uint64) error {
//	    // v1 implementation
//	    return nil
//	}
//
//	func (pf *protocolFeeV1) GetFeeRatio() uint64 {
//	    // v1 implementation
//	    return 0
//	}
//
// ```
//
// ### Step 4: Implement Version 2
//
// ```gno
// // protocol_fee/v2/v2.gno
// package v2
//
// import "gno.land/r/gnoswap/protocol_fee"
//
// type protocolFeeV2 struct {
//
//	store any
//
// }
//
//	func init(cur realm) {
//	    // Register v2 - inactive until explicitly activated.
//	    protocol_fee.RegisterInitializer(cross(cur), func(_ int, rlm realm, store any) any {
//	        return &protocolFeeV2{store: store}
//	    })
//	}
//
//	func (pf *protocolFeeV2) SetFeeRatio(ratio uint64) error {
//	    // v2 improved implementation
//	    return nil
//	}
//
//	func (pf *protocolFeeV2) GetFeeRatio() uint64 {
//	    // v2 improved implementation
//	    return 0
//	}
//
// ```
//
// ### Step 5: Use Active Implementation
//
// ```gno
// // client code
// import "gno.land/r/gnoswap/protocol_fee"
//
//	func UseFee() {
//	    manager := protocol_fee.GetManager()
//	    impl := manager.GetCurrentImplementation().(protocol_fee.ProtocolFee)
//
//	    ratio := impl.GetFeeRatio()
//	    // Use the active version's implementation
//	}
//
// ```
//
// ### Step 6: Switch Versions at Runtime
//
// ```gno
// // governance or admin function
//
//	func UpgradeToV2(cur realm) {
//	    // Hot-swap to v2 - zero downtime.
//	    protocol_fee.UpgradeImpl(cross(cur), "gno.land/r/gnoswap/protocol_fee/v2")
//	}
//
// ```
//
// ## Registration Flow
//
// The version registration process follows this sequence:
//
//  1. Domain package initializes version manager with KVStore
//     ↓
//  2. v1 package calls the domain registration wrapper during init(cur realm)
//     → Becomes the active implementation
//     ↓
//  3. v2 package calls the domain registration wrapper during init(cur realm)
//     → Registered for later activation
//     ↓
//  4. v3 package calls the domain registration wrapper during init(cur realm)
//     → Registered for later activation
//
// ## Version Switching Flow
//
// When switching versions, the following steps occur:
//
//  1. Admin/governance calls the domain upgrade wrapper
//     ↓
//  2. The domain wrapper enforces authorization and calls ChangeImplementation(0, cur, ...)
//     ↓
//  3. Version Manager validates the live realm token and retrieves v2's initializer
//     ↓
//  4. Executes v2 initializer with the shared KVStore
//     ↓
//  5. Updates currentPackagePath and currentImplementation
//
// ## Storage Access Model
//
// The version manager keeps storage ownership with the domain (proxy) realm:
//
//   - **Domain Ownership**: The domain realm owns the KVStore and drives writes.
//   - **No Direct Grants**: Implementation realms do not receive direct storage
//     permissions from version_manager.
//   - **Explicit Realm Threading**: Registration and switching calls validate the
//     live realm token with `rlm.IsCurrent()` and identify the caller with
//     `rlm.Previous()`.
//   - **Domain Isolation**: Registration is scoped to packages under the domain path.
//
// ## Security
//
// Domain-scoped security ensures that only authorized packages can register:
//
//   - **Path Validation**: Caller's package path must start with the domain path + "/"
//   - **Realm Verification**: Only realm (contract) code can register, not user calls
//   - **Example**: For domain "gno.land/r/gnoswap/protocol_fee":
//   - Valid: "gno.land/r/gnoswap/protocol_fee/v1", "gno.land/r/gnoswap/protocol_fee/v2"
//   - Invalid: "gno.land/r/gnoswap/other", "gno.land/r/attacker/malicious"
//
// ## Error Handling
//
// The package returns errors for:
//
//   - Unauthorized caller attempting to register (not in domain path)
//   - Duplicate registration of the same package path
//   - Attempting to switch to an unregistered version
//   - Invalid initializer function type
//
// ## Best Practices
//
//  1. **Version Registration**: All versions should register during init(cur realm) to ensure
//     they're available before any runtime operations.
//  2. **Interface Compliance**: Ensure all versions implement the same domain interface
//     for seamless switching.
//  3. **Storage Compatibility**: Design storage schema to be forward and backward
//     compatible across versions to prevent data corruption.
//  4. **Testing**: Thoroughly test version switching in a staging environment before
//     production use.
//  5. **Rollback Support**: Keep previous versions registered to enable quick rollback
//     if issues are detected in new versions.
//  6. **Type Assertions**: Always check type assertions when retrieving the current
//     implementation to prevent runtime panics.
//
// ## Use Cases
//
// ### Protocol Upgrades
//
// Upgrade DeFi protocol logic without disrupting active users:
//
//	manager.ChangeImplementation(0, cur, "gno.land/r/gnoswap/protocol_fee/v2")
//
// ### A/B Testing
//
// Test new implementations before full rollout:
//
//	// Switch to experimental version
//	manager.ChangeImplementation(0, cur, "gno.land/r/gnoswap/protocol_fee/experimental")
//
//	// Rollback if issues detected
//	manager.ChangeImplementation(0, cur, "gno.land/r/gnoswap/protocol_fee/v1")
//
// ### Emergency Response
//
// Quickly switch to a patched version during security incidents:
//
//	manager.ChangeImplementation(0, cur, "gno.land/r/gnoswap/protocol_fee/v1_hotfix")
//
// ## Limitations and Considerations
//
//   - **Type Safety**: Requires runtime type assertion to domain interface. No compile-time
//     type checking for implementation compatibility.
//   - **Atomic Switching**: Initializer side effects during ChangeImplementation are not
//     transactionally rolled back on partial failure. Manual recovery may be required.
//   - **Storage Schema**: Requires careful schema design for cross-version compatibility.
//     Breaking schema changes require migration or careful version ordering.
//   - **Registration Order**: The first registered version automatically becomes the
//     active implementation. Plan your deployment order carefully.
//   - **No Unregistration**: Once registered, a version cannot be unregistered. Plan
//     version lifecycles accordingly.
//
// ## Related Packages
//
//   - gno.land/p/gnoswap/store: Provides KVStore with permission-based access control
//
// Package version_manager is intended for use in Gno smart contracts requiring
// dynamic, upgradeable implementations with zero-downtime version switching.
package version_manager

package version_manager

// VersionManager defines the interface for managing multiple versioned implementations of a domain.
// It enables the Strategy Pattern at the package level, allowing runtime switching between
// different versions (v1, v2, v3, etc.) without requiring data migration.
//
// Design Goals:
//   - Enable zero-downtime upgrades through hot-swapping implementations
//   - Maintain a single source of truth for storage across all versions
//   - Enforce security through domain-scoped registration
//   - Support backward compatibility by keeping old versions registered for later activation
//
// Implementation Note:
// The actual implementations of each version must satisfy a common domain interface
// defined by the specific domain (e.g., ProtocolFee interface for protocol_fee domain).
type VersionManager interface {
	// RegisterInitializer registers a version's implementation.
	// Must be called by each version package during initialization.
	// First registration becomes the active implementation.
	// Subsequent registrations are retained for later switching.
	//
	// The leading `_ int, rlm realm` is the v2 interrealm-spec marker pattern:
	// the `0` sentinel surfaces at every call site so the realm threading is
	// visible to the reader, and rlm is the live crossing-frame token that
	// the implementation validates via rlm.IsCurrent() and reads via
	// rlm.Previous() to identify the version package.
	RegisterInitializer(_ int, rlm realm, initializer func(_ int, rlm realm, store any) any) error

	// ChangeImplementation switches the active version at runtime.
	// This enables hot-swapping without downtime or data migration while storage
	// ownership stays with the domain KVStore.
	//
	// The leading `_ int, rlm realm` is the v2 interrealm-spec marker pattern;
	// rlm is validated via rlm.IsCurrent() to reject spoofed/stale tokens.
	// Upgrade ACLs live in the wrapping /r/ realm, not here.
	ChangeImplementation(_ int, rlm realm, packagePath string) error

	// GetDomainPath returns the base domain path (e.g., "gno.land/r/gnoswap/protocol_fee")
	GetDomainPath() string

	// GetInitializers returns all registered version initializers
	GetInitializers() map[string]func(_ int, rlm realm, store any) any

	// GetCurrentPackagePath returns the package path of the active implementation
	GetCurrentPackagePath() string

	// GetCurrentImplementation returns the active version instance
	// The caller should type-assert this to the domain-specific interface
	GetCurrentImplementation() any
}

// Package version_manager implements a runtime version management system using the Strategy Pattern.
// It enables dynamic switching between different implementation versions of the same domain (e.g., v1, v2, v3)
// while maintaining a unified storage layer. This approach allows for seamless upgrades without migration overhead.
//
// Key Features:
//   - Dynamic implementation registration and switching
//   - Domain-scoped security (only authorized packages can register)
//   - Zero-downtime upgrades through hot-swapping
//
// Architecture Pattern: Strategy + Plugin Architecture
package version_manager

import (
	"chain"
	"errors"
	"strings"

	"gno.land/p/gnoswap/store"
)

// ErrSpoofedRealm is returned when the supplied realm token does not match the
// live crossing frame (rlm.IsCurrent() == false). It signals a stale or
// spoofed token captured in an earlier frame.
const ErrSpoofedRealm = "rlm does not match the current crossing frame"

// versionManager is the concrete implementation of VersionManager interface.
// It manages multiple versioned implementations of a domain (e.g., protocol_fee/v1, protocol_fee/v2).
//
// Storage Access Model:
// Implementation realms do NOT receive direct storage permissions. Instead, when calls flow
// from the domain proxy to the implementation, the proxy realm (which has write permission
// to the KVStore) is the one that drives the storage. This design prevents external callers
// from directly invoking implementation realms to modify storage.
type versionManager struct {
	// initializers stores registered initializer functions keyed by package path
	// Each initializer bootstraps a specific version's implementation
	initializers map[string]func(_ int, rlm realm, store any) any

	// domainKVStore is the shared storage layer accessible by all versions
	// The domain (proxy) realm is the owner and has write permission
	domainKVStore store.KVStore

	// initializeDomainStoreFn wraps the KVStore into domain-specific storage interface
	// This abstraction decouples the version manager from domain-specific storage implementations
	initializeDomainStoreFn func(_ int, rlm realm, kvStore store.KVStore) any

	// domainPath defines the base path for this domain (e.g., "gno.land/r/gnoswap/protocol_fee")
	// Used for security validation to ensure only authorized packages can register
	domainPath string

	// currentPackagePath holds the package path of the active implementation
	// (e.g., "gno.land/r/gnoswap/protocol_fee/v2")
	currentPackagePath string

	// currentImplementation is the active version's instance
	currentImplementation any
}

// RegisterInitializer registers a new version implementation for the domain.
// This method must be called by each version package (e.g., v1, v2) during initialization.
//
// The registration process:
//  1. Validates the realm token is the live crossing frame (rejects spoofed tokens)
//  2. Validates the caller is within the authorized domain path
//  3. Stores the initializer function for later version switching
//
// Parameters:
//   - rlm: the live realm token threaded in by the caller; rlm.Previous() identifies the
//     version package that is registering. The leading `_ int` is a v2 sentinel that surfaces
//     as a `0` at every call site so the realm-threading is visible to the reader.
//   - initializer: A function that receives a storage interface and returns an implementation instance
//
// Returns:
//   - error: If realm token is spoofed, caller is unauthorized, already registered, or initializer is nil
//
// Security: Only packages under the domainPath prefix can register (enforced by isContainDomainPath).
func (vm *versionManager) RegisterInitializer(_ int, rlm realm, initializer func(_ int, rlm realm, store any) any) error {
	if !rlm.IsCurrent() {
		return errors.New(ErrSpoofedRealm)
	}

	// Validate initializer is not nil to prevent panic during initialization
	if initializer == nil {
		return errors.New("version_manager: initializer cannot be nil")
	}

	// Ensure the caller is within the domain path (e.g., protocol_fee/v1, protocol_fee/v2).
	// rlm.Previous() corresponds to v1's runtime.PreviousRealm().
	previousRealm := rlm.Previous()
	if previousRealm.IsUser() {
		return errors.New("version_manager: caller cannot be user")
	}

	targetPackagePath := previousRealm.PkgPath()
	if !vm.isContainDomainPath(targetPackagePath) {
		return errors.New("version_manager: caller is not in the domain path")
	}

	// Check if this package path has already been registered
	if _, ok := vm.initializers[targetPackagePath]; ok {
		return errors.New("version_manager: initializer already registered")
	}

	// Register the initializer function for this package path
	vm.initializers[targetPackagePath] = initializer

	chain.Emit(
		"RegisterInitializer",
		"domainPath", vm.domainPath,
		"registeredPackagePath", targetPackagePath,
	)

	// Initialize the current implementation if it hasn't been done yet
	if vm.currentPackagePath == "" || vm.currentImplementation == nil {
		vm.currentPackagePath = targetPackagePath
		vm.currentImplementation = initializer(0, rlm, vm.initializeDomainStoreFn(0, rlm, vm.domainKVStore))

		chain.Emit(
			"InitializeImplementation",
			"domainPath", vm.domainPath,
			"newPackagePath", targetPackagePath,
		)
	}

	return nil
}

// ChangeImplementation performs a hot-swap to a different version implementation.
// This enables zero-downtime upgrades by switching the active implementation at runtime.
//
// The switching process:
//  1. Validates the realm token is the live crossing frame (rejects spoofed tokens)
//  2. Validates the target version has been registered via RegisterInitializer
//  3. Retrieves and executes the target version's initializer
//
// Authorization is the caller realm's responsibility — version_manager only rejects
// spoofed realm tokens. Upgrade ACLs (admin / governance) live in the wrapping /r/ realm
// (see each module's upgrade.gno).
//
// Parameters:
//   - rlm: the live realm token threaded in by the caller. The leading `_ int` is a v2
//     sentinel that surfaces as a `0` at every call site so the realm-threading is visible.
//   - packagePath: The full package path of the target version (e.g., "gno.land/r/gnoswap/protocol_fee/v2")
//
// Returns:
//   - error: If realm token is spoofed, target version is not registered, or initializer is invalid
func (vm *versionManager) ChangeImplementation(_ int, rlm realm, packagePath string) error {
	if !rlm.IsCurrent() {
		return errors.New(ErrSpoofedRealm)
	}

	// Retrieve the registered initializer function
	initializer, ok := vm.initializers[packagePath]
	if !ok {
		return errors.New("version_manager: initializer not found for package path:" + packagePath)
	}

	if initializer == nil {
		return errors.New("version_manager: initializer is not a function")
	}

	prevPackagePath := vm.currentPackagePath
	vm.currentPackagePath = packagePath
	vm.currentImplementation = initializer(0, rlm, vm.initializeDomainStoreFn(0, rlm, vm.domainKVStore))

	chain.Emit(
		"ChangeImplementation",
		"domainPath", vm.domainPath,
		"previousPackagePath", prevPackagePath,
		"newPackagePath", packagePath,
	)

	return nil
}

// GetDomainPath returns the base domain path for this version manager.
// Example: "gno.land/r/gnoswap/protocol_fee"
func (vm *versionManager) GetDomainPath() string {
	return vm.domainPath
}

// GetInitializers returns the map containing all registered initializer functions.
// Keys are package paths, values are initializer functions.
// Useful for inspecting which versions are available.
func (vm *versionManager) GetInitializers() map[string]func(_ int, rlm realm, store any) any {
	return vm.initializers
}

// GetCurrentPackagePath returns the package path of the currently active implementation.
func (vm *versionManager) GetCurrentPackagePath() string {
	return vm.currentPackagePath
}

// GetCurrentImplementation returns the instance of the currently active version.
// The returned value should be type-asserted to the domain-specific interface.
func (vm *versionManager) GetCurrentImplementation() any {
	return vm.currentImplementation
}

// isContainDomainPath checks if the calling contract is within the authorized domain path.
// This is a critical security check that prevents unauthorized external contracts from
// registering implementations.
//
// Validation rules:
//   - Package path must start with domainPath + "/"
//
// Example:
//   - domainPath: "gno.land/r/gnoswap/protocol_fee"
//   - Valid callers: "gno.land/r/gnoswap/protocol_fee/v1", "gno.land/r/gnoswap/protocol_fee/v2"
//   - Invalid callers: "gno.land/r/gnoswap/other", "gno.land/r/attacker/malicious"
func (vm *versionManager) isContainDomainPath(targetPackagePath string) bool {
	// `domainPath` is set via the current realm's PkgPath in each contract.
	// Therefore, there is no need for a separate trailing slash check,
	// and the prefix is determined by directly appending `/` for version detection.
	prefix := vm.domainPath + "/"

	return strings.HasPrefix(targetPackagePath, prefix)
}

// NewVersionManager creates a new version manager instance for a specific domain.
// This should be called once per domain during system initialization.
//
// Parameters:
//
//   - domainPath: The base package path for the domain (e.g., "gno.land/r/gnoswap/protocol_fee")
//     Used for access control to ensure only authorized packages can register
//
//   - kvStore: The shared key-value store that all versions will access
//     The domain realm (proxy) is the owner and has write permission to this store
//
//   - initializeDomainStoreFn: A factory function that wraps the KVStore into a domain-specific storage interface
//     This abstraction allows each version to work with a familiar storage API
//     Example: func(_ int, rlm realm, kvStore store.KVStore) any { return NewProtocolFeeStore(kvStore) }
//
// Returns:
//   - VersionManager: An initialized version manager ready to accept implementation registrations
//
// Usage Pattern:
//  1. Create version manager in parent domain package
//  2. Each version (v1, v2, v3) calls RegisterInitializer during their init()
//  3. Use ChangeImplementation to switch between versions at runtime
func NewVersionManager(
	domainPath string,
	kvStore store.KVStore,
	initializeDomainStoreFn func(_ int, rlm realm, kvStore store.KVStore) any,
) VersionManager {
	return &versionManager{
		domainPath:              domainPath,
		domainKVStore:           kvStore,
		initializeDomainStoreFn: initializeDomainStoreFn,
		initializers:            make(map[string]func(_ int, rlm realm, store any) any),
		currentPackagePath:      "",
		currentImplementation:   nil,
	}
}

package utils

import (
	"strconv"

	ufmt "gno.land/p/nt/ufmt/v0"
)

// FormatInt converts any signed integer type to its base-10 string
// representation. It accepts int8, int16, int32, int64 and int, and panics on
// any other type.
func FormatInt(v any) string {
	switch v := v.(type) {
	case int8:
		return strconv.FormatInt(int64(v), 10)
	case int16:
		return strconv.FormatInt(int64(v), 10)
	case int32:
		return strconv.FormatInt(int64(v), 10)
	case int64:
		return strconv.FormatInt(v, 10)
	case int:
		return strconv.Itoa(v)
	default:
		panic(ufmt.Sprintf("invalid type for FormatInt: %T", v))
	}
}

// FormatUint converts any unsigned integer type to its base-10 string
// representation. It accepts uint8, uint16, uint32, uint64 and uint, and panics
// on any other type.
func FormatUint(v any) string {
	switch v := v.(type) {
	case uint8:
		return strconv.FormatUint(uint64(v), 10)
	case uint16:
		return strconv.FormatUint(uint64(v), 10)
	case uint32:
		return strconv.FormatUint(uint64(v), 10)
	case uint64:
		return strconv.FormatUint(v, 10)
	case uint:
		return strconv.FormatUint(uint64(v), 10)
	default:
		panic(ufmt.Sprintf("invalid type for FormatUint: %T", v))
	}
}

// FormatBool converts a boolean to "true" or "false".
func FormatBool(v bool) string {
	return strconv.FormatBool(v)
}

// Uint64ToString returns the base-10 string representation of a uint64.
func Uint64ToString(v uint64) string {
	return strconv.FormatUint(v, 10)
}

// Int64ToString returns the base-10 string representation of an int64.
func Int64ToString(v int64) string {
	return strconv.FormatInt(v, 10)
}

// SafeParseInt64 parses a base-10 string into an int64, panicking when the
// input is not a valid int64.
func SafeParseInt64(value string) int64 {
	parsed, err := strconv.ParseInt(value, 10, 64)
	if err != nil {
		panic(err)
	}

	return parsed
}

package access

import (
	"chain"
	"strings"

	ufmt "gno.land/p/nt/ufmt/v0"
)

var roleAddresses map[string]address

func init() {
	roleAddresses = make(map[string]address)
}

// SetRoleAddress sets or updates a role's address.
// Creates the role if it doesn't exist, updates it if it does.
//
// Parameters:
//   - cur: current realm
//   - roleName: name of the role
//   - roleAddress: address for the role
//
// Only callable by RBAC contract.
func SetRoleAddress(cur realm, roleName string, roleAddress address) {
	prev := cur.Previous()
	assertIsRBAC(prev.Address())

	// capture old value for event
	oldAddr, _ := roleAddresses[strings.TrimSpace(roleName)]

	if err := setRoleAddress(roleName, roleAddress); err != nil {
		panic(err)
	}

	chain.Emit(
		"SetRoleAddress",
		"prevAddr", prev.Address().String(),
		"role", roleName,
		"prevRoleAddr", oldAddr.String(),
		"roleAddress", roleAddress.String(),
	)
}

// setRoleAddress is the internal implementation of SetRoleAddress.
// Separated for testability.
func setRoleAddress(roleName string, roleAddress address) error {
	roleName = strings.TrimSpace(roleName)
	if roleName == "" {
		panic("role name cannot be empty")
	}

	// Validate address
	if !roleAddress.IsValid() || roleAddress == address("") {
		return ufmt.Errorf(errInvalidAddress, roleName, roleAddress)
	}

	roleAddresses[roleName] = roleAddress
	return nil
}

// RemoveRole removes a role from the system.
//
// Parameters:
//   - roleName: name of the role to remove
//
// Only callable by RBAC contract.
func RemoveRole(cur realm, roleName string) {
	prev := cur.Previous()
	assertIsRBAC(prev.Address())

	// Validate role name
	roleName = strings.TrimSpace(roleName)
	if roleName == "" {
		panic("role name cannot be empty")
	}

	if _, ok := roleAddresses[roleName]; !ok {
		panic(ufmt.Errorf("role %s does not exist", roleName))
	}

	delete(roleAddresses, roleName)

	chain.Emit(
		"RemoveRole",
		"prevAddr", prev.Address().String(),
		"role", roleName,
	)
}

// IsAuthorized checks if caller has the specified role.
//
// Parameters:
//   - role: role name to check
//   - caller: address to verify
//
// Returns true if authorized, false otherwise.
func IsAuthorized(role string, caller address) bool {
	addr, ok := GetAddress(role)
	if !ok {
		return false
	}

	return caller == addr
}

// GetAddress returns the address for a role and whether it exists.
func GetAddress(role string) (address, bool) {
	role = strings.TrimSpace(role)
	addr, ok := roleAddresses[role]
	return addr, ok
}

// GetRoleAddresses returns a copy of all role addresses.
func GetRoleAddresses() map[string]address {
	addresses := make(map[string]address)

	for role, data := range roleAddresses {
		addresses[role] = data
	}

	return addresses
}

// MustGetAddress returns the address for a role or panics if it doesn't exist.
// Use this when the role is expected to exist and failure is critical.
func MustGetAddress(role string) address {
	role = strings.TrimSpace(role)
	addr, ok := GetAddress(role)
	if !ok {
		panic(ufmt.Errorf(errRoleNotFound, role))
	}

	return addr
}

