}

// GetInitialMintAmount returns the initial amount of gns tokens to be minted.
func GetInitialMintAmount() int64 {
	return INITIAL_MINT_AMOUNT
}

// IsEmissionInitialized returns true if emission schedule has been initialized.
func IsEmissionInitialized() bool {
	return getEmissionState().isInitialized()
}

// IsEmissionActive returns true if emission is currently active based on current time.
func IsEmissionActive() bool {
	return getEmissionState().isActive(time.Now().Unix())
}

// IsEmissionEnded returns true if emission schedule has completed.
func IsEmissionEnded() bool {
	return getEmissionState().isEnded(time.Now().Unix())
}

// GetHalvingYear returns the halving year (1-12) for a given timestamp.
func GetHalvingYear(timestamp int64) int64 {
	return getEmissionState().getCurrentYear(timestamp)
}

// GetCurrentYear returns the current halving year (1-12) or 0 if emission is not active.
func GetCurrentYear() int64 {
	return getEmissionState().getCurrentYear(time.Now().Unix())
}

// GetEmissionAmountPerSecondInRange returns halving timestamps and emission rates for the given time range.
// Returns two slices: timestamps when halving periods start and corresponding emission rates per second.
func GetEmissionAmountPerSecondInRange(fromTime, toTime int64) ([]int64, []int64) {
	if fromTime > toTime {
		return nil, nil
	}

	halvingData := getEmissionState().getHalvingData()
	halvingTimes := make([]int64, 0, HALVING_END_YEAR+1)
	halvingEmissions := make([]int64, 0, HALVING_END_YEAR+1)

	for year := HALVING_START_YEAR; year <= HALVING_END_YEAR; year++ {
		startTimestamp := halvingData.getStartTimestamp(year)
		if startTimestamp < fromTime {
			continue
		}

		if toTime < startTimestamp {
			break
		}

		halvingTimes = append(halvingTimes, startTimestamp)
		halvingEmissions = append(halvingEmissions, halvingData.getAmountPerSecond(year))
	}

	emissionEndTimestamp := halvingData.getEndTimestamp(HALVING_END_YEAR)
	if fromTime <= emissionEndTimestamp && emissionEndTimestamp < toTime {
		halvingTimes = append(halvingTimes, gnsmath.SafeAddInt64(emissionEndTimestamp, 1))
		halvingEmissions = append(halvingEmissions, 0)
	}

	return halvingTimes, halvingEmissions
}

// GetEmissionAmountPerSecondByTimestamp returns the emission rate per second for a given timestamp.
// Returns 0 if timestamp is outside emission period.
func GetEmissionAmountPerSecondByTimestamp(timestamp int64) int64 {
	state := getEmissionState()
	year := state.getCurrentYear(timestamp)
	return state.getHalvingYearAmountPerSecond(year)
}

// GetEmissionLeftAmountByTimestamp returns the remaining emission amount for the halving year at given timestamp.
// Returns 0 if timestamp is outside emission period.
func GetEmissionLeftAmountByTimestamp(timestamp int64) int64 {
	state := getEmissionState()
	year := state.getCurrentYear(timestamp)
	return state.getHalvingYearLeftAmount(year)
}

// GetEmissionAccumulatedAmountByTimestamp returns the accumulated emission amount for the halving year at given timestamp.
// Returns 0 if timestamp is outside emission period.
func GetEmissionAccumulatedAmountByTimestamp(timestamp int64) int64 {
	state := getEmissionState()
	year := state.getCurrentYear(timestamp)
	return state.getHalvingYearAccumulatedAmount(year)
}

// GetHalvingYearStartTimestamp returns the start timestamp for the specified halving year.
func GetHalvingYearStartTimestamp(year int64) int64 {
	halvingData := getEmissionState().getHalvingData()
	return halvingData.getStartTimestamp(year)
}

// GetHalvingYearEndTimestamp returns the end timestamp for the specified halving year.
func GetHalvingYearEndTimestamp(year int64) int64 {
	halvingData := getEmissionState().getHalvingData()
	return halvingData.getEndTimestamp(year)
}

// GetHalvingYearMaxAmount returns the maximum token issuance for the specified halving year.
func GetHalvingYearMaxAmount(year int64) int64 {
	halvingData := getEmissionState().getHalvingData()
	return halvingData.getMaxAmount(year)
}

// GetHalvingYearMintAmount returns the amount of tokens minted for the specified halving year.
func GetHalvingYearMintAmount(year int64) int64 {
	halvingData := getEmissionState().getHalvingData()
	return halvingData.getMintedAmount(year)
}

// GetHalvingYearLeftAmount returns the remaining token issuance for the specified halving year.
func GetHalvingYearLeftAmount(year int64) int64 {
	halvingData := getEmissionState().getHalvingData()
	return halvingData.getLeftAmount(year)
}

// GetHalvingYearAccuAmount returns the accumulated token issuance for the specified halving year.
func GetHalvingYearAccuAmount(year int64) int64 {
	halvingData := getEmissionState().getHalvingData()
	return halvingData.getAccumAmount(year)
}

// GetAmountPerSecondPerHalvingYear returns the emission rate per second for the specified halving year.
func GetAmountPerSecondPerHalvingYear(year int64) int64 {
	halvingData := getEmissionState().getHalvingData()
	return halvingData.getAmountPerSecond(year)
}

// GetHalvingAmountsPerYear returns the total emission amount allocated for the specified year.
// Returns 0 if year is outside the valid range (1-12).
func GetHalvingAmountsPerYear(year int64) int64 {
	if validYear(year) != nil {
		return 0
	}
	return halvingAmountsPerYear[year-1]
}

// GetEmissionCreatedHeight returns the block height when emission schedule was created.
func GetEmissionCreatedHeight() int64 {
	return getEmissionState().getCreatedHeight()
}

// GetEmissionStartTimestamp returns the timestamp when emission schedule begins.
func GetEmissionStartTimestamp() int64 {
	return getEmissionState().getStartTimestamp()
}

// GetEmissionEndTimestamp returns the timestamp when emission schedule ends.
func GetEmissionEndTimestamp() int64 {
	return getEmissionState().getEndTimestamp()
}

// GetHalvingYearInfo returns the halving year, start timestamp, and end timestamp for a given timestamp.
// Returns (year, startTimestamp, endTimestamp). Year is 0 if outside emission period.
func GetHalvingYearInfo(timestamp int64) (int64, int64, int64) {
	state := getEmissionState()
	year := state.getCurrentYear(timestamp)

	// If outside emission period, return 0 values
	if year == 0 {
		return 0, 0, 0
	}

	// Use cached timestamps from HalvingData
	halvingData := state.getHalvingData()
	return year, halvingData.getStartTimestamp(year), halvingData.getEndTimestamp(year)
}

// GetHalvingInfo returns a clone of the halving data.
func GetHalvingInfo() *HalvingData {
	return getEmissionState().getHalvingData().Clone()
}

// CalculateMintGnsAmount returns the amount of GNS that would be minted for the given timestamp range.
func CalculateMintGnsAmount(fromTimestamp, toTimestamp int64) int64 {
	state := getEmissionState().Clone()

	amountToMint, err := calculateAmountToMint(state, fromTimestamp, toTimestamp)
	if err != nil {
		return 0
	}

	return amountToMint
}

package gns

import (
	"chain"
	"strings"
	"time"

	"gno.land/p/demo/tokens/grc20"
	ufmt "gno.land/p/nt/ufmt/v0"

	"gno.land/r/demo/defi/grc20reg"
	"gno.land/r/gnoswap/access"

	gnsmath "gno.land/p/gnoswap/gnsmath"
	prabc "gno.land/p/gnoswap/rbac"
	"gno.land/p/gnoswap/utils"
	_ "gno.land/r/gnoswap/rbac"
)

const (
	tokenID             = 0
	MAXIMUM_SUPPLY      = int64(1_000_000_000_000_000)
	INITIAL_MINT_AMOUNT = int64(100_000_000_000_000)
	MAX_EMISSION_AMOUNT = int64(900_000_000_000_000) // MAXIMUM_SUPPLY - INITIAL_MINT_AMOUNT
)

var (
	token         *grc20.Token
	privateLedger *grc20.PrivateLedger
	userTeller    grc20.Teller

	leftEmissionAmount   int64 // amount of GNS can be minted for emission
	mintedEmissionAmount int64 // amount of GNS that has been minted for emission
	lastMintedTimestamp  int64 // last block time that gns was minted for emission
)

func init(cur realm) {
	token, privateLedger = grc20.NewToken("Gnoswap", "GNS", 6, tokenID, cur)
	userTeller = token.CallerTeller()

	adminAddr := access.MustGetAddress(prabc.ROLE_ADMIN.String())
	err := privateLedger.Mint(adminAddr, INITIAL_MINT_AMOUNT)
	if err != nil {
		panic(err.Error())
	}

	grc20reg.Register(cross(cur), token, "")

	// Initial amount set to 900_000_000_000_000 (MAXIMUM_SUPPLY - INITIAL_MINT_AMOUNT).
	// leftEmissionAmount will decrease as tokens are minted.
	setLeftEmissionAmount(MAX_EMISSION_AMOUNT)
	setMintedEmissionAmount(0)
	setLastMintedTimestamp(0)
}

// Name returns the name of the GNS token.
func Name() string { return token.GetName() }

// Symbol returns the symbol of the GNS token.
func Symbol() string { return token.GetSymbol() }

// Decimals returns the number of decimal places for GNS token.
func Decimals() int { return token.GetDecimals() }

// TotalSupply returns the total supply of GNS tokens in circulation.
func TotalSupply() int64 { return token.TotalSupply() }

// KnownAccounts returns the number of addresses that have held GNS.
func KnownAccounts() int { return token.KnownAccounts() }

// BalanceOf returns the GNS balance of a specific address.
func BalanceOf(owner address) int64 { return token.BalanceOf(owner) }

// Allowance returns the amount of GNS that a spender is allowed to transfer from an owner.
func Allowance(owner, spender address) int64 { return token.Allowance(owner, spender) }

// MintGns mints new GNS tokens according to the emission schedule.
//
// Parameters:
//   - address: recipient address for minted tokens
//
// Returns amount minted.
// Only callable by emission contract.
//
// Note: Halt check is performed by the caller (emission.MintAndDistributeGns)
// to allow graceful handling. This function assumes caller has already verified
// halt status before invoking.
func MintGns(cur realm, address address) int64 {
	previousRealm := cur.Previous()
	caller := previousRealm.Address()
	access.AssertIsEmission(caller)

	lastGNSMintedTimestamp := LastMintedTimestamp()
	currentTime := time.Now().Unix()

	// Skip if already minted this timestamp or emission ended.
	if lastGNSMintedTimestamp == currentTime || lastGNSMintedTimestamp >= GetEmissionEndTimestamp() {
		return 0
	}

	amountToMint, err := calculateAmountToMint(getEmissionState(), lastGNSMintedTimestamp+1, currentTime)
	if err != nil {
		panic(err)
	}

	err = validEmissionAmount(amountToMint)
	if err != nil {
		panic(err)
	}

	setLastMintedTimestamp(currentTime)
	setMintedEmissionAmount(gnsmath.SafeAddInt64(MintedEmissionAmount(), amountToMint))
	setLeftEmissionAmount(gnsmath.SafeSubInt64(LeftEmissionAmount(), amountToMint))

	err = privateLedger.Mint(address, amountToMint)
	if err != nil {
		panic(err.Error())
	}

	chain.Emit(
		"MintGNS",
		"prevAddr", caller.String(),
		"prevRealm", previousRealm.PkgPath(),
		"mintedBlockTime", utils.FormatInt(currentTime),
		"mintedGNSAmount", utils.FormatInt(amountToMint),
		"accumMintedGNSAmount", utils.FormatInt(MintedEmissionAmount()),
		"accumLeftMintGNSAmount", utils.FormatInt(LeftEmissionAmount()),
	)

	return amountToMint
}

// Transfer transfers GNS tokens from caller to recipient.
//
// Parameters:
//   - to: recipient address
//   - amount: amount to transfer
func Transfer(cur realm, to address, amount int64) {
	checkErr(userTeller.Transfer(0, cur, to, amount))
}

// Approve allows spender to transfer GNS tokens from caller's account.
//
// Parameters:
//   - spender: address authorized to spend
//   - amount: maximum amount spender can transfer
func Approve(cur realm, spender address, amount int64) {
	checkErr(userTeller.Approve(0, cur, spender, amount))
}

// TransferFrom transfers GNS tokens on behalf of owner.
//
// Parameters:
//   - from: token owner address
//   - to: recipient address
//   - amount: amount to transfer
func TransferFrom(cur realm, from, to address, amount int64) {
	checkErr(userTeller.TransferFrom(0, cur, from, to, amount))
}

// Render returns token information for web interface.
func Render(path string) string {
	parts := strings.Split(path, "/")
	c := len(parts)

	switch {
	case path == "":
		return token.RenderHome()
	case c == 2 && parts[0] == "balance":
		owner := address(parts[1])
		balance := token.BalanceOf(owner)
		return ufmt.Sprintf("%d\n", balance)
	default:
		return "404\n"
	}
}

// checkErr panics if error is not nil.
func checkErr(err error) {
	if err != nil {
		panic(err.Error())
	}
}

// calculateAmountToMint calculates and allocates GNS tokens to mint for given timestamp range.
// This function has side effects: it updates the accumulated and remaining amounts
// for each halving year in the emission state.
func calculateAmountToMint(state *EmissionState, fromTimestamp, toTimestamp int64) (int64, error) {
	// Cache state to avoid repeated lookups
	endTimestamp := state.getEndTimestamp()
	if toTimestamp > endTimestamp {
		toTimestamp = endTimestamp
	}

	if fromTimestamp > toTimestamp {
		return 0, nil
	}

	startTimestamp := state.getStartTimestamp()
	if fromTimestamp < startTimestamp {
		fromTimestamp = startTimestamp
	}

	if toTimestamp < startTimestamp {
		return 0, nil
	}

	fromYear := state.getCurrentYear(fromTimestamp)
	toYear := state.getCurrentYear(toTimestamp)

	if fromYear == 0 || toYear == 0 {
		return 0, nil
	}

	totalAmountToMint := int64(0)

	for year := fromYear; year <= toYear; year++ {
		yearEndTimestamp := state.getHalvingYearEndTimestamp(year)
		currentToTimestamp := i64Min(toTimestamp, yearEndTimestamp)

		seconds := currentToTimestamp - fromTimestamp + 1
		if seconds <= 0 {
			break
		}

		amountPerSecond := state.getHalvingYearAmountPerSecond(year)
		yearAmountToMint := gnsmath.SafeMulInt64(amountPerSecond, seconds)

		if currentToTimestamp >= yearEndTimestamp {
			leftover := gnsmath.SafeSubInt64(state.getHalvingYearLeftAmount(year), yearAmountToMint)
			yearAmountToMint = gnsmath.SafeAddInt64(yearAmountToMint, leftover)
		}

		totalAmountToMint = gnsmath.SafeAddInt64(totalAmountToMint, yearAmountToMint)

		err := state.addHalvingYearAccumulatedAmount(year, yearAmountToMint)
		if err != nil {
			return 0, err
		}

		err = state.subHalvingYearLeftAmount(year, yearAmountToMint)
		if err != nil {
			return 0, err
		}

		fromTimestamp = currentToTimestamp + 1

		if fromTimestamp > toTimestamp {
			break
		}
	}

	return totalAmountToMint, nil
}

// LastMintedTimestamp returns the timestamp of the last GNS emission mint.
func LastMintedTimestamp() int64 { return lastMintedTimestamp }

// LeftEmissionAmount returns the remaining GNS tokens available for emission.
func LeftEmissionAmount() int64 { return leftEmissionAmount }

// MintedEmissionAmount returns the total GNS tokens minted through emission,
// excluding the initial mint amount.
func MintedEmissionAmount() int64 { return mintedEmissionAmount }

// setLastMintedTimestamp sets the timestamp of the last emission mint.
func setLastMintedTimestamp(timestamp int64) { lastMintedTimestamp = timestamp }

// setLeftEmissionAmount sets the remaining emission amount.
func setLeftEmissionAmount(amount int64) { leftEmissionAmount = amount }

// setMintedEmissionAmount sets the total minted emission amount.
func setMintedEmissionAmount(amount int64) { mintedEmissionAmount = amount }

package gns

import (
	gnsmath "gno.land/p/gnoswap/gnsmath"
)

// HalvingData stores emission data for each halving period.
// Contains timestamps, amounts, and rates for the 12-year emission schedule.
type HalvingData struct {
	startTimestamps []int64
	endTimestamps   []int64
	maxAmount       []int64
	mintedAmount    []int64
	leftAmount      []int64
	accumAmount     []int64
	amountPerSecond []int64
}

// getStartTimestamp returns the start timestamp for the specified halving year.
// Returns 0 if year is invalid.
func (h *HalvingData) getStartTimestamp(year int64) int64 {
	if validYear(year) != nil {
		return 0
	}

	return h.startTimestamps[year-1]
}

// getEndTimestamp returns the end timestamp for the specified halving year.
// Returns 0 if year is invalid.
func (h *HalvingData) getEndTimestamp(year int64) int64 {
	if validYear(year) != nil {
		return 0
	}

	return h.endTimestamps[year-1]
}

// getMaxAmount returns the maximum emission amount for the specified halving year.
// Returns 0 if year is invalid.
func (h *HalvingData) getMaxAmount(year int64) int64 {
	if validYear(year) != nil {
		return 0
	}

	return h.maxAmount[year-1]
}

// getMintedAmount returns the amount already minted for the specified halving year.
func (h *HalvingData) getMintedAmount(year int64) int64 {
	if validYear(year) != nil {
		return 0
	}
	return h.mintedAmount[year-1]
}

// getAccumAmount returns the accumulated emission amount for the specified halving year.
func (h *HalvingData) getAccumAmount(year int64) int64 {
	if validYear(year) != nil {
		return 0
	}
	return h.accumAmount[year-1]
}

// getLeftAmount returns the remaining emission amount for the specified halving year.
func (h *HalvingData) getLeftAmount(year int64) int64 {
	if validYear(year) != nil {
		return 0
	}
	return h.leftAmount[year-1]
}

// getAmountPerSecond returns the emission rate per second for the specified halving year.
// Returns 0 if year is invalid.
func (h *HalvingData) getAmountPerSecond(year int64) int64 {
	if validYear(year) != nil {
		return 0
	}
	return h.amountPerSecond[year-1]
}

// setStartTimestamp sets the start timestamp for the specified halving year.
// Returns error if year is invalid.
func (h *HalvingData) setStartTimestamp(year int64, timestamp int64) error {
	err := validYear(year)
	if err != nil {
		return err
	}

	h.startTimestamps[year-1] = timestamp

	return nil
}

// setEndTimestamp sets the end timestamp for the specified halving year.
// Returns error if year is invalid.
func (h *HalvingData) setEndTimestamp(year int64, timestamp int64) error {
	err := validYear(year)
	if err != nil {
		return err
	}

	h.endTimestamps[year-1] = timestamp

	return nil
}

// setMaxAmount sets the maximum emission amount for the specified halving year.
// Returns error if year is invalid.
func (h *HalvingData) setMaxAmount(year, amount int64) error {
	err := validYear(year)
	if err != nil {
		return err
	}

	h.maxAmount[year-1] = amount

	return nil
}

// setMintedAmount sets the minted amount for the specified halving year.
// Returns error if year is invalid.
func (h *HalvingData) setMintedAmount(year, amount int64) error {
	err := validYear(year)
	if err != nil {
		return err
	}

	h.mintedAmount[year-1] = amount

	return nil
}

// setAccumAmount sets the accumulated amount for the specified halving year.
// Returns error if year is invalid.
func (h *HalvingData) setAccumAmount(year, amount int64) error {
	err := validYear(year)
	if err != nil {
		return err
	}

	h.accumAmount[year-1] = amount

	return nil
}

// setLeftAmount sets the remaining amount for the specified halving year.
// Returns error if year is invalid.
func (h *HalvingData) setLeftAmount(year, amount int64) error {
	err := validYear(year)
	if err != nil {
		return err
	}

	h.leftAmount[year-1] = amount

	return nil
}

// addAccumAmount adds to the accumulated amount for the specified halving year.
// Returns error if year is invalid.
func (h *HalvingData) addAccumAmount(year, amount int64) error {
	err := validYear(year)
	if err != nil {
		return err
	}

	h.accumAmount[year-1] = gnsmath.SafeAddInt64(h.accumAmount[year-1], amount)

	return nil
}

// setAmountPerSecond sets the emission rate per second for the specified halving year.
// Returns error if year is invalid.
func (h *HalvingData) setAmountPerSecond(year, amount int64) error {
	err := validYear(year)
	if err != nil {
		return err
	}

	h.amountPerSecond[year-1] = amount

	return nil
}

func (h *HalvingData) Clone() *HalvingData {
	startTimestamps := make([]int64, len(h.startTimestamps))
	endTimestamps := make([]int64, len(h.endTimestamps))
	maxAmount := make([]int64, len(h.maxAmount))
	mintedAmount := make([]int64, len(h.mintedAmount))
	leftAmount := make([]int64, len(h.leftAmount))
	accumAmount := make([]int64, len(h.accumAmount))
	amountPerSecond := make([]int64, len(h.amountPerSecond))

	copy(startTimestamps, h.startTimestamps)
	copy(endTimestamps, h.endTimestamps)
	copy(maxAmount, h.maxAmount)
	copy(mintedAmount, h.mintedAmount)
	copy(leftAmount, h.leftAmount)
	copy(accumAmount, h.accumAmount)
	copy(amountPerSecond, h.amountPerSecond)

	return &HalvingData{
		startTimestamps: startTimestamps,
		endTimestamps:   endTimestamps,
		maxAmount:       maxAmount,
		mintedAmount:    mintedAmount,
		leftAmount:      leftAmount,
		accumAmount:     accumAmount,
		amountPerSecond: amountPerSecond,
	}
}

// NewHalvingData creates a new HalvingData instance with emission schedule.
// Initializes 12 years of halving periods with timestamps, amounts, and rates based on startTimestamp.
func NewHalvingData(startTimestamp int64) *HalvingData {
	halvingData := &HalvingData{
		startTimestamps: make([]int64, HALVING_END_YEAR),
		endTimestamps:   make([]int64, HALVING_END_YEAR),
		maxAmount:       make([]int64, HALVING_END_YEAR),
		mintedAmount:    make([]int64, HALVING_END_YEAR),
		leftAmount:      make([]int64, HALVING_END_YEAR),
		accumAmount:     make([]int64, HALVING_END_YEAR),
		amountPerSecond: make([]int64, HALVING_END_YEAR),
	}

	for year := HALVING_START_YEAR; year <= HALVING_END_YEAR; year++ {
		yearStartTimestamp := startTimestamp + (SECONDS_IN_YEAR * (year - 1))
		yearEndTimestamp := yearStartTimestamp + SECONDS_IN_YEAR - 1
		yearDistributionAmount := GetHalvingAmountsPerYear(year)
		yearAmountPerSecond := yearDistributionAmount / SECONDS_IN_YEAR

		halvingData.setStartTimestamp(year, yearStartTimestamp)
		halvingData.setEndTimestamp(year, yearEndTimestamp)
		halvingData.setMaxAmount(year, yearDistributionAmount)
		halvingData.setMintedAmount(year, 0)
		halvingData.setAccumAmount(year, 0)
		halvingData.setAmountPerSecond(year, yearAmountPerSecond)
		halvingData.setLeftAmount(year, yearDistributionAmount)
	}

	return halvingData
}

package gns

import (
	gnsmath "gno.land/p/gnoswap/gnsmath"
	ufmt "gno.land/p/nt/ufmt/v0"
)

// validYear validates that year is within halving period range (1-12).
// Returns error if year is outside the valid range.
func validYear(year int64) error {
	if year < HALVING_START_YEAR || year > HALVING_END_YEAR {
		return makeErrorWithDetails(errInvalidYear, ufmt.Sprintf("year: %d", year))
	}

	return nil
}

// validEmissionAmount validates that the emission amount does not exceed maximum.
// Returns error if minting the amount would exceed MAX_EMISSION_AMOUNT.
func validEmissionAmount(amount int64) error {
	if amount < 0 {
		return makeErrorWithDetails(errInvalidEmissionAmount, ufmt.Sprintf("emission amount cannot be negative: %d", amount))
	}

	if gnsmath.SafeAddInt64(amount, MintedEmissionAmount()) > MAX_EMISSION_AMOUNT {
		return makeErrorWithDetails(errTooManyEmission, ufmt.Sprintf("too many emission amount: %d", amount))
	}

	return nil
}

// i64Min returns the smaller of two int64 values.
func i64Min(x, y int64) int64 {
	if x < y {
		return x
	}
	return y
}

package gnft

import (
	"gno.land/p/gnoswap/deps/tokens/grc721"
	prabc "gno.land/p/gnoswap/rbac"
	ufmt "gno.land/p/nt/ufmt/v0"
	"gno.land/r/gnoswap/access"
)

// assertIsValidTokenURI panics if the token already has a URI set.
func assertIsValidTokenURI(tid grc721.TokenID) {
	uri, _ := nft.TokenURI(tid)
	if string(uri) != "" {
		panic(makeErrorWithDetails(errCannotSetURI, ufmt.Sprintf("token id (%s) has already set URI", string(tid))))
	}
}

// assertIsNonEmptyTokenURI panics if the new URI is empty.
func assertIsNonEmptyTokenURI(tURI grc721.TokenURI) {
	if string(tURI) == "" {
		panic(makeErrorWithDetails(errCannotSetURI, "empty token URI"))
	}
}

// assertIsValidAddress panics if the address is invalid.
func assertIsValidAddress(addr address) {
	if !addr.IsValid() {
		panic(makeErrorWithDetails(errInvalidAddress, ufmt.Sprintf("address (%s)", addr.String())))
	}
}

// assertFromIsValidAddress panics if the from address is invalid.
func assertFromIsValidAddress(from address) {
	if !from.IsValid() {
		panic(makeErrorWithDetails(errInvalidAddress, ufmt.Sprintf("from address (%s)", from.String())))
	}
}

// assertToIsValidAddress panics if the to address is invalid.
func assertToIsValidAddress(to address) {
	if !to.IsValid() {
		panic(makeErrorWithDetails(errInvalidAddress, ufmt.Sprintf("to address (%s)", to.String())))
	}
}

// assertIsAllowedTransfer enforces that NFTs held
// by the staker (i.e. currently staked) can only be moved by the staker itself.
// Other tokens fall through to the standard GRC721 owner/approval checks performed inside nft.
func assertIsAllowedTransfer(caller address, tid grc721.TokenID) {
	owner, err := nft.OwnerOf(tid)
	if err != nil {
		// Surface the same not-found error as the standard transfer path.
		checkErr(err)
	}

	stakerAddr := access.MustGetAddress(prabc.ROLE_STAKER.String())
	if owner != stakerAddr {
		return
	}

	if caller != stakerAddr {
		panic(makeErrorWithDetails(
			errStakedTokenLocked,
			ufmt.Sprintf("token (%s) is held by staker", string(tid)),
		))
	}
}

// Package gnft implements GRC721-compliant NFTs for GnoSwap LP positions.
//
// Each LP position in GnoSwap is represented as a unique NFT with dynamically
// generated SVG artwork. The contract manages ownership, transfers, and visual
// representation of positions while minimizing storage costs.
package gnft

package gnft

import (
	ufmt "gno.land/p/nt/ufmt/v0"
)

const (
	errCannotSetURI   = "[GNOSWAP-GNFT-001] cannot set URI"
	errInvalidAddress = "[GNOSWAP-GNFT-002] invalid address"

	// Transfer errors
	errNotOwnerOrApproved = "[GNOSWAP-GNFT-003] caller is not token owner or approved"
	errTokenNotExists     = "[GNOSWAP-GNFT-004] token does not exist"
	errTransferToSelf     = "[GNOSWAP-GNFT-005] cannot transfer to self"

	errInvalidTokenParams      = "[GNOSWAP-GNFT-006] invalid token parameters"
	errInvalidTokenParamsRange = "[GNOSWAP-GNFT-007] token parameters out of range"
	errInvalidColorFormat      = "[GNOSWAP-GNFT-008] invalid color format"
	errStakedTokenLocked       = "[GNOSWAP-GNFT-009] staked token is locked"
	errSpoofedRealm            = "[GNOSWAP-GNFT-010] rlm does not match the current crossing frame"
)

// makeErrorWithDetails creates an error with additional context.
func makeErrorWithDetails(message string, details string) error {
	return ufmt.Errorf("%s || %s", message, details)
}

package gnft

import (
	"chain"
	"errors"

	"gno.land/p/gnoswap/deps/tokens/grc721"
	ufmt "gno.land/p/nt/ufmt/v0"
	"gno.land/r/gnoswap/access"

	prabc "gno.land/p/gnoswap/rbac"
	_ "gno.land/r/gnoswap/rbac"
)

var nft *grc721.BasicNFT

func init(cur realm) {
	nft = grc721.NewBasicNFT(0, cur, "GNOSWAP NFT", "GNFT")
}

// Name returns the NFT collection name.
func Name() string {
	return nft.Name()
}

// Symbol returns the NFT symbol.
func Symbol() string {
	return nft.Symbol()
}

// TotalSupply returns the total number of NFTs minted.
func TotalSupply() int64 {
	return nft.TokenCount()
}

// TokenURI returns the metadata URI for the specified token ID.
// If stored value is in parameter format (x1,y1,x2,y2,color1,color2),
// it converts to full base64-encoded SVG image URI on read.
func TokenURI(tid grc721.TokenID) (string, error) {
	stored, err := nft.TokenURI(tid)
	if err != nil {
		return "", err
	}

	params, err := parseImageParams(stored)
	if err == nil {
		return params.generateImageURI(tid), nil
	}

	return stored, nil
}

// BalanceOf returns the number of NFTs owned by the specified address.
func BalanceOf(owner address) (int64, error) {
	assertIsValidAddress(owner)
	return nft.BalanceOf(owner)
}

// OwnerOf returns the owner address for the specified token ID.
func OwnerOf(tid grc721.TokenID) (address, error) {
	return nft.OwnerOf(tid)
}

// MustOwnerOf returns the owner address for the specified token ID.
// It panics if the token ID is invalid.
func MustOwnerOf(tid grc721.TokenID) address {
	ownerAddr, err := nft.OwnerOf(tid)
	checkErr(err)
	return ownerAddr
}

// SetTokenURI sets the metadata URI for the specified token.
//
// Parameters:
//   - tid: token ID
//   - tURI: token URI
//
// Only callable by position contract.
func SetTokenURI(cur realm, tid grc721.TokenID, tURI grc721.TokenURI) (bool, error) {
	caller := cur.Previous().Address()
	access.AssertIsPosition(caller)

	assertIsNonEmptyTokenURI(tURI)
	assertIsValidTokenURI(tid)

	checkErr(setTokenURI(0, cur, tid, tURI))

	return true, nil
}

// SafeTransferFrom transfers token ownership with receiver validation.
//
// Parameters:
//   - from: current owner address
//   - to: recipient address
//   - tid: token ID to transfer
//
// Returns error if transfer fails.
//
// Permission model:
//   - Tokens held by the staker contract (i.e. currently staked) can only be
//     moved by the staker itself; the underlying staked LP position is
//     non-transferable.
//   - Otherwise, ownership and approval are enforced by the GRC721 layer
//     (owner / approved-for-token / approved-for-all).
func SafeTransferFrom(cur realm, from, to address, tid grc721.TokenID) error {
	assertFromIsValidAddress(from)
	assertToIsValidAddress(to)
	caller := cur.Previous().Address()
	assertIsAllowedTransfer(caller, tid)

	err := nft.SafeTransferFrom(caller, from, to, tid)
	checkTransferErr(err, caller, from, to, tid)
	return nil
}

// TransferFrom transfers a token from one address to another.
//
// Parameters:
//   - from: current owner address
//   - to: recipient address
//   - tid: token ID
//
// Returns error if transfer fails.
//
// Permission model:
//   - Tokens held by the staker contract (i.e. currently staked) can only be
//     moved by the staker itself; the underlying staked LP position is
//     non-transferable.
//   - Otherwise, ownership and approval are enforced by the GRC721 layer
//     (owner / approved-for-token / approved-for-all).
func TransferFrom(cur realm, from, to address, tid grc721.TokenID) error {
	assertFromIsValidAddress(from)
	assertToIsValidAddress(to)
	caller := cur.Previous().Address()
	assertIsAllowedTransfer(caller, tid)

	err := nft.TransferFrom(caller, from, to, tid)
	checkTransferErr(err, caller, from, to, tid)
	return nil
}

// Approve grants permission to transfer a specific token ID to another address.
//
// Parameters:
//   - approved: address to approve
//   - tid: token ID to approve for transfer
//
// Returns error if approval fails.
func Approve(cur realm, approved address, tid grc721.TokenID) error {
	assertIsValidAddress(approved)

	caller := cur.Previous().Address()
	err := nft.Approve(caller, approved, tid)
	checkApproveErr(err, caller, approved, tid)
	return nil
}

// SetApprovalForAll enables/disables operator approval for all tokens.
//
// Parameters:
//   - operator: address to set approval for
//   - approved: true to approve, false to revoke
//
// Returns error if operation fails.
func SetApprovalForAll(cur realm, operator address, approved bool) error {
	assertIsValidAddress(operator)

	checkErr(nft.SetApprovalForAll(cur.Previous().Address(), operator, approved))
	return nil
}

// GetApproved returns approved address for token ID.
//
// Parameters:
//   - tid: token ID to check
//
// Returns approved address and error if token doesn't exist.
func GetApproved(tid grc721.TokenID) (address, error) {
	return nft.GetApproved(tid)
}

// IsApprovedForAll checks if operator can manage all owner's tokens.
//
// Parameters:
//   - owner: token owner address
//   - operator: operator address to check
//
// Returns true if operator is approved for all owner's tokens.
func IsApprovedForAll(owner, operator address) bool {
	return nft.IsApprovedForAll(owner, operator)
}

// Mint creates new NFT and transfers to address.
//
// Parameters:
//   - to: recipient address
//   - tid: token ID
//
// Returns minted token ID.
// Only callable by position contract.
func Mint(cur realm, to address, tid grc721.TokenID) grc721.TokenID {
	caller := cur.Previous().Address()
	access.AssertIsPosition(caller)

	positionAddr := access.MustGetAddress(prabc.ROLE_POSITION.String())
	checkErr(nft.Mint(positionAddr, tid))

	// Store only the gradient parameters instead of full base64 SVG to reduce storage costs.
	// Parameters are converted to full SVG on read via TokenURI().
	imageParams := genImageParamsString(generateRandInstance())
	checkErr(setTokenURI(0, cur, tid, grc721.TokenURI(imageParams)))

	checkErr(nft.TransferFrom(positionAddr, positionAddr, to, tid))

	return tid
}

// Exists checks if token ID exists.
func Exists(tid grc721.TokenID) bool {
	_, err := nft.OwnerOf(tid)
	return err == nil
}

// Burn removes a specific token ID.
//
// Parameters:
//   - tid: token ID to burn
//
// Only callable by position.
func Burn(cur realm, tid grc721.TokenID) {
	caller := cur.Previous().Address()
	access.AssertIsPosition(caller)

	checkErr(nft.Burn(tid))
}

// Render returns the HTML representation of the NFT.
func Render(path string) string {
	if path == "" {
		return nft.RenderHome()
	}
	return "404\n"
}

// setTokenURI sets the metadata URI for a specific token ID.
func setTokenURI(_ int, rlm realm, tid grc721.TokenID, tURI grc721.TokenURI) error {
	if !rlm.IsCurrent() {
		return errors.New(errSpoofedRealm)
	}

	previousRealm := rlm.Previous()
	previousAddr := previousRealm.Address()

	_, err := nft.SetTokenURI(previousAddr, tid, tURI)
	if err != nil {
		return makeErrorWithDetails(err.Error(), ufmt.Sprintf("token id (%s)", tid))
	}
	tokenURI, err := TokenURI(tid)
	if err != nil {
		return makeErrorWithDetails(err.Error(), ufmt.Sprintf("token id (%s)", tid))
	}

	chain.Emit(
		"SetTokenURI",
		"prevAddr", previousAddr.String(),
		"prevRealm", previousRealm.PkgPath(),
		"tokenId", string(tid),
		"tokenURI", tokenURI,
	)

	return nil
}

package gnft

import (
	b64 "encoding/base64"
	"errors"
	"math/rand"
	"strconv"
	"strings"

	"gno.land/p/gnoswap/deps/tokens/grc721"
	ufmt "gno.land/p/nt/ufmt/v0"
)

// MUST BE IMMUTABLE, DO NOT MODIFY.
// SVG template structure:
// The template is split at variable insertion points for efficient string concatenation.
// Full template with placeholders (for reference):
//
//	<svg width="135" height="135" viewBox="0 0 135 135" fill="none" xmlns="...">
//	  <g clip-path="url(#clip0_7698_56846)">
//	    <circle cx="67.5" cy="67.5" r="67.5" fill="url(#paint0_linear_7698_56846)"/>
//	    ... (path elements) ...
//	  </g>
//	  <defs>
//	    <linearGradient id="paint0_linear_7698_56846"
//	      x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}"   <-- variables
//	      gradientUnits="userSpaceOnUse">
//	      <stop stop-color="{color1}"/>             <-- variable
//	      <stop offset="1" stop-color="{color2}"/>  <-- variable
//	    </linearGradient>
//	    ...
//	  </defs>
//	</svg>

// svgTemplate holds pre-split template parts for efficient concatenation.
// Usage: svgTemplate[0] + clipID + svgTemplate[1] + paintID + ... + color2 + svgTemplate[10]
var svgTemplate = [11]string{
	// [0] SVG header and body (before clip-path id)
	`<svg width="135" height="135" viewBox="0 0 135 135" fill="none" xmlns="http://www.w3.org/2000/svg">
<g clip-path="url(#`,
	// [1] between clip-path id and fill id
	`)">
<circle cx="67.5" cy="67.5" r="67.5" fill="url(#`,
	// [2] between fill id and gradient id
	`)"/>
<path d="M51.2905 42.9449L66.4895 33L97 52.8061L81.8241 62.7425L51.2905 42.9449Z" fill="white"/>
<path d="M51.6055 67.5059L66.8044 57.561L97 77.0657L82.1046 87.1793L51.6055 67.5059Z" fill="white" fill-opacity="0.4"/>
<path d="M36.0464 81.7559L51.2905 71.811L81.7336 91.6547L66.4895 101.508L36.0464 81.7559Z" fill="white" fill-opacity="0.6"/>
<path d="M36.001 52.8055L51.2884 42.9177L51.2884 71.8145L36.001 81.779L36.001 52.8055Z" fill="white"/>
<path d="M82.1051 87.1797L97.0016 77.0662L97.0016 81.7029L81.7896 91.629L82.1051 87.1797Z" fill="white" fill-opacity="0.5"/>
</g>
<defs>
<linearGradient id="`,
	// [3] between gradient id and x1
	`" x1="`,
	// [4] between x1 and y1
	`" y1="`,
	// [5] between y1 and x2
	`" x2="`,
	// [6] between x2 and y2
	`" y2="`,
	// [7] between y2 and color1
	`" gradientUnits="userSpaceOnUse">
<stop stop-color="`,
	// [8] between color1 and color2
	`"/>
<stop offset="1" stop-color="`,
	// [9] between color2 and clipPath id
	`"/>
</linearGradient>
<clipPath id="`,
	// [10] SVG footer (after clipPath id)
	`">
<rect width="135" height="135" fill="white"/>
</clipPath>
</defs>
</svg>
`,
}

// charset contains valid hex digits for color generation.
const charset = "0123456789ABCDEF"

// Parameter range constants for gradient coordinates.
const (
	x1Min = 7
	x1Max = 13
	y1Min = 7
	y1Max = 13
	x2Min = 121
	x2Max = 126
	y2Min = 121
	y2Max = 126

	x1Range = x1Max - x1Min + 1
	y1Range = y1Max - y1Min + 1
	x2Range = x2Max - x2Min + 1
	y2Range = y2Max - y2Min + 1
)

// genImageParamsString generates random gradient parameters and returns them as a compact string.
// Format: "x1,y1,x2,y2,color1,color2" (e.g., "10,12,125,123,#AABBCC,#DDEEFF")
func genImageParamsString(r *rand.Rand) string {
	x1 := x1Min + r.Uint64N(x1Range)
	y1 := y1Min + r.Uint64N(y1Range)
	x2 := x2Min + r.Uint64N(x2Range)
	y2 := y2Min + r.Uint64N(y2Range)

	var buf1 [7]byte
	var buf2 [7]byte
	buf1[0] = '#'
	buf2[0] = '#'
	for i := 1; i < 7; i++ {
		buf1[i] = charset[r.IntN(16)]
		buf2[i] = charset[r.IntN(16)]
	}
	color1 := string(buf1[:])
	color2 := string(buf2[:])

	return strconv.Itoa(int(x1)) + "," + strconv.Itoa(int(y1)) + "," +
		strconv.Itoa(int(x2)) + "," + strconv.Itoa(int(y2)) + "," +
		color1 + "," + color2
}

// ImageParams holds parsed and validated image parameters.
type ImageParams struct {
	x1, y1, x2, y2 int
	color1, color2 string
}

// validateCoordinate checks if a coordinate value is within valid range.
// Returns error with details about which coordinate failed if out of range.
func validateCoordinate(value int, min int, max int, name string) error {
	if value < min || value > max {
		details := ufmt.Sprintf("%s=%d (expected range: [%d, %d])", name, value, min, max)
		return makeErrorWithDetails(errInvalidTokenParamsRange, details)
	}
	return nil
}

// parseImageParams parses and validates parameters in one step.
// Returns parsed ImageParams pointer or error.
// Returns nil on error to avoid allocating zero-value struct.
// Expected format: "x1,y1,x2,y2,color1,color2"
func parseImageParams(s string) (*ImageParams, error) {
	parts := strings.Split(s, ",")
	if len(parts) != 6 {
		return nil, errors.New(errInvalidTokenParams)
	}

	x1, err := strconv.Atoi(parts[0])
	if err != nil {
		return nil, errors.New(errInvalidTokenParams)
	}

	y1, err := strconv.Atoi(parts[1])
	if err != nil {
		return nil, errors.New(errInvalidTokenParams)
	}

	x2, err := strconv.Atoi(parts[2])
	if err != nil {
		return nil, errors.New(errInvalidTokenParams)
	}

	y2, err := strconv.Atoi(parts[3])
	if err != nil {
		return nil, errors.New(errInvalidTokenParams)
	}

	// Validate coordinate ranges with detailed error messages
	if err := validateCoordinate(x1, x1Min, x1Max, "x1"); err != nil {
		return nil, err
	}
	if err := validateCoordinate(y1, y1Min, y1Max, "y1"); err != nil {
		return nil, err
	}
	if err := validateCoordinate(x2, x2Min, x2Max, "x2"); err != nil {
		return nil, err
	}
	if err := validateCoordinate(y2, y2Min, y2Max, "y2"); err != nil {
		return nil, err
	}

	color1 := parts[4]
	color2 := parts[5]

	// Validate color format (#XXXXXX)
	if !isValidHexColor(color1) || !isValidHexColor(color2) {
		return nil, errors.New(errInvalidColorFormat)
	}

	return &ImageParams{
		x1:     x1,
		y1:     y1,
		x2:     x2,
		y2:     y2,
		color1: color1,
		color2: color2,
	}, nil
}

// generateImageURI converts parsed image parameters to a base64-encoded SVG image URI.
func (params ImageParams) generateImageURI(tid grc721.TokenID) string {
	svg := params.generateSVG(tid)
	sEnc := b64.StdEncoding.EncodeToString([]byte(svg))

	return "data:image/svg+xml;base64," + sEnc
}

// generateSVG generates SVG image from parsed and validated parameters.
func (params ImageParams) generateSVG(tid grc721.TokenID) string {
	suffix := svgIDSuffix(tid)
	paintID := "paint0_linear_" + suffix
	clipID := "clip0_" + suffix
	return svgTemplate[0] + clipID + svgTemplate[1] + paintID + svgTemplate[2] + paintID +
		svgTemplate[3] + strconv.Itoa(params.x1) + svgTemplate[4] + strconv.Itoa(params.y1) +
		svgTemplate[5] + strconv.Itoa(params.x2) + svgTemplate[6] + strconv.Itoa(params.y2) +
		svgTemplate[7] + params.color1 + svgTemplate[8] + params.color2 + svgTemplate[9] +
		clipID + svgTemplate[10]
}

func svgIDSuffix(tid grc721.TokenID) string {
	return "gnft_" + string(tid)
}

// isValidHexColor checks if a string is a valid hex color in #XXXXXX format.
func isValidHexColor(color string) bool {
	if len(color) != 7 || color[0] != '#' {
		return false
	}

	for i := 1; i < 7; i++ {
		c := color[i]

		isHex := (c >= '0' && c <= '9') || (c >= 'A' && c <= 'F') || (c >= 'a' && c <= 'f')
		if !isHex {
			return false
		}
	}

	return true
}

package gnft

import (
	"errors"
	"math/rand"
	"time"

	"gno.land/p/gnoswap/deps/tokens/grc721"
	ufmt "gno.land/p/nt/ufmt/v0"
)

// generateRandInstance generates a new random instance.
func generateRandInstance() *rand.Rand {
	now := time.Now()
	seed1 := now.Unix() + TotalSupply()
	seed2 := now.UnixNano() + TotalSupply()
	pcg := rand.NewPCG(uint64(seed1), uint64(seed2))
	return rand.New(pcg)
}

// checkErr panics if an error occurs.
func checkErr(err error) {
	if err != nil {
		panic(err.Error())
	}
}

// checkTransferErr wraps transfer errors with more specific context.
func checkTransferErr(err error, caller, from, to address, tid grc721.TokenID) {
	if err == nil {
		return
	}

	// Check if token exists
	owner, ownerErr := nft.OwnerOf(tid)
	if ownerErr != nil {
		panic(ownerErr)
	}

	switch err {
	case grc721.ErrCallerIsNotOwnerOrApproved:
		// Check if caller is the owner
		if caller == owner {
			panic(makeErrorWithDetails(grc721.ErrTransferFromIncorrectOwner.Error(), ufmt.Sprintf("owner mismatch - from: %s, actual owner: %s, token: %s", from, owner, string(tid))))
		}

		// Check if caller is approved for this specific token
		approved, _ := nft.GetApproved(tid)
		if approved != caller {
			// Check if caller is approved for all tokens
			if !nft.IsApprovedForAll(owner, caller) {
				panic(makeErrorWithDetails(grc721.ErrCallerIsNotOwnerOrApproved.Error(), ufmt.Sprintf("caller %s is not owner %s or approved for token %s", caller, owner, string(tid))))
			}
		}

	case grc721.ErrInvalidAddress:
		panic(makeErrorWithDetails(grc721.ErrInvalidAddress.Error(), ufmt.Sprintf("to address (%s)", to)))

	case grc721.ErrTransferFromIncorrectOwner:
		panic(makeErrorWithDetails(grc721.ErrTransferFromIncorrectOwner.Error(), ufmt.Sprintf("from %s is not the owner %s of token %s", from, owner, string(tid))))

	case grc721.ErrInvalidTokenId:
		panic(makeErrorWithDetails(grc721.ErrInvalidTokenId.Error(), ufmt.Sprintf("token %s", string(tid))))

	default:
		panic(err.Error())
	}
}

// checkApproveErr wraps approve errors with more specific context.
func checkApproveErr(err error, caller, approved address, tid grc721.TokenID) {
	if err == nil {
		return
	}

	switch {
	case errors.Is(err, grc721.ErrInvalidTokenId):
		panic(makeErrorWithDetails(errTokenNotExists, ufmt.Sprintf("token %s", string(tid))))

	case errors.Is(err, grc721.ErrCallerIsNotOwnerOrApproved):
		owner, ownerErr := nft.OwnerOf(tid)
		checkErr(ownerErr)
		panic(makeErrorWithDetails(errNotOwnerOrApproved, ufmt.Sprintf("caller %s cannot approve for token %s owned by %s", caller, string(tid), owner)))

	case errors.Is(err, grc721.ErrApprovalToCurrentOwner):
		panic(makeErrorWithDetails(errTransferToSelf, ufmt.Sprintf("cannot approve to current owner %s for token %s", approved, string(tid))))

	default:
		panic(err.Error())
	}
}

// Package xgns implements the GRC20-compliant xGNS token that represents
// staked GNS tokens. It manages minting/burning operations and tracks
// voting power for governance.
package xgns

package xgns

import (
	"chain"
	"errors"
	"strings"

	"gno.land/p/demo/tokens/grc20"
	ownable "gno.land/p/nt/ownable/v0"
	ufmt "gno.land/p/nt/ufmt/v0"

	"gno.land/r/gnoswap/access"
	"gno.land/r/gnoswap/halt"

	prbac "gno.land/p/gnoswap/rbac"
)

const tokenID = 0

var (
	admin = ownable.NewWithAddress(chain.PackageAddress(prbac.ROLE_GOV_STAKER.String()))

	token  *grc20.Token
	ledger *grc20.PrivateLedger
)

func init(cur realm) {
	token, ledger = grc20.NewToken("XGNS", "xGNS", 6, tokenID, cur)
}

// TotalSupply returns the total supply of xGNS tokens.
func TotalSupply() int64 {
	return token.TotalSupply()
}

// BalanceOf returns token balance for address.
//
// Parameters:
//   - owner: address to check balance for
//
// Returns balance amount.
func BalanceOf(owner address) int64 {
	return token.BalanceOf(owner)
}

// Render returns a formatted representation of the token state.
func Render(path string) string {
	if path == "" {
		return token.RenderHome()
	}

	parts := strings.Split(path, "/")
	switch parts[0] {
	case "balance":
		if len(parts) != 2 {
			return "404\n"
		}
		balance := token.BalanceOf(address(parts[1]))
		return ufmt.Sprintf("%d\n", balance)
	default:
		return "404\n"
	}
}

// Mint mints tokens to address.
//
// Parameters:
//   - to: recipient address
//   - amount: amount to mint
//
// Only callable by governance staker contract.
func Mint(cur realm, to address, amount int64) {
	halt.AssertIsNotHaltedXGns()

	caller := cur.Previous().Address()
	access.AssertIsGovStaker(caller)

	checkErr(ledger.Mint(to, amount))
}

// Burn burns tokens from address.
//
// Parameters:
//   - from: address to burn from
//   - amount: amount to burn
//
// Only callable by governance staker contract.
func Burn(cur realm, from address, amount int64) {
	halt.AssertIsNotHaltedWithdraw()

	caller := cur.Previous().Address()
	access.AssertIsGovStaker(caller)

	checkErr(ledger.Burn(from, amount))
}

// SupplyInfo returns supply breakdown information.
//
// Returns:
//   - totalIssued: total xGNS tokens issued
//   - issuedByDelegate: tokens issued through governance delegation
//   - issuedByDepositGns: tokens issued through launchpad deposit
//   - error: error if launchpad address not found
func SupplyInfo() (totalIssued, issuedByDelegate, issuedByDepositGns int64, err error) {
	launchpad, ok := access.GetAddress(prbac.ROLE_LAUNCHPAD.String())
	if !ok {
		return 0, 0, 0, errors.New("launchpad address not found")
	}

	totalIssued = token.TotalSupply()
	issuedByDepositGns = token.BalanceOf(launchpad)
	issuedByDelegate = totalIssued - issuedByDepositGns

	return totalIssued, issuedByDelegate, issuedByDepositGns, nil
}

func checkErr(err error) {
	if err != nil {
		panic(err)
	}
}

