	ufmt "gno.land/p/nt/ufmt/v0"

	u256 "gno.land/p/gnoswap/uint256"
)

// ProtocolFeeRewardManager manages the distribution of protocol fee rewards to stakers.
// Unlike emission rewards, protocol fees can come from multiple tokens, requiring
// separate tracking and distribution mechanisms for each token type.
type ProtocolFeeRewardManager struct {
	// rewardStates maps address to ProtocolFeeRewardState for tracking individual staker rewards
	rewardStates *bptree.BPTree // address -> ProtocolFeeRewardState

	// accumulatedProtocolFeeX128PerStake maps token path to accumulated fee per stake with 128-bit precision
	accumulatedProtocolFeeX128PerStake map[string]*u256.Uint
	// protocolFeeAmounts maps token path to total distributed protocol fee amounts
	protocolFeeAmounts map[string]int64
	// accumulatedTimestamp tracks the last timestamp when fees were accumulated
	accumulatedTimestamp int64
	// totalStakedAmount tracks the total amount of tokens staked in the system
	totalStakedAmount int64
}

// NewProtocolFeeRewardManager creates a new instance of ProtocolFeeRewardManager.
// This factory function initializes all tracking structures for multi-token protocol fee reward management.
//
// Returns:
//   - *ProtocolFeeRewardManager: new protocol fee reward manager instance
func NewProtocolFeeRewardManager() *ProtocolFeeRewardManager {
	return &ProtocolFeeRewardManager{
		rewardStates:                       bptree.NewBPTreeN(16),
		protocolFeeAmounts:                 make(map[string]int64),
		accumulatedProtocolFeeX128PerStake: make(map[string]*u256.Uint),
		accumulatedTimestamp:               0,
		totalStakedAmount:                  0,
	}
}

/* Getters */

func (p *ProtocolFeeRewardManager) GetRewardState(addr string) (*ProtocolFeeRewardState, bool, error) {
	ri := p.rewardStates.Get(addr)
	if ri == nil {
		return nil, false, nil
	}
	rs, castOk := ri.(*ProtocolFeeRewardState)
	if !castOk {
		return nil, false, ufmt.Errorf(errFailedToCastRewardState, ri)
	}
	return rs, true, nil
}

// GetAccumulatedProtocolFeeX128PerStake returns the accumulated protocol fee per stake for a specific token.
//
// Parameters:
//   - token: token path to get accumulated fee for
//
// Returns:
//   - *u256.Uint: accumulated protocol fee per stake for the token (scaled by 2^128)
func (p *ProtocolFeeRewardManager) GetAccumulatedProtocolFeeX128PerStake(token string) *u256.Uint {
	return p.accumulatedProtocolFeeX128PerStake[token]
}

func (p *ProtocolFeeRewardManager) GetProtocolFeeAmounts() map[string]int64 {
	return p.protocolFeeAmounts
}

// GetAccumulatedTimestamp returns the last timestamp when protocol fees were accumulated.
//
// Returns:
//   - int64: last accumulated timestamp
func (p *ProtocolFeeRewardManager) GetAccumulatedTimestamp() int64 {
	return p.accumulatedTimestamp
}

func (p *ProtocolFeeRewardManager) GetTotalStakedAmount() int64 {
	return p.totalStakedAmount
}

/* Setters */

func (p *ProtocolFeeRewardManager) SetRewardStates(rewardStates *bptree.BPTree) {
	p.rewardStates = rewardStates
}

func (p *ProtocolFeeRewardManager) SetAccumulatedProtocolFeeX128PerStake(accumulatedProtocolFeeX128PerStake map[string]*u256.Uint) {
	copied := make(map[string]*u256.Uint, len(accumulatedProtocolFeeX128PerStake))
	for token, value := range accumulatedProtocolFeeX128PerStake {
		copied[token] = u256.Zero().Set(value)
	}
	p.accumulatedProtocolFeeX128PerStake = copied
}

func (p *ProtocolFeeRewardManager) SetProtocolFeeAmounts(protocolFeeAmounts map[string]int64) {
	copied := make(map[string]int64, len(protocolFeeAmounts))
	for token, amount := range protocolFeeAmounts {
		copied[token] = amount
	}
	p.protocolFeeAmounts = copied
}

func (p *ProtocolFeeRewardManager) SetAccumulatedProtocolFeeX128PerStakeForToken(token string, value *u256.Uint) {
	if p.accumulatedProtocolFeeX128PerStake == nil {
		p.accumulatedProtocolFeeX128PerStake = make(map[string]*u256.Uint)
	}
	p.accumulatedProtocolFeeX128PerStake[token] = u256.Zero().Set(value)
}

func (p *ProtocolFeeRewardManager) SetProtocolFeeAmountForToken(token string, amount int64) {
	if p.protocolFeeAmounts == nil {
		p.protocolFeeAmounts = make(map[string]int64)
	}
	p.protocolFeeAmounts[token] = amount
}

func (p *ProtocolFeeRewardManager) SetAccumulatedTimestamp(accumulatedTimestamp int64) {
	p.accumulatedTimestamp = accumulatedTimestamp
}

func (p *ProtocolFeeRewardManager) SetTotalStakedAmount(totalStakedAmount int64) {
	p.totalStakedAmount = totalStakedAmount
}

// GetAllAccumulatedProtocolFeeX128PerStake returns all accumulated protocol fees per stake
func (p *ProtocolFeeRewardManager) GetAllAccumulatedProtocolFeeX128PerStake() map[string]*u256.Uint {
	return p.accumulatedProtocolFeeX128PerStake
}

// GetProtocolFeeAmount returns the protocol fee amount for a specific token
func (p *ProtocolFeeRewardManager) GetProtocolFeeAmount(token string) int64 {
	return p.protocolFeeAmounts[token]
}

// SetRewardState sets the reward state for a specific address
func (p *ProtocolFeeRewardManager) SetRewardState(address string, rewardState *ProtocolFeeRewardState) {
	p.rewardStates.Set(address, rewardState)
}

package staker

import (
	u256 "gno.land/p/gnoswap/uint256"
)

// ProtocolFeeRewardState tracks protocol fee reward information for an individual staker across multiple tokens.
// Unlike emission rewards which are single-token, protocol fees can come from various trading pairs,
// requiring separate tracking and calculation for each token type.
type ProtocolFeeRewardState struct {
	// rewardDebtX128 maps token path to reward debt with 128-bit precision scaling
	// Used to calculate rewards earned since the last update for each token
	rewardDebtX128 map[string]*u256.Uint
	// accumulatedRewards maps token path to total rewards accumulated but not yet claimed
	accumulatedRewards map[string]int64
	// claimedRewards maps token path to total amount of rewards that have been claimed
	claimedRewards map[string]int64
	// accumulatedTimestamp is the last timestamp when rewards were accumulated
	accumulatedTimestamp int64
	// claimedTimestamp is the last timestamp when rewards were claimed
	claimedTimestamp int64
	// stakedAmount is the current amount of tokens staked by this address
	stakedAmount int64
}

func (p *ProtocolFeeRewardState) GetRewardDebtX128() map[string]*u256.Uint {
	return p.rewardDebtX128
}

func (p *ProtocolFeeRewardState) GetAccumulatedRewards() map[string]int64 {
	return p.accumulatedRewards
}

func (p *ProtocolFeeRewardState) GetClaimedRewards() map[string]int64 {
	return p.claimedRewards
}

func (p *ProtocolFeeRewardState) GetAccumulatedTimestamp() int64 {
	return p.accumulatedTimestamp
}

func (p *ProtocolFeeRewardState) GetClaimedTimestamp() int64 {
	return p.claimedTimestamp
}

func (p *ProtocolFeeRewardState) GetStakedAmount() int64 {
	return p.stakedAmount
}

/* Setters */

// SetRewardDebtX128 stores a copy of the given map. Copying into a map
// allocated by this domain method keeps the stored map owned by
// /r/gnoswap/gov/staker, so later per-token writes (SetRewardDebtX128ForToken)
// from any realm clear the cross-realm write guard. Storing the caller's map
// directly would leave the map stamped with the caller's realm.
func (p *ProtocolFeeRewardState) SetRewardDebtX128(rewardDebtX128 map[string]*u256.Uint) {
	copied := make(map[string]*u256.Uint, len(rewardDebtX128))
	for token, value := range rewardDebtX128 {
		copied[token] = u256.Zero().Set(value)
	}
	p.rewardDebtX128 = copied
}

func (p *ProtocolFeeRewardState) SetAccumulatedRewards(accumulatedRewards map[string]int64) {
	copied := make(map[string]int64, len(accumulatedRewards))
	for token, value := range accumulatedRewards {
		copied[token] = value
	}
	p.accumulatedRewards = copied
}

func (p *ProtocolFeeRewardState) SetClaimedRewards(claimedRewards map[string]int64) {
	copied := make(map[string]int64, len(claimedRewards))
	for token, value := range claimedRewards {
		copied[token] = value
	}
	p.claimedRewards = copied
}

func (p *ProtocolFeeRewardState) SetAccumulatedTimestamp(accumulatedTimestamp int64) {
	p.accumulatedTimestamp = accumulatedTimestamp
}

func (p *ProtocolFeeRewardState) SetClaimedTimestamp(claimedTimestamp int64) {
	p.claimedTimestamp = claimedTimestamp
}

func (p *ProtocolFeeRewardState) SetStakedAmount(stakedAmount int64) {
	p.stakedAmount = stakedAmount
}

// Additional getters for individual token rewards

func (p *ProtocolFeeRewardState) GetRewardDebtX128ForToken(token string) *u256.Uint {
	if p.rewardDebtX128 == nil {
		return nil
	}
	return p.rewardDebtX128[token]
}

func (p *ProtocolFeeRewardState) GetAccumulatedRewardForToken(token string) int64 {
	if p.accumulatedRewards == nil {
		return 0
	}
	return p.accumulatedRewards[token]
}

func (p *ProtocolFeeRewardState) GetClaimedRewardForToken(token string) int64 {
	if p.claimedRewards == nil {
		return 0
	}
	return p.claimedRewards[token]
}

// Additional setters for individual token rewards

func (p *ProtocolFeeRewardState) SetRewardDebtX128ForToken(token string, value *u256.Uint) {
	if p.rewardDebtX128 == nil {
		p.rewardDebtX128 = make(map[string]*u256.Uint)
	}
	p.rewardDebtX128[token] = u256.Zero().Set(value)
}

func (p *ProtocolFeeRewardState) SetAccumulatedRewardForToken(token string, value int64) {
	if p.accumulatedRewards == nil {
		p.accumulatedRewards = make(map[string]int64)
	}
	p.accumulatedRewards[token] = value
}

func (p *ProtocolFeeRewardState) SetClaimedRewardForToken(token string, value int64) {
	if p.claimedRewards == nil {
		p.claimedRewards = make(map[string]int64)
	}
	p.claimedRewards[token] = value
}

// NewProtocolFeeRewardState creates a new protocol fee reward state for a staker.
// This factory function initializes the state with the current system reward debt for all tokens.
func NewProtocolFeeRewardState(accumulatedProtocolFeeX128PerStake map[string]*u256.Uint) *ProtocolFeeRewardState {
	rewardDebtX128 := make(map[string]*u256.Uint)

	// Clone reward debt for each token to avoid reference issues
	for token, accumulatedFee := range accumulatedProtocolFeeX128PerStake {
		rewardDebtX128[token] = accumulatedFee.Clone()
	}

	return &ProtocolFeeRewardState{
		rewardDebtX128:       rewardDebtX128,
		claimedRewards:       make(map[string]int64),
		accumulatedRewards:   make(map[string]int64),
		stakedAmount:         0,
		accumulatedTimestamp: 0,
		claimedTimestamp:     0,
	}
}

