package governance

// ProposalStatusType represents the current status of a proposal in its lifecycle.
// These statuses determine what actions are available for a proposal.
type ProposalStatusType int

const (
	_                ProposalStatusType = iota
	StatusUpcoming                      // Proposal created but voting hasn't started yet
	StatusActive                        // Proposal is in voting period
	StatusPassed                        // Proposal has passed but hasn't been executed (or is text proposal)
	StatusRejected                      // Proposal failed to meet voting requirements
	StatusExecutable                    // Proposal can be executed (passed and in execution window)
	StatusExecuted                      // Proposal has been successfully executed
	StatusExpired                       // Proposal execution window has passed
	StatusCanceled                      // Proposal has been canceled
)

// String returns the string representation of ProposalStatusType for display purposes.
//
// Returns:
//   - string: human-readable status name
func (s ProposalStatusType) String() string {
	switch s {
	case StatusUpcoming:
		return "upcoming"
	case StatusActive:
		return "active"
	case StatusPassed:
		return "passed"
	case StatusRejected:
		return "rejected"
	case StatusExecutable:
		return "executable"
	case StatusExecuted:
		return "executed"
	case StatusExpired:
		return "expired"
	case StatusCanceled:
		return "canceled"
	default:
		return "unknown"
	}
}

// ProposalStatus manages the complete status of a proposal including scheduling, voting, and actions.
// This is the central status tracking structure that coordinates different aspects of proposal state.
type ProposalStatus struct {
	schedule     *ProposalScheduleStatus // Time-based scheduling information
	actionStatus *ProposalActionStatus   // Execution and cancellation status
	voteStatus   *ProposalVoteStatus     // Voting tallies and requirements
}

func NewProposalStatusBy(
	schedule *ProposalScheduleStatus,
	actionStatus *ProposalActionStatus,
	voteStatus *ProposalVoteStatus,
) *ProposalStatus {
	return &ProposalStatus{
		schedule:     schedule,
		actionStatus: actionStatus,
		voteStatus:   voteStatus,
	}
}

/* Getter methods */
func (s *ProposalStatus) Schedule() *ProposalScheduleStatus   { return s.schedule }
func (s *ProposalStatus) ActionStatus() *ProposalActionStatus { return s.actionStatus }
func (s *ProposalStatus) VoteStatus() *ProposalVoteStatus     { return s.voteStatus }

/* Delegation getters for vote data */

// YesWeight returns the total weight of "yes" votes.
//
// Returns:
//   - int64: total "yes" vote weight
func (s *ProposalStatus) YesWeight() int64 {
	return s.voteStatus.YesWeight()
}

// NoWeight returns the total weight of "no" votes.
//
// Returns:
//   - int64: total "no" vote weight
func (s *ProposalStatus) NoWeight() int64 {
	return s.voteStatus.NoWeight()
}

// Clone creates a deep copy of the ProposalStatus.
func (s *ProposalStatus) Clone() *ProposalStatus {
	if s == nil {
		return nil
	}

	return &ProposalStatus{
		schedule:     s.schedule.Clone(),
		actionStatus: s.actionStatus.Clone(),
		voteStatus:   s.voteStatus.Clone(),
	}
}

package governance

// ProposalType defines the different types of proposals supported by the governance system.
// Each type has different execution behavior and validation requirements.
type ProposalType string

const (
	Text               ProposalType = "TEXT"                 // Informational proposals for community discussion
	CommunityPoolSpend ProposalType = "COMMUNITY_POOL_SPEND" // Proposals to spend community pool funds
	ParameterChange    ProposalType = "PARAMETER_CHANGE"     // Proposals to modify system parameters
)

// String returns the human-readable string representation of the proposal type.
func (p ProposalType) String() string {
	switch p {
	case Text:
		return "Text"
	case CommunityPoolSpend:
		return "CommunityPoolSpend"
	case ParameterChange:
		return "ParameterChange"
	default:
		return "Unknown"
	}
}

// IsExecutable determines whether this proposal type can be executed.
// Text proposals are informational only and cannot be executed.
func (p ProposalType) IsExecutable() bool {
	switch p {
	case Text:
		return false
	case CommunityPoolSpend, ParameterChange:
		return true
	default:
		return false
	}
}

package governance

// ProposalVoteStatus tracks the voting tallies and requirements for a proposal.
// This structure manages vote counting, quorum calculation, and voting outcome determination.
type ProposalVoteStatus struct {
	yea             int64 // Total weight of "yes" votes collected
	nay             int64 // Total weight of "no" votes collected
	maxVotingWeight int64 // The max voting weight at the time of proposal creation
	quorumAmount    int64 // How many total votes must be collected for the proposal to be valid
}

/* Getter methods */
func (p *ProposalVoteStatus) MaxVotingWeight() int64 { return p.maxVotingWeight }
func (p *ProposalVoteStatus) QuorumAmount() int64    { return p.quorumAmount }

// YesWeight returns the total weight of "yes" votes.
//
// Returns:
//   - int64: total "yes" vote weight
func (p *ProposalVoteStatus) YesWeight() int64 {
	return p.yea
}

// NoWeight returns the total weight of "no" votes.
//
// Returns:
//   - int64: total "no" vote weight
func (p *ProposalVoteStatus) NoWeight() int64 {
	return p.nay
}

/* Setter methods */
func (p *ProposalVoteStatus) SetYesWeight(yes int64) {
	p.yea = yes
}

func (p *ProposalVoteStatus) SetNoWeight(no int64) {
	p.nay = no
}

func (p *ProposalVoteStatus) SetMaxVotingWeight(maxVotingWeight int64) {
	p.maxVotingWeight = maxVotingWeight
}

func (p *ProposalVoteStatus) SetQuorumAmount(quorumAmount int64) {
	p.quorumAmount = quorumAmount
}

// NewProposalVoteStatus creates a new vote status for a proposal.
// Initializes vote tallies to zero and calculates the quorum requirement.
//
// Parameters:
//   - maxVotingWeight: maximum possible voting weight for this proposal
//   - quorumAmount: quorum amount required for passage
//
// Returns:
//   - *ProposalVoteStatus: new vote status instance
func NewProposalVoteStatus(
	maxVotingWeight int64,
	quorumAmount int64,
) *ProposalVoteStatus {
	return &ProposalVoteStatus{
		yea:             0,               // Start with no "yes" votes
		nay:             0,               // Start with no "no" votes
		maxVotingWeight: maxVotingWeight, // Set maximum possible votes
		quorumAmount:    quorumAmount,    // Set required votes for passage
	}
}

// Clone creates a deep copy of the ProposalVoteStatus.
func (p *ProposalVoteStatus) Clone() *ProposalVoteStatus {
	if p == nil {
		return nil
	}

	return &ProposalVoteStatus{
		yea:             p.yea,
		nay:             p.nay,
		maxVotingWeight: p.maxVotingWeight,
		quorumAmount:    p.quorumAmount,
	}
}

